public.sync_audit_columns().definition:
CREATE OR REPLACE FUNCTION public.sync_audit_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_TABLE_SCHEMA = 'public'
    AND TG_TABLE_NAME = 'outbound_shipments'
    AND (to_jsonb(NEW)->'status') IS NOT DISTINCT FROM (to_jsonb(OLD)->'status')
    AND (to_jsonb(NEW)->'status_changed_at') IS DISTINCT FROM (to_jsonb(OLD)->'status_changed_at')
    AND (to_jsonb(NEW) - 'status_changed_at')
      IS NOT DISTINCT FROM (to_jsonb(OLD) - 'status_changed_at') THEN
    RETURN NEW;
  END IF;

  NEW.updated_at = now();
  NEW.version = OLD.version + 1;
  IF auth.uid() IS NOT NULL THEN
    NEW.updated_by = auth.uid();
  END IF;
  RETURN NEW;
END;
$function$

public.erp_read_waca_snapshot().definition:
CREATE OR REPLACE FUNCTION public.erp_read_waca_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_state public.waca_state%rowtype;
begin
  if v_actor is null or not public.is_owner(v_actor) then
    raise exception using errcode='42501',message='WACA_OWNER_REQUIRED';
  end if;
  select * into v_state from public.waca_state limit 1;
  return jsonb_build_object(
    'revision',coalesce(v_state.revision,0),
    'orders',coalesce((select jsonb_agg(payload order by order_key) from public.waca_orders),'[]'::jsonb),
    'items',coalesce((select jsonb_agg(jsonb_set(payload,'{productVariantId}',
      to_jsonb(coalesce(product_variant_id::text,'')),true) order by item_key)
      from public.waca_order_items),'[]'::jsonb),
    'mappings',coalesce((select jsonb_agg(jsonb_set(payload,'{productVariantId}',
      to_jsonb(product_variant_id::text),true) order by feature)
      from public.waca_mappings),'[]'::jsonb),
    'batches',coalesce((select jsonb_agg(payload order by created_at,id) from public.waca_import_batches),'[]'::jsonb),
    'masterLinks',coalesce((select jsonb_agg(jsonb_set(payload,'{productVariantId}',
      to_jsonb(coalesce(product_variant_id::text,'')),true) order by child_code)
      from public.waca_master_links),'[]'::jsonb),
    'cutoverAudit',coalesce((select jsonb_agg(jsonb_set(payload,'{productVariantId}',
      to_jsonb(product_variant_id::text),true) order by product_variant_id)
      from public.waca_cutover_audit),'[]'::jsonb),
    'cutoverState',case when v_state.id is null then null else v_state.payload end
  );
end;
$function$

public.erp_waca_variant_id(text).definition:
CREATE OR REPLACE FUNCTION public.erp_waca_variant_id(p_identity text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_ids uuid[];
begin
  if p_identity is null or btrim(p_identity) = '' then return null; end if;
  select array_agg(v.id) into v_ids from public.product_variants v
   where v.local_id = p_identity or v.id::text = p_identity;
  if coalesce(cardinality(v_ids),0) <> 1 then
    raise exception using errcode='23503', message='WACA_VARIANT_IDENTITY_NOT_UNIQUE_OR_MISSING';
  end if;
  return v_ids[1];
end;
$function$

public.update_updated_at_column().definition:
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$

public.erp_restore_upload_owner(uuid).definition:
CREATE OR REPLACE FUNCTION public.erp_restore_upload_owner(p_request_id uuid)
 RETURNS erp_restore_upload_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE r public.erp_restore_upload_requests%rowtype;
BEGIN
 IF auth.uid() IS NULL OR NOT public.is_owner(auth.uid()) THEN
  RAISE EXCEPTION USING errcode='42501',message='CLOUD_RESTORE_OWNER_REQUIRED'; END IF;
 IF split_part(lower(coalesce(nullif(current_setting('request.headers',true),'')::jsonb->>'host','')),'.',1)<>'rhfdjsklfrgpoqsaqpkn' THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_TARGET_MISMATCH'; END IF;
 SELECT * INTO r FROM public.erp_restore_upload_requests
  WHERE request_id=p_request_id AND actor_key=encode(extensions.digest(auth.uid()::text,'sha256'),'hex');
 IF NOT FOUND OR r.expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_NOT_FOUND'; END IF;
 RETURN r;
END;
$function$

public.erp_plan_waca_recognition(jsonb).definition:
CREATE OR REPLACE FUNCTION public.erp_plan_waca_recognition(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  actor uuid:=auth.uid(); revision bigint; epoch bigint; driven boolean; choice jsonb;
  i public.waca_order_items%rowtype; o public.waca_orders%rowtype; v public.product_variants%rowtype;
  before_q integer; after_q integer; source_q integer; old_mode text; mode text;
  lines jsonb:='[]'; quantities jsonb:='[]'; delta integer; ledger_q integer; request_hash text;
begin
  if actor is null or not public.is_owner(actor) then raise exception using errcode='42501',message='WACA_OWNER_REQUIRED'; end if;
  if jsonb_typeof(p_request) is distinct from 'object'
    or coalesce(p_request->>'requestId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or coalesce(p_request->>'revision','') !~ '^[0-9]+$' or coalesce(p_request->>'restoreEpoch','') !~ '^[0-9]+$'
    or length(btrim(coalesce(p_request->>'reason','')))=0 or length(p_request->>'reason')>500
    or jsonb_typeof(p_request->'choices') is distinct from 'array' then
    raise exception using errcode='22023',message='WACA_RECOGNITION_REQUEST_INVALID';
  end if;
  if jsonb_array_length(p_request->'choices') not between 1 and 500
    or (select count(distinct c->>'itemKey') from jsonb_array_elements(p_request->'choices') c)
      <>jsonb_array_length(p_request->'choices') then
    raise exception using errcode='22023',message='WACA_RECOGNITION_CHOICES_INVALID';
  end if;
  select s.revision,s.mode='ORDER_DRIVEN_ACTIVE' into revision,driven from public.waca_state s
    where id='00000000-0000-4000-8000-000000000001';
  select e.epoch into epoch from public.erp_cloud_restore_epoch e where singleton;
  if revision is distinct from (p_request->>'revision')::bigint then raise exception using errcode='40001',message='WACA_STALE_REVISION'; end if;
  if epoch is distinct from (p_request->>'restoreEpoch')::bigint then raise exception using errcode='40001',message='WACA_RESTORE_EPOCH_CHANGED'; end if;
  if not coalesce(driven,false) then raise exception using errcode='23000',message='WACA_RECOGNITION_REQUIRES_COUNTED_LEDGER'; end if;
  request_hash:=encode(extensions.digest(p_request::text,'sha256'),'hex');
  for choice in select value from jsonb_array_elements(p_request->'choices') order by value->>'itemKey' loop
    mode:=choice->>'mode';
    if mode is null or mode not in ('COUNT','INCLUDED','HOLD') then raise exception using errcode='22023',message='WACA_RECOGNITION_MODE_INVALID'; end if;
    select * into i from public.waca_order_items where item_key=choice->>'itemKey';
    if not found then raise exception using errcode='23503',message='WACA_RECOGNITION_ITEM_MISSING'; end if;
    select * into o from public.waca_orders where id=i.order_id;
    if o.order_key is distinct from p_request->>'orderKey' or i.product_variant_id is null then
      raise exception using errcode='23000',message='WACA_RECOGNITION_IDENTITY_INVALID';
    end if;
    select * into v from public.product_variants where id=i.product_variant_id and deleted_at is null;
    if not found then raise exception using errcode='23503',message='WACA_RECOGNITION_VARIANT_MISSING'; end if;
    source_q:=case when o.status in ('處理中','完成付款') then i.quantity else 0 end;
    if mode='COUNT' and o.status not in ('處理中','完成付款') then
      raise exception using errcode='23000',message='WACA_INACTIVE_ORDER_NOT_COUNTABLE';
    end if;
    before_q:=coalesce((i.payload->>'countedQuantity')::integer,source_q);
    old_mode:=coalesce(i.payload->'recognition'->>'mode',case when i.payload->>'countedReason'='BASELINE_INCLUDED' then 'INCLUDED'
      when before_q>0 or i.payload->>'countedReason' in ('NORMAL_IMPORT','OWNER_CONFIRMED_NEW','SOURCE_CHANGE_APPLIED','OVERWRITE','LEGACY_COUNTED') then 'COUNT' else 'HOLD' end);
    after_q:=case when mode='COUNT' then source_q else 0 end;
    -- A same-setting/no-difference operation creates neither receipt nor revision.
    if old_mode=mode and before_q=after_q and (i.payload->>'countedReview' is null
      or mode='HOLD' and i.payload->>'countedReview'='OWNER_HOLD') then continue; end if;
    if before_q<0 or after_q<before_q and (
      coalesce(i.payload->>'countedReason','') not in ('NORMAL_IMPORT','OWNER_CONFIRMED_NEW','SOURCE_CHANGE_APPLIED')
      or not public.erp_waca_reversal_proven(v.id,epoch,i.item_key)) then
      raise exception using errcode='23000',message='WACA_REVERSAL_PROOF_REQUIRED',detail=i.item_key;
    end if;
    lines:=lines||jsonb_build_array(jsonb_build_object('itemKey',i.item_key,'orderKey',o.order_key,
      'variantId',v.id,'sku',v.myacg_item_code,'sourceQuantity',i.quantity,'sourceStatus',o.status,
      'beforeMode',old_mode,'mode',mode,'countedBefore',before_q,'countedAfter',after_q,'delta',after_q-before_q,
      'previousDecision',i.payload->'recognition','previousReason',i.payload->>'countedReason','previousCountedBy',i.payload->>'countedBy'));
  end loop;
  for v in select pv.* from public.product_variants pv where pv.id in
    (select (x->>'variantId')::uuid from jsonb_array_elements(lines) x) order by pv.id loop
    select sum((x->>'delta')::integer)::integer into delta from jsonb_array_elements(lines) x where x->>'variantId'=v.id::text;
    select coalesce(sum(i2.quantity) filter(where o2.status in ('處理中','完成付款')),0)::integer into ledger_q
      from public.waca_order_items i2 join public.waca_orders o2 on o2.id=i2.order_id where i2.product_variant_id=v.id;
    if ledger_q<>v.waca_auto_quantity then raise exception using errcode='23000',message='WACA_RECOGNITION_LEDGER_MISMATCH'; end if;
    if v.waca_auto_quantity+v.waca_manual_adjustment+delta<0 then raise exception using errcode='23514',message='WACA_COUNTED_NEGATIVE_DISPLAY'; end if;
    quantities:=quantities||jsonb_build_array(jsonb_build_object('variantId',v.id,'sku',v.myacg_item_code,'version',v.version,
      'autoBefore',v.waca_auto_quantity,'manualBefore',v.waca_manual_adjustment,
      'before',v.waca_auto_quantity+v.waca_manual_adjustment,'after',v.waca_auto_quantity+v.waca_manual_adjustment+delta,'delta',delta,
      'reversibleItemKeys',public.erp_waca_reversal_keys(v.id,epoch)));
  end loop;
  return jsonb_build_object('contract','waca-recognition-v1','requestId',p_request->>'requestId','requestHash',request_hash,
    'revision',revision,'restoreEpoch',epoch,'orderKey',p_request->>'orderKey','reason',p_request->>'reason','lines',lines,'quantities',quantities);
end;
$function$

public.erp_finalize_restore_upload(uuid).definition:
CREATE OR REPLACE FUNCTION public.erp_finalize_restore_upload(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '25s'
 SET work_mem TO '16MB'
AS $function$
DECLARE r public.erp_restore_upload_requests%rowtype;d jsonb;a jsonb;i jsonb;result jsonb;resource_name text;
 profiles jsonb;columns_by_resource jsonb;bytes bigint;rows bigint;payload_hash text;relationship_hash text;
 transformed bigint;policy text;source_fp text;started timestamptz:=clock_timestamp();phase text:='authorization';
 assembled timestamptz;resource_timings jsonb;phase_at timestamptz:=started;phase_timings jsonb:='{}';
BEGIN
 r:=public.erp_restore_upload_owner(p_request_id);
 IF NOT pg_try_advisory_xact_lock(hashtextextended('erp-restore-upload:'||p_request_id::text,0)) THEN
  RAISE EXCEPTION USING errcode='55006',message='CLOUD_RESTORE_UPLOAD_BUSY'; END IF;
 IF r.completed_result IS NOT NULL THEN RETURN r.completed_result; END IF;
 IF r.source_generation IS DISTINCT FROM (SELECT generation FROM public.erp_restore_business_generation WHERE singleton)
  OR r.source_epoch IS DISTINCT FROM (SELECT epoch FROM public.erp_cloud_restore_epoch WHERE singleton) THEN
  RAISE EXCEPTION USING errcode='55000',message='STALE_RESTORE_PREPARE'; END IF;
 phase_timings:=phase_timings||jsonb_build_object('authorization',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();phase:='resource-stage';
 -- Backward-compatible older clients use the same bounded stages, never a full
 -- 24 MB aggregate. New clients stage resources with bounded concurrency.
 FOR resource_name IN SELECT jsonb_object_keys(r.manifest->'counts') LOOP
  IF NOT EXISTS(SELECT 1 FROM public.erp_restore_upload_resource_proofs WHERE request_id=p_request_id AND resource=resource_name) THEN
   PERFORM public.erp_stage_restore_upload_resource(p_request_id,resource_name); END IF;
 END LOOP;
 IF (SELECT count(*) FROM public.erp_restore_upload_resource_proofs WHERE request_id=p_request_id)<>24
  OR EXISTS(SELECT 1 FROM public.erp_restore_upload_resource_proofs rp WHERE rp.request_id=p_request_id
   AND (rp.profile->>'count')::bigint IS DISTINCT FROM (r.manifest->'counts'->>rp.resource)::bigint) THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_INCOMPLETE'; END IF;
 phase_timings:=phase_timings||jsonb_build_object('resourceCoverage',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();phase:='validation-input';
 SELECT json_object_agg(resource,validation_rows) FILTER(WHERE r.restore_mode='cross-environment'
   OR resource IN('product_variants','outbound_shipments','import_batches','waca_orders','waca_order_items','waca_mappings','waca_master_links','waca_import_batches','waca_cutover_audit','waca_state'))::jsonb,jsonb_object_agg(resource,profile),
  jsonb_object_agg(resource,supplied_columns),sum(transformed_rows),jsonb_object_agg(resource,server_ms)
 INTO d,profiles,columns_by_resource,transformed,resource_timings
 FROM public.erp_restore_upload_resource_proofs WHERE request_id=p_request_id;
 assembled:=clock_timestamp();
 phase_timings:=phase_timings||jsonb_build_object('validationInput',(extract(epoch FROM assembled-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();phase:='portability';
 IF r.restore_mode='cross-environment' THEN
  policy:='cross-environment-audit-null-v1';source_fp:=r.manifest->'portability'->>'sourceSnapshotFingerprint';
  IF r.manifest->'portability'->>'mode' IS DISTINCT FROM 'cross-environment'
   OR transformed IS DISTINCT FROM (r.manifest->'portability'->>'totalTransformedRows')::bigint
   OR EXISTS(SELECT 1 FROM public.erp_restore_upload_resource_proofs rp WHERE rp.request_id=p_request_id
    AND rp.transformed_rows IS DISTINCT FROM (r.manifest->'portability'->'transformedCounts'->>rp.resource)::bigint) THEN
   RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PORTABILITY_TRANSFORM_COUNT_MISMATCH'; END IF;
  PERFORM public.erp_cloud_restore_validate_portability(d,r.manifest,'rhfdjsklfrgpoqsaqpkn');
 ELSIF r.restore_mode='strict' AND NOT(r.manifest ? 'portability') THEN
  policy:='strict';source_fp:=r.manifest->>'snapshotFingerprint';
 ELSE RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_POLICY_INVALID'; END IF;
 phase_timings:=phase_timings||jsonb_build_object('portability',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();phase:='waca-validation';
 PERFORM public.erp_cloud_restore_validate_waca_dataset(d);
 phase_timings:=phase_timings||jsonb_build_object('wacaValidation',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();phase:='projected-semantic-proof';
 -- Exact erp_cloud_restore_audit_dataset and erp_cloud_restore_relationship_hash
 -- representations are combined over SERVER resource proofs, never client hashes.
 a:=public.erp_restore_upload_semantic_audit(p_request_id);i:=a->'integrity';
 -- Keep BOTH contracts: the public manifest hash and Execute's staged proof
 -- hash use different canonical representations. Neither can replace the other.
 relationship_hash:=a->>'execute_relationship_hash';
 phase_timings:=phase_timings||jsonb_build_object('projectedSemanticProof',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();phase:='manifest-validation';
 IF r.manifest->'counts' IS DISTINCT FROM a->'table_counts'
  OR (r.manifest->>'totalRows')::bigint IS DISTINCT FROM (a->>'total_rows')::bigint
  OR r.manifest->>'relationshipHash' IS DISTINCT FROM a->>'relationship_hash'
  OR (r.manifest->>'orphanCount')::bigint IS DISTINCT FROM (i->>'orphan_count')::bigint
  OR (r.manifest->>'duplicateVariantIdCount')::bigint IS DISTINCT FROM (i->>'duplicate_variant_id_count')::bigint
  OR (r.manifest->>'duplicateVariantLocalIdCount')::bigint IS DISTINCT FROM (i->>'duplicate_variant_local_id_count')::bigint
  OR (r.manifest->>'duplicateCanonicalIdCount')::bigint IS DISTINCT FROM (i->>'duplicate_canonical_id_count')::bigint
  OR (r.manifest->>'canonicalIdentityAnomalyCount')::bigint IS DISTINCT FROM (i->>'canonical_identity_anomaly_count')::bigint
  OR (r.manifest->>'unknownProductCount')::bigint IS DISTINCT FROM (i->>'unknown_product_count')::bigint
  OR (r.manifest->>'optionalMetadataMissingReferenceCount')::bigint IS DISTINCT FROM (i->>'optional_metadata_missing_reference_count')::bigint
  OR (i->>'duplicate_inventory_key_count')::bigint<>0 OR (i->>'missing_inventory_key_count')::bigint<>0 THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_CANDIDATE_INVALID'; END IF;
 phase_timings:=phase_timings||jsonb_build_object('manifestValidation',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();phase:='prepared-chunk-proof';
 SELECT coalesce(sum(row_count),0),coalesce(sum(pg_column_size(ch.rows)),0),
  encode(extensions.digest(convert_to(coalesce(string_agg(resource||':'||chunk_ordinal||':'||ch.payload_hash,E'\n'
   ORDER BY resource COLLATE "C",chunk_ordinal),''),'UTF8'),'sha256'),'hex')
 INTO rows,bytes,payload_hash FROM public.erp_cloud_restore_prepared_chunks ch WHERE proof_id=p_request_id;
 IF rows IS DISTINCT FROM (a->>'total_rows')::bigint THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_STAGE_ROW_COUNT_MISMATCH'; END IF;
 IF r.source_generation IS DISTINCT FROM (SELECT generation FROM public.erp_restore_business_generation WHERE singleton)
  OR r.source_epoch IS DISTINCT FROM (SELECT epoch FROM public.erp_cloud_restore_epoch WHERE singleton) THEN
  RAISE EXCEPTION USING errcode='55000',message='STALE_RESTORE_PREPARE'; END IF;
 phase_timings:=phase_timings||jsonb_build_object('preparedChunkProof',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();phase:='proof-write';
 result:=jsonb_build_object('ok',true,'candidate_valid',true,'schema_version','cloud-restore-candidate-proof-v1',
  'policy',policy,'resource_count',24,'coverage_count',24,'total_rows',rows,'table_counts',a->'table_counts',
  'transformed_updated_by_count',transformed,'source_fingerprint',source_fp,
  'effective_fingerprint',r.manifest->>'snapshotFingerprint','relationship_hash',a->>'relationship_hash','integrity',i,
  'proof_id',p_request_id,'proof_expires_at',r.expires_at,'request_id',p_request_id,
  'prepared_row_count',rows,'prepared_byte_count',bytes,'prepared_payload_hash',payload_hash,
  'uploadAssemblyMs',(extract(epoch FROM assembled-started)*1000)::bigint,
  'finalizeServerMs',(extract(epoch FROM clock_timestamp()-started)*1000)::bigint,
  'resourceStageTimingsMs',resource_timings,'validationProjectionBytes',pg_column_size(d),
  'phaseTimingsMs',phase_timings,'semanticProofRepresentation','server-resource-proofs-v1',
  'statementTimeout',current_setting('statement_timeout'),
  'prepareTimingsMs',jsonb_build_object('semanticProof',(extract(epoch FROM clock_timestamp()-assembled)*1000)::bigint),
  'elapsed_ms',(extract(epoch FROM clock_timestamp()-started)*1000)::bigint);
 UPDATE public.erp_cloud_restore_candidate_proofs SET proof_result=result,expected_profiles=profiles,
  prepared_columns=columns_by_resource,prepared_row_count=rows,prepared_byte_count=bytes,prepared_payload_hash=payload_hash,
  expected_relationship_hash=relationship_hash,source_generation=r.source_generation,source_restore_epoch=r.source_epoch
 WHERE proof_id=p_request_id AND actor_key=r.actor_key;
 UPDATE public.erp_restore_upload_requests SET completed_result=result WHERE request_id=p_request_id;
 phase:='request-cleanup';
 DELETE FROM public.erp_restore_upload_chunks WHERE request_id=p_request_id;
 DELETE FROM public.erp_restore_upload_resource_proofs WHERE request_id=p_request_id;
 phase_timings:=phase_timings||jsonb_build_object('proofWriteAndCleanup',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 result:=result||jsonb_build_object('phaseTimingsMs',phase_timings,
  'finalizeServerMs',(extract(epoch FROM clock_timestamp()-started)*1000)::bigint,
  'elapsed_ms',(extract(epoch FROM clock_timestamp()-started)*1000)::bigint);
 UPDATE public.erp_cloud_restore_candidate_proofs SET proof_result=result WHERE proof_id=p_request_id AND actor_key=r.actor_key;
 UPDATE public.erp_restore_upload_requests SET completed_result=result WHERE request_id=p_request_id;
 RETURN result;
EXCEPTION WHEN query_canceled THEN
 RAISE EXCEPTION USING errcode='57014',message='CLOUD_RESTORE_PREPARE_TIMEOUT',
  detail=jsonb_build_object('phase',phase,'requestId',p_request_id,'reasonCode','CLOUD_RESTORE_PREPARE_TIMEOUT')::text;
END;
$function$

public.erp_assert_cloud_restore_unlocked.definition:
CREATE OR REPLACE FUNCTION public.erp_assert_cloud_restore_unlocked()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if current_setting('erp.cloud_restore_active', true) = 'on' then
    return null;
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock', 0)) then
    raise exception using errcode = '55006', message = 'CLOUD_RESTORE_MAINTENANCE_LOCKED';
  end if;
  return null;
end;
$function$

public.erp_set_outbound_status_changed_a.definition:
CREATE OR REPLACE FUNCTION public.erp_set_outbound_status_changed_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_table_owner name;
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.status_changed_at := clock_timestamp();
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    NEW.status_changed_at := clock_timestamp();
  ELSIF NEW.status_changed_at IS DISTINCT FROM OLD.status_changed_at THEN
    SELECT pg_catalog.pg_get_userbyid(c.relowner)
      INTO v_table_owner
      FROM pg_catalog.pg_class c
     WHERE c.oid = TG_RELID;
    IF current_user IS DISTINCT FROM v_table_owner THEN
      RAISE EXCEPTION USING errcode = '42501',
        message = 'OUTBOUND_STATUS_TIMESTAMP_SYSTEM_MANAGED';
    END IF;
  ELSE
    NEW.status_changed_at := OLD.status_changed_at;
  END IF;
  RETURN NEW;
END;
$function$

public.erp_apply_field_mutations(text,js.definition:
CREATE OR REPLACE FUNCTION public.erp_apply_field_mutations(p_entity text, p_operations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_table regclass;
  v_create_allowed text[];
  v_patch_allowed text[];
  v_reorder_allowed text[] := ARRAY[]::text[];
  v_operation jsonb;
  v_kind text;
  v_id uuid;
  v_current jsonb;
  v_values jsonb;
  v_changes jsonb;
  v_expected jsonb;
  v_keys text[];
  v_key text;
  v_set_sql text;
  v_columns_sql text;
  v_values_sql text;
  v_result_row jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_conflicts jsonb;
  v_expected_version integer;
  v_seen_ids text[] := ARRAY[]::text[];
  v_protected constant text[] := ARRAY[
    'id', 'created_at', 'updated_at', 'updated_by', 'version', 'deleted_at', 'sync_status'
  ];
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_editor(auth.uid()) THEN
    RAISE EXCEPTION 'CLOUD_FIELD_CAS_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_operations) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'CLOUD_FIELD_CAS_OPERATIONS_MUST_BE_ARRAY' USING ERRCODE = '22023';
  END IF;

  -- Both table and fields are resolved exclusively from this server-owned whitelist.
  CASE p_entity
    WHEN 'product_groups' THEN
      v_table := 'public.product_groups'::regclass;
      v_create_allowed := ARRAY['local_id','title','normalized_title','listing_type','priority','purchase_date','closing_date','release_month','has_official_site','product_url','proxy_agent','show_in_purchase_list'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
    WHEN 'product_categories' THEN
      v_table := 'public.product_categories'::regclass;
      v_create_allowed := ARRAY['local_id','product_group_id','title','sort_order'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
      v_reorder_allowed := ARRAY['sort_order'];
    WHEN 'product_variants' THEN
      v_table := 'public.product_variants'::regclass;
      v_create_allowed := ARRAY['local_id','product_group_id','product_category_id','myacg_item_code','product_title','variant_name','raw_variant_name','myacg_auto_quantity','effective_myacg_quantity','myacg_manual_adjustment','waca_auto_quantity','waca_manual_adjustment','private_manual_adjustment','purchased_manual_adjustment','note','sort_order','catalog_missing','source','default_jpy_cost','default_twd_cost'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
      v_reorder_allowed := ARRAY['sort_order'];
    WHEN 'inventory_items' THEN
      v_table := 'public.inventory_items'::regclass;
      v_create_allowed := ARRAY['inventory_key','myacg_item_code','myacg_parent_code','product_id','product_title','normalized_product_title','raw_variant_name','listing_type','final_price','myacg_available_quantity','myacg_sold_quantity','myacg_demand_quantity','myacg_listed_at','import_sort_index','latest_catalog_import_id','catalog_last_seen_at'];
      v_patch_allowed := v_create_allowed;
    WHEN 'purchase_batches' THEN
      v_table := 'public.purchase_batches'::regclass;
      v_create_allowed := ARRAY['local_id','product_group_id','name','date','note','currency'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
    WHEN 'purchase_batch_items' THEN
      v_table := 'public.purchase_batch_items'::regclass;
      v_create_allowed := ARRAY['local_id','purchase_batch_id','product_variant_id','quantity','cost','note'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
    WHEN 'private_orders' THEN
      v_table := 'public.private_orders'::regclass;
      v_create_allowed := ARRAY['local_id','product_group_id','customer_name','contact','note','status'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
    WHEN 'private_order_items' THEN
      v_table := 'public.private_order_items'::regclass;
      v_create_allowed := ARRAY['local_id','private_order_id','product_variant_id','quantity','amount','note'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
    WHEN 'japan_packages' THEN
      v_table := 'public.japan_packages'::regclass;
      v_create_allowed := ARRAY['title','vendor_name','carrier','tracking_number','shipped_at','expected_arrival_at','arrived_at','status','note'];
      v_patch_allowed := v_create_allowed;
    WHEN 'japan_package_items' THEN
      v_table := 'public.japan_package_items'::regclass;
      v_create_allowed := ARRAY['japan_package_id','product_group_id','product_variant_id','purchase_batch_id','purchase_batch_item_id','product_title','category_name','variant_name','sku','quantity','note','checked','checked_at'];
      v_patch_allowed := v_create_allowed;
    WHEN 'outbound_shipments' THEN
      v_table := 'public.outbound_shipments'::regclass;
      v_create_allowed := ARRAY['title','status','carrier','tracking_number','weight_kg','shipping_cost','shipped_at','received_at','note'];
      v_patch_allowed := v_create_allowed;
    WHEN 'outbound_shipment_items' THEN
      v_table := 'public.outbound_shipment_items'::regclass;
      v_create_allowed := ARRAY['outbound_shipment_id','japan_package_item_id','product_group_id','product_variant_id','product_title','variant_name','sku','quantity','checked','checked_at','note'];
      v_patch_allowed := v_create_allowed;
    WHEN 'sales_orders' THEN
      v_table := 'public.sales_orders'::regclass;
      v_create_allowed := ARRAY['local_id','platform','order_number','buyer_name'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
    WHEN 'sales_order_items' THEN
      v_table := 'public.sales_order_items'::regclass;
      v_create_allowed := ARRAY['local_id','order_id','product_variant_id','myacg_item_code','product_name','variant_name','quantity','price','amount','order_status'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
    WHEN 'bundle_components' THEN
      v_table := 'public.bundle_components'::regclass;
      v_create_allowed := ARRAY['bundle_variant_id','component_variant_id'];
      v_patch_allowed := ARRAY[]::text[];
    ELSE
      RAISE EXCEPTION 'CLOUD_FIELD_CAS_ENTITY_NOT_ALLOWED:%', p_entity USING ERRCODE = '22023';
  END CASE;

  -- Phase 1: deterministic advisory locks + row locks + validation. No DML occurs here.
  FOR v_operation IN
    SELECT value FROM jsonb_array_elements(p_operations) ORDER BY value->>'id', value->>'kind'
  LOOP
    v_kind := v_operation->>'kind';
    BEGIN
      v_id := (v_operation->>'id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'CLOUD_FIELD_CAS_CANONICAL_UUID_REQUIRED' USING ERRCODE = '22023';
    END;
    IF v_id::text = ANY(v_seen_ids) THEN
      RAISE EXCEPTION 'CLOUD_FIELD_CAS_DUPLICATE_OPERATION_ID:%', v_id USING ERRCODE = '22023';
    END IF;
    v_seen_ids := array_append(v_seen_ids, v_id::text);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_entity || ':' || v_id::text, 0));
    EXECUTE format('SELECT to_jsonb(target) FROM %s AS target WHERE target.id = $1 FOR UPDATE', v_table)
      INTO v_current USING v_id;

    IF v_kind = 'create' THEN
      IF v_current IS NOT NULL THEN
        RETURN jsonb_build_object('ok', false, 'code', 'DUPLICATE_CREATE', 'entity', p_entity, 'recordId', v_id);
      END IF;
      v_values := COALESCE(v_operation->'values', '{}'::jsonb);
      IF jsonb_typeof(v_values) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_VALUES_MUST_BE_OBJECT' USING ERRCODE = '22023';
      END IF;
      SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[]) INTO v_keys FROM jsonb_object_keys(v_values) key;
      IF v_keys && v_protected OR NOT v_keys <@ v_create_allowed THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_CREATE_FIELD_NOT_ALLOWED' USING ERRCODE = '22023';
      END IF;
    ELSIF v_kind IN ('patch', 'reorder') THEN
      IF v_current IS NULL OR (v_current ? 'deleted_at' AND v_current->'deleted_at' <> 'null'::jsonb) THEN
        RETURN jsonb_build_object('ok', false, 'code', 'RECORD_DELETED_OR_MISSING', 'entity', p_entity, 'recordId', v_id);
      END IF;
      v_changes := COALESCE(v_operation->'changes', '{}'::jsonb);
      v_expected := COALESCE(v_operation->'expected', '{}'::jsonb);
      IF jsonb_typeof(v_changes) IS DISTINCT FROM 'object' OR jsonb_typeof(v_expected) IS DISTINCT FROM 'object' OR v_changes = '{}'::jsonb THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_PATCH_INVALID' USING ERRCODE = '22023';
      END IF;
      SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[]) INTO v_keys FROM jsonb_object_keys(v_changes) key;
      IF v_keys && v_protected OR (v_kind = 'patch' AND NOT v_keys <@ v_patch_allowed) OR (v_kind = 'reorder' AND NOT v_keys <@ v_reorder_allowed) THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_PATCH_FIELD_NOT_ALLOWED' USING ERRCODE = '22023';
      END IF;
      IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v_expected) key) IS DISTINCT FROM v_keys THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_EXPECTED_KEYS_MISMATCH' USING ERRCODE = '22023';
      END IF;
      IF v_kind = 'reorder' AND (v_current->>'version')::integer IS DISTINCT FROM (v_operation->>'expectedVersion')::integer THEN
        RETURN jsonb_build_object('ok', false, 'code', 'REORDER_CONFLICT', 'entity', p_entity, 'recordId', v_id);
      END IF;
      IF v_kind = 'patch' AND jsonb_typeof(v_operation->'observedVersion') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_OBSERVED_VERSION_REQUIRED' USING ERRCODE = '22023';
      END IF;
      SELECT COALESCE(jsonb_agg(jsonb_build_object('field', key, 'expected', v_expected->key, 'current', v_current->key) ORDER BY key), '[]'::jsonb)
        INTO v_conflicts
        FROM unnest(v_keys) key
       WHERE NOT (v_current->key IS NOT DISTINCT FROM v_expected->key);
      IF jsonb_array_length(v_conflicts) > 0 THEN
        RETURN jsonb_build_object(
          'ok', false,
          'code', CASE WHEN v_kind = 'reorder' THEN 'REORDER_CONFLICT' ELSE 'FIELD_CONFLICT' END,
          'entity', p_entity,
          'recordId', v_id,
          'conflicts', v_conflicts
        );
      END IF;
    ELSIF v_kind = 'delete' THEN
      IF v_current IS NULL OR (v_current ? 'deleted_at' AND v_current->'deleted_at' <> 'null'::jsonb) THEN
        RETURN jsonb_build_object('ok', false, 'code', 'RECORD_DELETED_OR_MISSING', 'entity', p_entity, 'recordId', v_id);
      END IF;
      v_expected_version := (v_operation->>'expectedVersion')::integer;
      IF (v_current->>'version')::integer IS DISTINCT FROM v_expected_version THEN
        RETURN jsonb_build_object('ok', false, 'code', 'STALE_DELETE', 'entity', p_entity, 'recordId', v_id);
      END IF;
    ELSE
      RAISE EXCEPTION 'CLOUD_FIELD_CAS_OPERATION_NOT_ALLOWED:%', v_kind USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -- Phase 2: all operations validated. Apply only the whitelisted touched fields.
  FOR v_operation IN
    SELECT value FROM jsonb_array_elements(p_operations) ORDER BY value->>'id', value->>'kind'
  LOOP
    v_kind := v_operation->>'kind';
    v_id := (v_operation->>'id')::uuid;
    IF v_kind = 'create' THEN
      v_values := v_operation->'values';
      SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[]) INTO v_keys FROM jsonb_object_keys(v_values) key;
      v_columns_sql := array_to_string(ARRAY(SELECT format('%I', key) FROM unnest(v_keys) key), ', ');
      v_values_sql := array_to_string(ARRAY(SELECT format('typed.%I', key) FROM unnest(v_keys) key), ', ');
      IF cardinality(v_keys) = 0 THEN
        EXECUTE format('INSERT INTO %s AS target (id, updated_by) VALUES ($1, auth.uid()) RETURNING to_jsonb(target)', v_table)
          INTO v_result_row USING v_id;
      ELSE
        EXECUTE format(
          'INSERT INTO %s AS target (id, updated_by, %s) SELECT $1, auth.uid(), %s FROM jsonb_populate_record(NULL::%s, $2) AS typed RETURNING to_jsonb(target)',
          v_table, v_columns_sql, v_values_sql, v_table
        ) INTO v_result_row USING v_id, v_values;
      END IF;
    ELSIF v_kind IN ('patch', 'reorder') THEN
      v_changes := v_operation->'changes';
      SELECT array_agg(key ORDER BY key) INTO v_keys FROM jsonb_object_keys(v_changes) key;
      v_set_sql := array_to_string(ARRAY(SELECT format('%I = typed.%I', key, key) FROM unnest(v_keys) key), ', ');
      EXECUTE format(
        'UPDATE %s AS target SET %s, version = target.version + 1, updated_at = clock_timestamp(), updated_by = auth.uid(), sync_status = ''synced'' FROM jsonb_populate_record(NULL::%s, $2) AS typed WHERE target.id = $1 RETURNING to_jsonb(target)',
        v_table, v_set_sql, v_table
      ) INTO v_result_row USING v_id, v_changes;
    ELSE
      EXECUTE format(
        'UPDATE %s AS target SET deleted_at = clock_timestamp(), version = target.version + 1, updated_at = clock_timestamp(), updated_by = auth.uid(), sync_status = ''synced'' WHERE target.id = $1 RETURNING to_jsonb(target)',
        v_table
      ) INTO v_result_row USING v_id;
    END IF;
    v_rows := v_rows || jsonb_build_array(v_result_row);
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'entity', p_entity, 'rows', v_rows);
END;
$function$

public.erp_cleanup_expired_restore_ops(u.definition:
CREATE OR REPLACE FUNCTION public.erp_cleanup_expired_restore_ops(p_exclude_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '4s'
 SET lock_timeout TO '200ms'
AS $function$
DECLARE
 k text; r public.erp_restore_upload_requests%rowtype; p public.erp_cloud_restore_candidate_proofs%rowtype;
 v_resource text; n integer; chunk_n integer:=0; typed_n integer:=0; byte_n bigint:=0;
 row_budget integer:=1024; more boolean:=false; resource_more boolean; removed integer:=0;
 started timestamptz:=clock_timestamp();
 resources constant text[]:=ARRAY['inventory_items','product_groups','product_categories','product_variants','bundle_components',
 'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
 'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
 'waca_orders','waca_order_items','waca_mappings','waca_master_links','waca_import_batches','waca_cutover_audit','waca_state'];
BEGIN
 -- Administrative SQL is already privileged. A PostgREST role, even inside
 -- this definer, cannot use that branch (session_user remains authenticator).
 IF auth.uid() IS NOT NULL AND public.is_owner(auth.uid()) THEN
  k:=encode(extensions.digest(auth.uid()::text,'sha256'),'hex');
 ELSIF session_user='postgres' AND coalesce(current_setting('role',true),'none')='none' THEN
  k:=NULL;
 ELSE RAISE EXCEPTION USING errcode='42501',message='CLOUD_RESTORE_OWNER_REQUIRED'; END IF;
 IF k IS NOT NULL AND split_part(lower(coalesce(nullif(current_setting('request.headers',true),'')::jsonb->>'host','')),'.',1)<>'rhfdjsklfrgpoqsaqpkn' THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_TARGET_MISMATCH'; END IF;
 -- No Execute/business lock is taken. Proof row NOWAIT makes cleanup yield to
 -- a transaction using the proof; expired proofs are already non-executable.
 SELECT u.* INTO r FROM public.erp_restore_upload_requests u
 LEFT JOIN public.erp_cloud_restore_candidate_proofs cp ON cp.proof_id=u.request_id
 WHERE u.expires_at<=started AND (k IS NULL OR u.actor_key=k)
  AND u.request_id IS DISTINCT FROM p_exclude_request_id
  AND (cp.proof_id IS NULL OR cp.expires_at<=started)
  AND NOT EXISTS(SELECT 1 FROM public.erp_cloud_restore_attempts a
   WHERE a.actor_key=u.actor_key AND a.effective_fingerprint=cp.effective_fingerprint
    AND a.status NOT IN('completed','not_committed'))
 ORDER BY u.created_at,u.request_id LIMIT 1 FOR UPDATE OF u NOWAIT;
 IF NOT FOUND THEN
  -- Legacy proof-only prepares share the same bounded drain; they are not
  -- forgotten just because the newer upload request table has no parent row.
  SELECT cp.* INTO p FROM public.erp_cloud_restore_candidate_proofs cp
  WHERE cp.expires_at<=started AND (k IS NULL OR cp.actor_key=k)
   AND cp.proof_id IS DISTINCT FROM p_exclude_request_id
   AND NOT EXISTS(SELECT 1 FROM public.erp_restore_upload_requests u WHERE u.request_id=cp.proof_id)
   AND NOT EXISTS(SELECT 1 FROM public.erp_cloud_restore_attempts a WHERE a.actor_key=cp.actor_key
    AND a.effective_fingerprint=cp.effective_fingerprint AND a.status NOT IN('completed','not_committed'))
  ORDER BY cp.created_at,cp.proof_id LIMIT 1 FOR UPDATE NOWAIT;
  IF NOT FOUND THEN RETURN jsonb_build_object('status','idle','requests',0,'serverMs',extract(epoch FROM clock_timestamp()-started)*1000); END IF;
  r.request_id:=p.proof_id;
 END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('erp-restore-upload:'||r.request_id::text,0)) THEN
  RETURN jsonb_build_object('status','busy','requests',0); END IF;
 SELECT * INTO p FROM public.erp_cloud_restore_candidate_proofs WHERE proof_id=r.request_id FOR UPDATE NOWAIT;

 -- Each chunk selection is bounded before TOAST deletion: <=16 chunks and
 -- <=8 MiB physical JSON bytes. One oversized chunk is handled alone, not lost.
 WITH candidates AS MATERIALIZED (
  SELECT resource,chunk_ordinal,pg_column_size(rows) bytes,
   sum(pg_column_size(rows)) OVER(ORDER BY resource,chunk_ordinal) total_bytes,
   row_number() OVER(ORDER BY resource,chunk_ordinal) position
  FROM (SELECT resource,chunk_ordinal,rows FROM public.erp_cloud_restore_prepared_chunks
   WHERE proof_id=r.request_id ORDER BY resource,chunk_ordinal LIMIT 4) limited
 ), deleted AS (
  DELETE FROM public.erp_cloud_restore_prepared_chunks c USING candidates x
   WHERE c.proof_id=r.request_id AND c.resource=x.resource AND c.chunk_ordinal=x.chunk_ordinal
    AND (x.total_bytes<=2097152 OR x.position=1) RETURNING x.bytes
 ) SELECT count(*),coalesce(sum(bytes),0) INTO chunk_n,byte_n FROM deleted;
 WITH candidates AS MATERIALIZED (
  SELECT resource,ordinal,pg_column_size(rows) bytes,
   sum(pg_column_size(rows)) OVER(ORDER BY resource,ordinal) total_bytes,
   row_number() OVER(ORDER BY resource,ordinal) position
  FROM (SELECT resource,ordinal,rows FROM public.erp_restore_upload_chunks
   WHERE request_id=r.request_id ORDER BY resource,ordinal LIMIT 4) limited
 ), deleted AS (
  DELETE FROM public.erp_restore_upload_chunks c USING candidates x
   WHERE c.request_id=r.request_id AND c.resource=x.resource AND c.ordinal=x.ordinal
    AND (x.total_bytes<=2097152 OR x.position=1) RETURNING x.bytes
 ) SELECT chunk_n+count(*),byte_n+coalesce(sum(bytes),0) INTO chunk_n,byte_n FROM deleted;
 FOREACH v_resource IN ARRAY resources LOOP
  IF row_budget>0 AND extract(epoch FROM clock_timestamp()-started)*1000<1000 THEN
   EXECUTE format('WITH chosen AS MATERIALIZED (SELECT id FROM public.%I WHERE restore_proof_id=$1 ORDER BY id LIMIT $2)
    DELETE FROM public.%I t USING chosen c WHERE t.restore_proof_id=$1 AND t.id=c.id',
    'erp_restore_stage_'||v_resource,'erp_restore_stage_'||v_resource) USING r.request_id,row_budget;
   GET DIAGNOSTICS n=ROW_COUNT; row_budget:=row_budget-n; typed_n:=typed_n+n;
  END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE restore_proof_id=$1)','erp_restore_stage_'||v_resource)
   INTO resource_more USING r.request_id;
  more:=more OR resource_more;
 END LOOP;
 -- At most 24 fixed resource summaries, never business data or attempt audit.
 WITH chosen AS MATERIALIZED (SELECT resource FROM public.erp_restore_upload_resource_proofs
  WHERE request_id=r.request_id ORDER BY resource LIMIT 24)
 DELETE FROM public.erp_restore_upload_resource_proofs t USING chosen c
  WHERE t.request_id=r.request_id AND t.resource=c.resource;
 more:=more OR EXISTS(SELECT 1 FROM public.erp_cloud_restore_prepared_chunks WHERE proof_id=r.request_id)
  OR EXISTS(SELECT 1 FROM public.erp_restore_upload_chunks WHERE request_id=r.request_id)
  OR EXISTS(SELECT 1 FROM public.erp_restore_upload_resource_proofs WHERE request_id=r.request_id);
 IF NOT more THEN
  -- All cascade children were drained in bounded batches; preserve the
  -- existing referential trigger and immutable attempt/failure/receipt audit.
  DELETE FROM public.erp_cloud_restore_candidate_proofs WHERE proof_id=r.request_id;
  DELETE FROM public.erp_restore_upload_requests WHERE request_id=r.request_id;
  GET DIAGNOSTICS removed=ROW_COUNT;
 END IF;
 RETURN jsonb_build_object('status','progress','requestId',r.request_id,'requests',removed,
  'chunks',chunk_n,'approxBytes',byte_n,'typedRows',typed_n,'requestRemaining',more,
  'serverMs',extract(epoch FROM clock_timestamp()-started)*1000);
EXCEPTION WHEN lock_not_available THEN
 RETURN jsonb_build_object('status','busy','requests',0,'serverMs',extract(epoch FROM clock_timestamp()-started)*1000);
END;
$function$

public.erp_delete_product_group_trees(js.definition:
CREATE OR REPLACE FUNCTION public.erp_delete_product_group_trees(p_groups jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_group jsonb;
  v_group_id uuid;
  v_group_version integer;
  v_expected_categories jsonb;
  v_expected_variants jsonb;
  v_current_categories jsonb;
  v_current_variants jsonb;
  v_group_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_editor(auth.uid()) THEN
    RAISE EXCEPTION 'CLOUD_FIELD_CAS_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_groups) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'CLOUD_GROUP_DELETE_EXPECTATIONS_MUST_BE_ARRAY' USING ERRCODE = '22023';
  END IF;

  FOR v_group IN SELECT value FROM jsonb_array_elements(p_groups) ORDER BY value->>'id'
  LOOP
    v_group_id := (v_group->>'id')::uuid;
    v_group_version := (v_group->>'expectedVersion')::integer;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('product_group_tree:' || v_group_id::text, 0));
    PERFORM 1 FROM public.product_groups
      WHERE id = v_group_id AND deleted_at IS NULL AND version = v_group_version
      FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'code', 'STALE_DELETE', 'entity', 'product_groups', 'recordId', v_group_id);
    END IF;

    PERFORM 1 FROM public.product_categories WHERE product_group_id = v_group_id AND deleted_at IS NULL ORDER BY id FOR UPDATE;
    PERFORM 1 FROM public.product_variants WHERE product_group_id = v_group_id AND deleted_at IS NULL ORDER BY id FOR UPDATE;

    v_expected_categories := COALESCE(v_group->'categories', '[]'::jsonb);
    v_expected_variants := COALESCE(v_group->'variants', '[]'::jsonb);
    SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'expectedVersion', version) ORDER BY id), '[]'::jsonb)
      INTO v_current_categories FROM public.product_categories WHERE product_group_id = v_group_id AND deleted_at IS NULL;
    SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'expectedVersion', version) ORDER BY id), '[]'::jsonb)
      INTO v_current_variants FROM public.product_variants WHERE product_group_id = v_group_id AND deleted_at IS NULL;

    SELECT COALESCE(jsonb_agg(value ORDER BY value->>'id'), '[]'::jsonb)
      INTO v_expected_categories FROM jsonb_array_elements(v_expected_categories);
    SELECT COALESCE(jsonb_agg(value ORDER BY value->>'id'), '[]'::jsonb)
      INTO v_expected_variants FROM jsonb_array_elements(v_expected_variants);
    IF v_current_categories IS DISTINCT FROM v_expected_categories OR v_current_variants IS DISTINCT FROM v_expected_variants THEN
      RETURN jsonb_build_object('ok', false, 'code', 'STALE_DELETE', 'entity', 'product_groups', 'recordId', v_group_id);
    END IF;
    v_group_ids := array_append(v_group_ids, v_group_id);
  END LOOP;

  UPDATE public.product_categories SET deleted_at = clock_timestamp(), version = version + 1,
    updated_at = clock_timestamp(), updated_by = auth.uid(), sync_status = 'synced'
    WHERE product_group_id = ANY(v_group_ids) AND deleted_at IS NULL;
  UPDATE public.product_variants SET deleted_at = clock_timestamp(), version = version + 1,
    updated_at = clock_timestamp(), updated_by = auth.uid(), sync_status = 'synced'
    WHERE product_group_id = ANY(v_group_ids) AND deleted_at IS NULL;
  UPDATE public.product_groups SET deleted_at = clock_timestamp(), version = version + 1,
    updated_at = clock_timestamp(), updated_by = auth.uid(), sync_status = 'synced'
    WHERE id = ANY(v_group_ids) AND deleted_at IS NULL;

  RETURN jsonb_build_object('ok', true, 'entity', 'product_groups', 'rows', '[]'::jsonb);
END;
$function$

public.erp_merge_waca_master_links(uuid,.definition:
CREATE OR REPLACE FUNCTION public.erp_merge_waca_master_links(p_idempotency_key uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid:=auth.uid();
  v_claimed boolean;
  v_prior_request public.erp_idempotency_keys%ROWTYPE;
  v_prior_link public.waca_master_links%ROWTYPE;
  v_row jsonb;
  v_payload jsonb;
  v_variant_id uuid;
  v_expected_revision bigint;
  v_revision bigint;
  v_inserted integer:=0;
  v_updated integer:=0;
  v_unchanged integer:=0;
  v_failure jsonb;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.is_owner(v_actor) THEN
    RAISE EXCEPTION 'WACA_OWNER_REQUIRED' USING ERRCODE='42501';
  END IF;
  IF p_idempotency_key IS NULL OR jsonb_typeof(p_request) IS DISTINCT FROM 'object'
    OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_request) k)
      IS DISTINCT FROM ARRAY['expectedRevision','family','links']::text[]
    OR p_request->>'family' IS DISTINCT FROM 'waca-master-links'
    OR coalesce(p_request->>'expectedRevision','') !~ '^[0-9]+$'
    OR jsonb_typeof(p_request->'links') IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_request->'links')=0
    OR jsonb_array_length(p_request->'links')>10000 THEN
    RAISE EXCEPTION 'WACA_MASTER_LINK_DELTA_INVALID' USING ERRCODE='22023';
  END IF;
  v_expected_revision:=(p_request->>'expectedRevision')::bigint;
  IF (SELECT count(*) FROM jsonb_array_elements(p_request->'links')) IS DISTINCT FROM
     (SELECT count(DISTINCT value->>'childCode') FROM jsonb_array_elements(p_request->'links')) THEN
    RAISE EXCEPTION 'WACA_MASTER_LINK_DELTA_DUPLICATE' USING ERRCODE='22023';
  END IF;
  FOR v_row IN SELECT value FROM jsonb_array_elements(p_request->'links') LOOP
    IF EXISTS(SELECT 1 FROM jsonb_object_keys(v_row) k WHERE k NOT IN (
      'mainCode','childCode','productGroupId','productVariantId','productTitle',
      'variantTitle','sourceFile','sourceFiles','observedAt'))
      OR coalesce(btrim(v_row->>'childCode'),'')=''
      OR coalesce(btrim(v_row->>'mainCode'),'')=''
      OR jsonb_typeof(coalesce(v_row->'sourceFiles','[]'::jsonb)) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'WACA_MASTER_LINK_DELTA_ROW_INVALID' USING ERRCODE='22023';
    END IF;
  END LOOP;

  BEGIN
    INSERT INTO public.erp_idempotency_keys(
      actor_id,idempotency_key,operation_type,request_fingerprint,request_payload,status
    ) VALUES(v_actor,p_idempotency_key,'edit',md5(p_request::text),p_request,'processing')
    ON CONFLICT(actor_id,idempotency_key) DO NOTHING RETURNING true INTO v_claimed;
    IF NOT coalesce(v_claimed,false) THEN
      SELECT * INTO v_prior_request FROM public.erp_idempotency_keys
       WHERE actor_id=v_actor AND idempotency_key=p_idempotency_key FOR UPDATE;
      IF v_prior_request.request_payload IS DISTINCT FROM p_request THEN
        RETURN jsonb_build_object('ok',false,'code','IDEMPOTENCY_KEY_PAYLOAD_MISMATCH');
      END IF;
      IF v_prior_request.status<>'completed' THEN
        RAISE EXCEPTION 'WACA_MASTER_LINK_DELTA_INCOMPLETE';
      END IF;
      RETURN jsonb_set(v_prior_request.canonical_result,'{replayed}','true',true);
    END IF;

    IF NOT pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) THEN
      RAISE EXCEPTION 'CLOUD_RESTORE_MAINTENANCE_LOCKED' USING ERRCODE='55006';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('erp-waca-ledger-import',0));
    SELECT revision INTO v_revision FROM public.waca_state FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'WACA_STATE_MISSING' USING ERRCODE='55000'; END IF;
    IF v_revision IS DISTINCT FROM v_expected_revision THEN
      v_failure:=jsonb_build_object('ok',false,'code','WACA_STALE_REVISION',
        'expectedRevision',v_expected_revision,'actualRevision',v_revision);
      RAISE EXCEPTION 'WACA_MASTER_LINK_DELTA_ROLLBACK';
    END IF;

    FOR v_row IN SELECT value FROM jsonb_array_elements(p_request->'links') ORDER BY value->>'childCode' LOOP
      v_variant_id:=public.erp_waca_variant_id(v_row->>'productVariantId');
      v_payload:=jsonb_set(v_row,'{productVariantId}',to_jsonb(coalesce(v_variant_id::text,'')),true);
      SELECT * INTO v_prior_link FROM public.waca_master_links WHERE child_code=v_row->>'childCode';
      IF FOUND AND (v_prior_link.main_code IS DISTINCT FROM v_row->>'mainCode'
        OR (v_prior_link.product_variant_id IS NOT NULL AND v_variant_id IS NOT NULL
          AND v_prior_link.product_variant_id IS DISTINCT FROM v_variant_id)
        OR (coalesce(v_prior_link.payload->>'productGroupId','')<>''
          AND coalesce(v_row->>'productGroupId','')<>''
          AND v_prior_link.payload->>'productGroupId' IS DISTINCT FROM v_row->>'productGroupId')) THEN
        v_failure:=jsonb_build_object('ok',false,'code','WACA_MASTER_LINK_CONFLICT',
          'childCode',v_row->>'childCode');
        RAISE EXCEPTION 'WACA_MASTER_LINK_DELTA_ROLLBACK';
      END IF;
      IF FOUND AND v_prior_link.main_code IS NOT DISTINCT FROM v_row->>'mainCode'
        AND v_prior_link.product_variant_id IS NOT DISTINCT FROM v_variant_id
        AND v_prior_link.payload IS NOT DISTINCT FROM v_payload THEN
        v_unchanged:=v_unchanged+1;
      ELSIF FOUND THEN
        UPDATE public.waca_master_links SET main_code=v_row->>'mainCode',
          product_variant_id=v_variant_id,payload=v_payload,updated_at=clock_timestamp(),updated_by=v_actor
         WHERE id=v_prior_link.id;
        v_updated:=v_updated+1;
      ELSE
        INSERT INTO public.waca_master_links(child_code,main_code,product_variant_id,payload,updated_by)
        VALUES(v_row->>'childCode',v_row->>'mainCode',v_variant_id,v_payload,v_actor);
        v_inserted:=v_inserted+1;
      END IF;
    END LOOP;

    IF v_inserted+v_updated>0 THEN
      UPDATE public.waca_state SET revision=revision+1,
        payload=payload||jsonb_build_object('lastMasterLinkMerge',jsonb_build_object(
          'requestId',p_idempotency_key,'actorId',v_actor,'changed',v_inserted+v_updated,
          'mergedAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))),
        updated_at=clock_timestamp(),updated_by=v_actor
       RETURNING revision INTO v_revision;
    END IF;
    v_result:=jsonb_build_object('ok',true,'replayed',false,'idempotencyKey',p_idempotency_key,
      'revision',v_revision,'inserted',v_inserted,'updated',v_updated,'unchanged',v_unchanged,
      'changed',v_inserted+v_updated);
    UPDATE public.erp_idempotency_keys SET status='completed',canonical_result=v_result,
      completed_at=clock_timestamp() WHERE actor_id=v_actor AND idempotency_key=p_idempotency_key;
    RETURN v_result;
  EXCEPTION WHEN OTHERS THEN
    IF v_failure IS NOT NULL THEN RETURN v_failure; END IF;
    RETURN jsonb_build_object('ok',false,'code','TRANSACTION_REJECTED','sqlstate',SQLSTATE);
  END;
END;
$function$

public.erp_restore_track_business_genera.definition:
CREATE OR REPLACE FUNCTION public.erp_restore_track_business_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  -- Uses the existing maintenance lock, not a new bypass; even Restore changes
  -- advance the generation transactionally. Rolled-back writes do not advance it.
  IF NOT pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) THEN
    RAISE EXCEPTION USING errcode='55006',message='CLOUD_RESTORE_MAINTENANCE_LOCKED';
  END IF;
  UPDATE public.erp_restore_business_generation SET generation=generation+1 WHERE singleton;
  RETURN NULL;
END;
$function$

public.erp_commit_waca_recognition(jsonb.definition:
CREATE OR REPLACE FUNCTION public.erp_commit_waca_recognition(p_request jsonb, p_expected_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '15s'
AS $function$
declare
  actor uuid:=auth.uid(); plan jsonb; prior jsonb; line jsonb; qty jsonb; n bigint; epoch bigint;
  evidence jsonb:='[]'; result jsonb; keys jsonb; now_at timestamptz:=now(); v public.product_variants%rowtype;
begin
  if actor is null or not public.is_owner(actor) then raise exception using errcode='42501',message='WACA_OWNER_REQUIRED'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) then
    raise exception using errcode='55006',message='CLOUD_RESTORE_MAINTENANCE_LOCKED'; end if;
  perform pg_advisory_xact_lock(hashtextextended('erp-waca-ledger-import',0));
  perform 1 from public.waca_state where id='00000000-0000-4000-8000-000000000001' for update;
  select e.epoch into epoch from public.erp_cloud_restore_epoch e where singleton;
  if epoch is distinct from (p_request->>'restoreEpoch')::bigint then raise exception using errcode='40001',message='WACA_RESTORE_EPOCH_CHANGED'; end if;
  select b.payload->'recognition' into prior from public.waca_import_batches b where b.batch_key=p_request->>'requestId';
  if found then
    if prior->'request' is distinct from p_request or prior->'plan' is distinct from p_expected_plan or prior->>'actor' is distinct from actor::text then
      raise exception using errcode='23000',message='WACA_RECOGNITION_REQUEST_REUSED'; end if;
    return prior->'result';
  end if;
  -- Lock target variants before re-planning so another manual writer cannot race the proof/CAS.
  perform 1 from public.product_variants pv where pv.id in
    (select i.product_variant_id from public.waca_order_items i join jsonb_array_elements(p_request->'choices') c
      on i.item_key=c->>'itemKey') order by pv.id for update;
  plan:=public.erp_plan_waca_recognition(p_request);
  if plan is distinct from p_expected_plan then raise exception using errcode='40001',message='WACA_RECOGNITION_PREVIEW_CHANGED'; end if;
  if jsonb_array_length(plan->'lines')=0 then return jsonb_build_object('status','NO_CHANGE','revision',(plan->>'revision')::bigint,'requestId',plan->>'requestId'); end if;
  for line in select value from jsonb_array_elements(plan->'lines') loop
    update public.waca_order_items set payload=(payload-'countedReview')||jsonb_build_object(
      'countedQuantity',(line->>'countedAfter')::integer,
      'countedReason',case line->>'mode' when 'COUNT' then 'OWNER_CONFIRMED_NEW' when 'INCLUDED' then 'BASELINE_INCLUDED' else 'PENDING_REVIEW' end,
      'countedBy',actor::text,'recognition',jsonb_build_object('mode',line->>'mode','requestId',plan->>'requestId',
        'restoreEpoch',epoch,'sourceQuantity',line->'sourceQuantity','sourceStatus',line->>'sourceStatus','actor',actor,'decidedAt',now_at))
      ||case when line->>'mode'='HOLD' then '{"countedReview":"OWNER_HOLD"}'::jsonb else '{}'::jsonb end,
      updated_at=now_at,updated_by=actor where item_key=line->>'itemKey' and product_variant_id=(line->>'variantId')::uuid;
    get diagnostics n=row_count;
    if n<>1 then raise exception using errcode='23514',message='WACA_RECOGNITION_ITEM_UPDATE_MISMATCH'; end if;
  end loop;
  for qty in select value from jsonb_array_elements(plan->'quantities') loop
    -- Zero-delta decisions still record a proof but never touch unrelated Variant fields.
    if (qty->>'delta')::integer<>0 then
      update public.product_variants set waca_manual_adjustment=waca_manual_adjustment+(qty->>'delta')::integer,
        version=version+1,updated_at=now_at,updated_by=actor
      where id=(qty->>'variantId')::uuid and version=(qty->>'version')::bigint
        and waca_auto_quantity=(qty->>'autoBefore')::integer and waca_manual_adjustment=(qty->>'manualBefore')::integer;
      get diagnostics n=row_count;
      if n<>1 then raise exception using errcode='40001',message='WACA_RECOGNITION_VARIANT_CHANGED'; end if;
    end if;
    select * into v from public.product_variants where id=(qty->>'variantId')::uuid;
    evidence:=evidence||jsonb_build_array(jsonb_build_object('variantId',v.id,'versionAfter',v.version,
      'autoAfter',v.waca_auto_quantity,'manualAfter',v.waca_manual_adjustment));
    select coalesce(jsonb_agg(i.item_key order by i.item_key),'[]'::jsonb) into keys from public.waca_order_items i
      where i.product_variant_id=v.id and coalesce((i.payload->>'countedQuantity')::integer,0)>0
        and ((qty->'reversibleItemKeys') ? i.item_key or exists(select 1 from jsonb_array_elements(plan->'lines') l
          where l->>'itemKey'=i.item_key and (l->>'countedBefore')::integer=0 and (l->>'countedAfter')::integer>0));
    perform public.erp_store_waca_recognition_continuity(v.id,epoch,keys);
  end loop;
  update public.waca_state set revision=revision+1,updated_at=now_at,updated_by=actor
    where id='00000000-0000-4000-8000-000000000001' and revision=(plan->>'revision')::bigint;
  get diagnostics n=row_count;
  if n<>1 then raise exception using errcode='40001',message='WACA_STALE_REVISION'; end if;
  result:=jsonb_build_object('status','COMMITTED','revision',(plan->>'revision')::bigint+1,'requestId',plan->>'requestId');
  insert into public.waca_import_batches(batch_key,payload,updated_at,updated_by)
    values(plan->>'requestId',jsonb_build_object('id',plan->>'requestId','fileName','來源訂單認列調整','importedAt',now_at,
      'rows',jsonb_array_length(plan->'lines'),'inserted',0,'updated',jsonb_array_length(plan->'lines'),'unchanged',0,
      'result',jsonb_build_object('ordersTotal',1,'productRows',jsonb_array_length(plan->'lines'),'cancelledOrders',0,
        'failedOrders',0,'matched',jsonb_array_length(plan->'lines'),'unmatched',0,'multipleCandidates',0,'statusConflicts','[]'::jsonb,'effectiveQuantity',0),
      'conflictRows','[]'::jsonb,'recognition',jsonb_build_object('contract','waca-recognition-v1','request',p_request,'plan',plan,
        'result',result,'actor',actor,'at',now_at,'variants',evidence)),now_at,actor);
  return result;
end;
$function$

public.erp_read_cloud_restore_integrity_.definition:
CREATE OR REPLACE FUNCTION public.erp_read_cloud_restore_integrity_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '30s'
AS $function$
declare
  v_data jsonb;
  v_audit jsonb;
  v_epoch bigint;
  v_latest public.erp_cloud_restore_attempts%rowtype;
  v_manifest jsonb;
  v_latest_safe jsonb;
  v_pending bigint;
  v_executing bigint;
  v_processing bigint;
  v_locks bigint;
  v_inconsistent bigint := 0;
  v_counts_match boolean;
  v_hash_match boolean;
begin
  if auth.uid() is null then
    raise exception using errcode='42501', message='AUTHENTICATION_REQUIRED';
  end if;
  if public.is_owner(auth.uid()) is distinct from true then
    raise exception using errcode='42501', message='CLOUD_RESTORE_OWNER_REQUIRED';
  end if;

  -- Deliberately fixed relations, ALL rows including deleted_at != null.
  -- Neither table names nor predicates can be supplied by the caller.
  select jsonb_build_object(
    'inventory_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.inventory_items t),
    'product_groups',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.product_groups t),
    'product_categories',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.product_categories t),
    'product_variants',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.product_variants t),
    'bundle_components',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.bundle_components t),
    'purchase_batches',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.purchase_batches t),
    'purchase_batch_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.purchase_batch_items t),
    'private_orders',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.private_orders t),
    'private_order_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.private_order_items t),
    'sales_orders',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.sales_orders t),
    'sales_order_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.sales_order_items t),
    'japan_packages',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.japan_packages t),
    'japan_package_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.japan_package_items t),
    'outbound_shipments',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.outbound_shipments t),
    'outbound_shipment_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.outbound_shipment_items t),
    'dashboard_category_images',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.dashboard_category_images t),
    'import_batches',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.import_batches t),
    'waca_orders',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.waca_orders t),
    'waca_order_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.waca_order_items t),
    'waca_mappings',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.waca_mappings t),
    'waca_master_links',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.waca_master_links t),
    'waca_import_batches',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.waca_import_batches t),
    'waca_cutover_audit',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.waca_cutover_audit t),
    'waca_state',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.waca_state t)
  ) into v_data;
  perform public.erp_cloud_restore_validate_waca_dataset(v_data);
  v_audit := public.erp_cloud_restore_audit_dataset(v_data);
  select epoch into strict v_epoch from public.erp_cloud_restore_epoch where singleton=true;
  select * into v_latest from public.erp_cloud_restore_attempts
    where status='completed' order by result_epoch desc,completed_at desc,attempt_id limit 1;
  if found then
    v_manifest := v_latest.canonical_result->'manifest';
    v_latest_safe := jsonb_build_object(
      'attempt_id',v_latest.attempt_id,'status',v_latest.status,
      'result_epoch',v_latest.result_epoch,'replayed',v_latest.canonical_result->'replayed',
      'source_fingerprint',v_latest.source_fingerprint,'effective_fingerprint',v_latest.effective_fingerprint,
      'completed_at',v_latest.completed_at,
      'source_transformed_updated_by_count',v_manifest->'portability'->'totalTransformedRows'
    );
    v_counts_match := v_manifest->'counts'=v_audit->'table_counts'
      and (v_manifest->>'totalRows')::bigint=(v_audit->>'total_rows')::bigint;
    v_hash_match := v_manifest->>'relationshipHash'=v_audit->>'relationship_hash';
    if v_latest.result_epoch is distinct from v_epoch
      or v_manifest->>'snapshotFingerprint' is distinct from v_latest.effective_fingerprint
      or v_latest.canonical_result->>'snapshotFingerprint' is distinct from v_latest.effective_fingerprint
      or not exists(select 1 from public.erp_cloud_restore_requests r
        join public.erp_cloud_restore_snapshots s on s.id=r.rollback_snapshot_id
        where r.idempotency_key=v_latest.attempt_id and r.status='completed'
          and r.canonical_result->>'restoreEpoch'=v_epoch::text
          and r.canonical_result->>'snapshotFingerprint'=v_latest.effective_fingerprint
          and r.completed_at is not null)
    then v_inconsistent := v_inconsistent+1; end if;
  elsif v_epoch > 0 then v_inconsistent := v_inconsistent+1;
  end if;
  select count(*) filter(where status='prepared'),count(*) filter(where status='executing')
    into v_pending,v_executing from public.erp_cloud_restore_attempts;
  select count(*) into v_processing from public.erp_cloud_restore_requests where status='processing';

  -- Observation only: never try/acquire advisory locks, never reconcile attempts.
  select count(*) into v_locks from pg_catalog.pg_locks l
    where l.locktype='advisory' and l.objsubid=1
      and l.database=(select oid from pg_catalog.pg_database where datname=current_database())
      and ((l.classid::bigint<<32)|l.objid::bigint) in (
        select hashtextextended('erp-cloud-restore-maintenance-lock',0)
        union all select hashtextextended('erp-cloud-restore-attempt:'||attempt_id::text,0)
          from public.erp_cloud_restore_attempts
      );

  return v_audit || jsonb_build_object(
    'schema_version','cloud-restore-integrity-audit-v1','audited_at',statement_timestamp(),'epoch',v_epoch,
    'audit_policy',(v_audit->'audit_policy')||jsonb_build_object('policy',v_latest.restore_policy),
    'expected_manifest',case when v_manifest is null then null else jsonb_build_object(
      'counts',v_manifest->'counts','total_rows',v_manifest->'totalRows',
      'relationship_hash',v_manifest->'relationshipHash') end,
    'comparison',jsonb_build_object('counts_match',v_counts_match,'relationship_hash_match',v_hash_match),
    'restore_state',jsonb_build_object(
      'latest_completed',v_latest_safe,'pending_count',v_pending,'executing_count',v_executing,
      'processing_request_count',v_processing,'active_lock_count',v_locks,
      'metadata_inconsistency_count',v_inconsistent,
      'partial_state',case when v_inconsistent>0 then 'inconsistent'
        when v_pending+v_executing+v_processing+v_locks>0 or v_counts_match is not true or v_hash_match is not true then 'unproven'
        else 'not_detected' end,
      'scope','statement snapshot; locks sampled separately; counts/identity/relationships, not all business values'
    )
  );
end;
$function$

public.erp_apply_catalog_transaction(uui.definition:
CREATE OR REPLACE FUNCTION public.erp_apply_catalog_transaction(p_idempotency_key uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor uuid:=auth.uid(); claimed boolean; exact_replay boolean:=false;
  old_request public.erp_idempotency_keys%ROWTYPE;
  entity text; current_versions jsonb; ops jsonb; result jsonb; failure jsonb; op jsonb;
  categories_written boolean:=false; started_at timestamptz:=clock_timestamp(); phase_at timestamptz:=clock_timestamp();
  phases jsonb:='{}'::jsonb;
BEGIN
  IF actor IS NULL OR NOT public.is_editor(actor) THEN RAISE EXCEPTION 'CATALOG_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF p_idempotency_key IS NULL OR jsonb_typeof(p_request) IS DISTINCT FROM 'object'
    OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_request) k) IS DISTINCT FROM ARRAY['dependencies','family','mode','operations']::text[]
    OR p_request->>'family' IS DISTINCT FROM 'catalog'
    OR coalesce(p_request->>'mode','') NOT IN ('create','sync','reparse')
    OR jsonb_typeof(p_request->'dependencies') IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_request->'operations') IS DISTINCT FROM 'object'
    OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_request->'dependencies') k) IS DISTINCT FROM ARRAY['inventory_items','product_categories','product_groups','product_variants']::text[]
    OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_request->'operations') k) IS DISTINCT FROM ARRAY['product_categories','product_groups','product_variants']::text[] THEN
    RAISE EXCEPTION 'CATALOG_INVALID_REQUEST' USING ERRCODE='22023';
  END IF;

  -- A successful response-loss retry must be recognized before consulting the
  -- now-promoted row. Only an exact completed request may take this path.
  SELECT EXISTS(
    SELECT 1 FROM public.erp_idempotency_keys i
    WHERE i.actor_id=actor AND i.idempotency_key=p_idempotency_key
      AND i.status='completed' AND i.request_payload=p_request
  ) INTO exact_replay;

  FOREACH entity IN ARRAY ARRAY['product_groups','product_categories','product_variants'] LOOP
    ops:=p_request->'operations'->entity;
    IF jsonb_typeof(ops) IS DISTINCT FROM 'array' OR jsonb_array_length(ops)>10000 THEN
      RAISE EXCEPTION 'CATALOG_INVALID_OPERATIONS' USING ERRCODE='22023';
    END IF;
    FOR op IN SELECT value FROM jsonb_array_elements(ops) LOOP
      IF coalesce(op->>'kind','') NOT IN ('create','patch','reorder','delete')
        OR (entity<>'product_categories' AND op->>'kind'='delete') THEN
        RAISE EXCEPTION 'CATALOG_DESTRUCTIVE_OPERATION_FORBIDDEN' USING ERRCODE='22023';
      END IF;
      IF entity='product_variants' AND op->>'kind'<>'create' AND EXISTS(
        SELECT 1 FROM jsonb_object_keys(coalesce(op->'changes','{}')) k WHERE k NOT IN (
          'product_category_id','myacg_item_code','product_title','variant_name','raw_variant_name',
          'myacg_auto_quantity','effective_myacg_quantity','sort_order','catalog_missing','source')) THEN
        RAISE EXCEPTION 'CATALOG_MANUAL_METADATA_FORBIDDEN' USING ERRCODE='22023';
      END IF;
      IF entity='product_variants' AND op->>'kind'<>'create' AND coalesce(op->'changes','{}') ? 'source'
        AND NOT exact_replay AND NOT (
          p_request->>'mode'='create'
          AND op->>'kind'='patch'
          AND op->'expected'->>'source'='inventory_import'
          AND op->'changes'->>'source'='myacg_order_import'
          AND EXISTS(
            SELECT 1
            FROM public.product_variants v
            JOIN public.product_groups g ON g.id=v.product_group_id AND g.deleted_at IS NULL
            WHERE v.id=(op->>'id')::uuid
              AND v.deleted_at IS NULL
              AND v.source='inventory_import'
              AND coalesce(g.show_in_purchase_list,false)=false
              AND v.myacg_item_code<>''
              AND (SELECT count(*) FROM public.inventory_items i
                   WHERE i.deleted_at IS NULL
                     AND i.myacg_item_code=v.myacg_item_code
                     AND i.product_title=v.product_title
                     AND coalesce(i.raw_variant_name,'')=coalesce(v.raw_variant_name,'')
                     AND coalesce(nullif(i.normalized_product_title,''),lower(btrim(i.product_title)))
                       =coalesce(nullif(g.normalized_title,''),lower(btrim(g.title))))=1
              AND EXISTS(
                SELECT 1 FROM jsonb_array_elements(p_request->'operations'->'product_groups') group_op
                WHERE group_op->>'kind'='patch'
                  AND group_op->>'id'=v.product_group_id::text
                  AND group_op->'expected'->'show_in_purchase_list'='false'::jsonb
                  AND group_op->'changes'->'show_in_purchase_list'='true'::jsonb
              )
          )
        ) THEN
        RAISE EXCEPTION 'CATALOG_PROVENANCE_TRANSITION_FORBIDDEN' USING ERRCODE='22023';
      END IF;
    END LOOP;
  END LOOP;
  phases:=jsonb_build_object('validationMs',extract(epoch from clock_timestamp()-started_at)*1000); phase_at:=clock_timestamp();
  BEGIN
    INSERT INTO public.erp_idempotency_keys(actor_id,idempotency_key,operation_type,request_fingerprint,request_payload,status)
      VALUES(actor,p_idempotency_key,'edit',md5(p_request::text),p_request,'processing')
      ON CONFLICT(actor_id,idempotency_key) DO NOTHING RETURNING true INTO claimed;
    IF NOT coalesce(claimed,false) THEN
      SELECT * INTO old_request FROM public.erp_idempotency_keys WHERE actor_id=actor AND idempotency_key=p_idempotency_key FOR UPDATE;
      IF old_request.request_payload IS DISTINCT FROM p_request THEN RETURN jsonb_build_object('ok',false,'code','IDEMPOTENCY_KEY_PAYLOAD_MISMATCH'); END IF;
      IF old_request.status<>'completed' THEN RAISE EXCEPTION 'CATALOG_INCOMPLETE'; END IF;
      RETURN jsonb_set(old_request.canonical_result,'{replayed}','true',true);
    END IF;
    -- Full dependency CAS also prevents a fresh plan from creating a duplicate
    -- group/variant while another editor or import changes the catalog.
    LOCK TABLE public.inventory_items,public.product_groups,public.product_categories,public.product_variants IN SHARE ROW EXCLUSIVE MODE;
    phases:=phases||jsonb_build_object('lockIdempotencyMs',extract(epoch from clock_timestamp()-phase_at)*1000); phase_at:=clock_timestamp();
    FOREACH entity IN ARRAY ARRAY['inventory_items','product_groups','product_categories','product_variants'] LOOP
      EXECUTE format('SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''version'',version) ORDER BY id),''[]''::jsonb) FROM public.%I WHERE deleted_at IS NULL',entity) INTO current_versions;
      IF current_versions IS DISTINCT FROM p_request->'dependencies'->entity THEN
        failure:=jsonb_build_object('ok',false,'code','FIELD_CONFLICT','entity',entity); RAISE EXCEPTION 'CATALOG_ROLLBACK';
      END IF;
    END LOOP;
    phases:=phases||jsonb_build_object('dependencyCasMs',extract(epoch from clock_timestamp()-phase_at)*1000); phase_at:=clock_timestamp();
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_request->'operations'->'product_groups') o
      JOIN public.product_groups g ON g.title=o->'values'->>'title' AND g.deleted_at IS NULL WHERE o->>'kind'='create') THEN
      RAISE EXCEPTION 'CATALOG_DUPLICATE_GROUP';
    END IF;
    FOREACH entity IN ARRAY ARRAY['product_groups','product_categories','product_variants','product_categories'] LOOP
      SELECT coalesce(jsonb_agg(o),'[]') INTO ops FROM jsonb_array_elements(p_request->'operations'->entity) o
        WHERE CASE WHEN entity='product_categories' THEN
          CASE WHEN categories_written THEN o->>'kind'='delete' ELSE o->>'kind'<>'delete' END ELSE true END;
      IF jsonb_array_length(ops)>0 THEN
        phase_at:=clock_timestamp(); result:=public.erp_apply_catalog_fields_set_based(entity,ops);
        phases:=phases||jsonb_build_object(entity||CASE WHEN entity='product_categories' AND categories_written THEN '_delete' ELSE '' END||'Ms',extract(epoch from clock_timestamp()-phase_at)*1000);
        IF result->>'ok' IS DISTINCT FROM 'true' THEN failure:=result; RAISE EXCEPTION 'CATALOG_ROLLBACK'; END IF;
      END IF;
      IF entity='product_categories' THEN categories_written:=true; END IF;
    END LOOP;
    phase_at:=clock_timestamp();
    IF EXISTS(SELECT 1 FROM public.product_variants v
      JOIN jsonb_array_elements(p_request->'operations'->'product_variants') o ON v.id=(o->>'id')::uuid
      LEFT JOIN public.product_groups g ON g.id=v.product_group_id AND g.deleted_at IS NULL
      LEFT JOIN public.product_categories c ON c.id=v.product_category_id AND c.deleted_at IS NULL
      WHERE v.deleted_at IS NULL AND (g.id IS NULL OR (v.product_category_id IS NOT NULL AND
        (c.id IS NULL OR c.product_group_id IS DISTINCT FROM v.product_group_id)))) THEN RAISE EXCEPTION 'CATALOG_RELATIONSHIP_INVALID'; END IF;
    IF EXISTS(SELECT 1 FROM public.product_variants v JOIN public.product_categories c ON c.id=v.product_category_id
      JOIN jsonb_array_elements(p_request->'operations'->'product_categories') o ON c.id=(o->>'id')::uuid
      WHERE v.deleted_at IS NULL AND c.deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'CATALOG_ACTIVE_CATEGORY_REFERENCE'; END IF;
    IF EXISTS(SELECT 1 FROM public.product_variants v
      JOIN jsonb_array_elements(p_request->'operations'->'product_variants') o ON v.id=(o->>'id')::uuid
      JOIN public.product_variants other ON other.id<>v.id AND other.deleted_at IS NULL
        AND other.product_group_id=v.product_group_id AND other.myacg_item_code=v.myacg_item_code
        AND coalesce(other.raw_variant_name,'')=coalesce(v.raw_variant_name,'') AND other.product_title=v.product_title
      WHERE o->>'kind'='create' AND v.deleted_at IS NULL) THEN RAISE EXCEPTION 'CATALOG_DUPLICATE_VARIANT'; END IF;
    phases:=phases||jsonb_build_object('integrityMs',extract(epoch from clock_timestamp()-phase_at)*1000,'totalMs',extract(epoch from clock_timestamp()-started_at)*1000);
    result:=jsonb_build_object('ok',true,'replayed',false,'idempotencyKey',p_idempotency_key,'serverPhases',phases);
    UPDATE public.erp_idempotency_keys SET status='completed',canonical_result=result,completed_at=clock_timestamp()
      WHERE actor_id=actor AND idempotency_key=p_idempotency_key;
    RETURN result;
  EXCEPTION WHEN OTHERS THEN
    IF failure IS NOT NULL THEN RETURN failure; END IF;
    RETURN jsonb_build_object('ok',false,'code','TRANSACTION_REJECTED','sqlstate',SQLSTATE);
  END;
END; $function$

public.erp_apply_related_transaction(uui.definition:
CREATE OR REPLACE FUNCTION public.erp_apply_related_transaction(p_idempotency_key uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor uuid:=auth.uid(); family text; root uuid; parent_id uuid; entities text[]; entity text;
  expected jsonb; actual jsonb; ops jsonb; op jsonb; result jsonb; failure jsonb; claimed boolean;
  prior public.erp_idempotency_keys%ROWTYPE; quantity_now integer; allocated integer;
BEGIN
  IF actor IS NULL OR NOT public.is_editor(actor) THEN RAISE EXCEPTION 'RELATED_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF p_idempotency_key IS NULL OR jsonb_typeof(p_request) IS DISTINCT FROM 'object'
    OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_request) k) IS DISTINCT FROM ARRAY['expectedRecords','family','operations','rootId']::text[]
    OR jsonb_typeof(p_request->'expectedRecords') IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_request->'operations') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'RELATED_INVALID_REQUEST' USING ERRCODE='22023'; END IF;
  family:=p_request->>'family'; root:=(p_request->>'rootId')::uuid;
  entities:=CASE family WHEN 'purchase-delete' THEN ARRAY['purchase_batch_items','purchase_batches']
    WHEN 'package-delete' THEN ARRAY['japan_package_items','japan_packages']
    WHEN 'package-item-delete' THEN ARRAY['japan_package_items']
    WHEN 'manual-package-edit' THEN ARRAY['japan_package_items','outbound_shipment_items']
    WHEN 'variant-delete' THEN ARRAY['product_variants'] END;
  IF root IS NULL OR entities IS NULL
    OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_request->'expectedRecords') k) IS DISTINCT FROM (SELECT array_agg(k ORDER BY k) FROM unnest(entities) k)
    OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_request->'operations') k) IS DISTINCT FROM (SELECT array_agg(k ORDER BY k) FROM unnest(entities) k) THEN RAISE EXCEPTION 'RELATED_INVALID_SCOPE' USING ERRCODE='22023'; END IF;
  FOREACH entity IN ARRAY entities LOOP
    ops:=p_request->'operations'->entity; expected:=p_request->'expectedRecords'->entity;
    IF jsonb_typeof(ops) IS DISTINCT FROM 'array' OR jsonb_typeof(expected) IS DISTINCT FROM 'array'
      OR jsonb_array_length(ops)>10000 THEN RAISE EXCEPTION 'RELATED_INVALID_OPERATIONS' USING ERRCODE='22023'; END IF;
    FOR op IN SELECT value FROM jsonb_array_elements(ops) LOOP
      IF op->>'kind' IS DISTINCT FROM (CASE WHEN family='manual-package-edit' THEN 'patch' ELSE 'delete' END)
        OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(expected) e WHERE e->>'id'=op->>'id') THEN RAISE EXCEPTION 'RELATED_OPERATION_SCOPE_INVALID' USING ERRCODE='22023'; END IF;
      IF family='manual-package-edit' AND EXISTS(SELECT 1 FROM jsonb_object_keys(coalesce(op->'changes','{}')) k
        WHERE k NOT IN ('sku','product_title','variant_name','note') AND NOT(entity='japan_package_items' AND k='quantity')) THEN RAISE EXCEPTION 'RELATED_MANUAL_FIELDS_INVALID' USING ERRCODE='22023'; END IF;
    END LOOP;
    IF family<>'manual-package-edit' AND jsonb_array_length(ops)<>jsonb_array_length(expected) THEN RAISE EXCEPTION 'RELATED_DELETE_INCOMPLETE' USING ERRCODE='22023'; END IF;
  END LOOP;
  BEGIN
    INSERT INTO public.erp_idempotency_keys(actor_id,idempotency_key,operation_type,request_fingerprint,request_payload,status)
      VALUES(actor,p_idempotency_key,'edit',md5(p_request::text),p_request,'processing') ON CONFLICT(actor_id,idempotency_key) DO NOTHING RETURNING true INTO claimed;
    IF NOT coalesce(claimed,false) THEN
      SELECT * INTO prior FROM public.erp_idempotency_keys WHERE actor_id=actor AND idempotency_key=p_idempotency_key FOR UPDATE;
      IF prior.request_payload IS DISTINCT FROM p_request THEN RETURN jsonb_build_object('ok',false,'code','IDEMPOTENCY_KEY_PAYLOAD_MISMATCH'); END IF;
      IF prior.status<>'completed' THEN RAISE EXCEPTION 'RELATED_INCOMPLETE'; END IF;
      RETURN jsonb_set(prior.canonical_result,'{replayed}','true',true);
    END IF;
    LOCK TABLE public.product_variants,public.purchase_batches,public.purchase_batch_items,public.private_order_items,public.sales_order_items,
      public.japan_packages,public.japan_package_items,public.outbound_shipment_items,public.bundle_components,
      public.waca_order_items,public.waca_mappings,public.waca_master_links IN SHARE ROW EXCLUSIVE MODE;
    FOREACH entity IN ARRAY entities LOOP
      IF entity='product_variants' THEN
        SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version) ORDER BY id),'[]') INTO actual FROM public.product_variants
          WHERE deleted_at IS NULL AND id IN(SELECT (e->>'id')::uuid FROM jsonb_array_elements(p_request->'expectedRecords'->entity) e);
        IF jsonb_array_length(actual)=0 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual) e WHERE e->>'id'=root::text) THEN
          RAISE EXCEPTION 'RELATED_VARIANT_SCOPE_INVALID';
        END IF;
      ELSIF entity='purchase_batches' OR entity='japan_packages' THEN
        EXECUTE format('SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''version'',version) ORDER BY id),''[]''::jsonb) FROM public.%I WHERE id=$1 AND deleted_at IS NULL',entity) INTO actual USING root;
      ELSIF entity='purchase_batch_items' THEN
        SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version) ORDER BY id),'[]') INTO actual FROM public.purchase_batch_items WHERE purchase_batch_id=root AND deleted_at IS NULL;
      ELSIF entity='outbound_shipment_items' THEN
        SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version) ORDER BY id),'[]') INTO actual FROM public.outbound_shipment_items WHERE japan_package_item_id=root AND deleted_at IS NULL;
      ELSE
        SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version) ORDER BY id),'[]') INTO actual FROM public.japan_package_items
          WHERE deleted_at IS NULL AND CASE WHEN family='package-delete' THEN japan_package_id=root ELSE id=root END;
      END IF;
      IF actual IS DISTINCT FROM p_request->'expectedRecords'->entity OR
        (entity IN ('purchase_batches','japan_packages') AND jsonb_array_length(actual)<>1) OR
        (entity='japan_package_items' AND family IN ('package-item-delete','manual-package-edit') AND jsonb_array_length(actual)<>1) THEN
        failure:=jsonb_build_object('ok',false,'code','FIELD_CONFLICT','entity',entity); RAISE EXCEPTION 'RELATED_ROLLBACK';
      END IF;
    END LOOP;
    IF family='variant-delete' AND EXISTS(
      SELECT 1 FROM (
        SELECT product_variant_id id FROM public.purchase_batch_items WHERE deleted_at IS NULL
        UNION ALL SELECT product_variant_id FROM public.private_order_items WHERE deleted_at IS NULL
        UNION ALL SELECT product_variant_id FROM public.sales_order_items WHERE deleted_at IS NULL
        UNION ALL SELECT product_variant_id FROM public.japan_package_items WHERE deleted_at IS NULL
        UNION ALL SELECT product_variant_id FROM public.outbound_shipment_items WHERE deleted_at IS NULL
        UNION ALL SELECT bundle_variant_id FROM public.bundle_components
        UNION ALL SELECT component_variant_id FROM public.bundle_components
        UNION ALL SELECT product_variant_id FROM public.waca_order_items
        UNION ALL SELECT product_variant_id FROM public.waca_mappings
        UNION ALL SELECT product_variant_id FROM public.waca_master_links
      ) refs WHERE refs.id IN(SELECT (e->>'id')::uuid FROM jsonb_array_elements(p_request->'expectedRecords'->'product_variants') e)
    ) THEN failure:=jsonb_build_object('ok',false,'code','DEPENDENT_RECORDS_EXIST');RAISE EXCEPTION 'RELATED_ROLLBACK';END IF;
    IF family='variant-delete' AND EXISTS(SELECT 1 FROM public.product_variants WHERE deleted_at IS NULL
      AND id IN(SELECT (e->>'id')::uuid FROM jsonb_array_elements(p_request->'expectedRecords'->'product_variants') e)
      AND (coalesce(myacg_manual_adjustment,0)<>0 OR coalesce(waca_manual_adjustment,0)<>0
        OR coalesce(private_manual_adjustment,0)<>0 OR coalesce(purchased_manual_adjustment,0)<>0
        OR coalesce(myacg_auto_quantity,0)<>0 OR coalesce(effective_myacg_quantity,0)<>0 OR coalesce(waca_auto_quantity,0)<>0)) THEN
      failure:=jsonb_build_object('ok',false,'code','DEPENDENT_RECORDS_EXIST'); RAISE EXCEPTION 'RELATED_ROLLBACK';
    END IF;
    IF family='purchase-delete' AND EXISTS(SELECT 1 FROM public.japan_package_items j WHERE j.deleted_at IS NULL AND
      (j.purchase_batch_id=root OR j.purchase_batch_item_id IN(SELECT id FROM public.purchase_batch_items WHERE purchase_batch_id=root))) THEN
      failure:=jsonb_build_object('ok',false,'code','DEPENDENT_RECORDS_EXIST'); RAISE EXCEPTION 'RELATED_ROLLBACK';
    END IF;
    IF family IN('package-delete','package-item-delete') AND EXISTS(SELECT 1 FROM public.outbound_shipment_items o
      JOIN public.japan_package_items j ON j.id=o.japan_package_item_id WHERE o.deleted_at IS NULL AND
      CASE WHEN family='package-delete' THEN j.japan_package_id=root ELSE j.id=root END) THEN
      failure:=jsonb_build_object('ok',false,'code','DEPENDENT_RECORDS_EXIST'); RAISE EXCEPTION 'RELATED_ROLLBACK';
    END IF;
    IF family IN('package-item-delete','manual-package-edit') THEN
      SELECT japan_package_id INTO parent_id FROM public.japan_package_items WHERE id=root AND deleted_at IS NULL;
    END IF;
    IF family='manual-package-edit' AND EXISTS(SELECT 1 FROM public.japan_package_items WHERE id=root
      AND (product_variant_id IS NOT NULL OR purchase_batch_item_id IS NOT NULL)) THEN RAISE EXCEPTION 'RELATED_NOT_MANUAL_ITEM'; END IF;
    FOREACH entity IN ARRAY entities LOOP
      ops:=p_request->'operations'->entity;
      IF jsonb_array_length(ops)>0 THEN result:=public.erp_apply_field_mutations(entity,ops);
        IF result->>'ok' IS DISTINCT FROM 'true' THEN failure:=result; RAISE EXCEPTION 'RELATED_ROLLBACK'; END IF;
      END IF;
    END LOOP;
    IF family='manual-package-edit' THEN
      SELECT quantity INTO quantity_now FROM public.japan_package_items WHERE id=root;
      SELECT coalesce(sum(quantity),0) INTO allocated FROM public.outbound_shipment_items WHERE japan_package_item_id=root AND deleted_at IS NULL;
      IF quantity_now<=0 OR quantity_now<allocated THEN RAISE EXCEPTION 'RELATED_QUANTITY_INVALID'; END IF;
      IF EXISTS(SELECT 1 FROM public.outbound_shipment_items o JOIN public.japan_package_items j ON j.id=o.japan_package_item_id
        WHERE j.id=root AND o.deleted_at IS NULL AND
          (o.sku IS DISTINCT FROM j.sku OR o.product_title IS DISTINCT FROM j.product_title
            OR o.variant_name IS DISTINCT FROM j.variant_name OR o.note IS DISTINCT FROM j.note)) THEN RAISE EXCEPTION 'RELATED_MIRROR_INVALID'; END IF;
    END IF;
    IF parent_id IS NOT NULL THEN
      UPDATE public.japan_packages p SET
        status=CASE WHEN EXISTS(SELECT 1 FROM public.japan_package_items WHERE japan_package_id=parent_id AND deleted_at IS NULL)
          AND NOT EXISTS(SELECT 1 FROM public.japan_package_items WHERE japan_package_id=parent_id AND deleted_at IS NULL AND NOT checked)
          THEN 'confirmed' ELSE CASE WHEN p.status='confirmed' THEN 'arrived' ELSE p.status END END,
        arrived_at=CASE WHEN p.status='confirmed' AND p.arrived_at IS NULL THEN current_date ELSE p.arrived_at END
        WHERE p.id=parent_id AND p.status<>'problem' AND p.status IS DISTINCT FROM
          CASE WHEN EXISTS(SELECT 1 FROM public.japan_package_items WHERE japan_package_id=parent_id AND deleted_at IS NULL)
            AND NOT EXISTS(SELECT 1 FROM public.japan_package_items WHERE japan_package_id=parent_id AND deleted_at IS NULL AND NOT checked)
            THEN 'confirmed' ELSE CASE WHEN p.status='confirmed' THEN 'arrived' ELSE p.status END END;
    END IF;
    result:=jsonb_build_object('ok',true,'replayed',false,'idempotencyKey',p_idempotency_key,'parentId',parent_id);
    UPDATE public.erp_idempotency_keys SET status='completed',canonical_result=result,completed_at=clock_timestamp() WHERE actor_id=actor AND idempotency_key=p_idempotency_key;
    RETURN result;
  EXCEPTION WHEN OTHERS THEN
    IF failure IS NOT NULL THEN RETURN failure; END IF;
    RETURN jsonb_build_object('ok',false,'code','TRANSACTION_REJECTED','sqlstate',SQLSTATE);
  END;
END; $function$

public.erp_begin_cloud_restore_attempt(u.definition:
CREATE OR REPLACE FUNCTION public.erp_begin_cloud_restore_attempt(p_attempt_id uuid, p_trace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '10s'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_key text;
  v_attempt public.erp_cloud_restore_attempts%rowtype;
  v_epoch bigint;
  v_execution_id uuid;
begin
  if v_actor is null then raise exception using errcode = '42501', message = 'AUTHENTICATION_REQUIRED'; end if;
  if not public.is_owner(v_actor) then raise exception using errcode = '42501', message = 'CLOUD_RESTORE_OWNER_REQUIRED'; end if;
  v_actor_key := encode(digest(v_actor::text, 'sha256'), 'hex');
  select * into v_attempt from public.erp_cloud_restore_attempts
   where attempt_id = p_attempt_id and trace_id = p_trace_id and actor_key = v_actor_key for update;
  if not found then raise exception using errcode = '22023', message = 'CLOUD_RESTORE_ATTEMPT_NOT_FOUND'; end if;
  if v_attempt.status = 'completed' then
    return jsonb_build_object(
      'status','completed','attemptId',v_attempt.attempt_id,'traceId',v_attempt.trace_id,
      'expectedEpoch',v_attempt.expected_epoch,'effectiveFingerprint',v_attempt.effective_fingerprint,
      'resultEpoch',v_attempt.result_epoch,'restoreResult',v_attempt.canonical_result
    );
  end if;
  if v_attempt.status <> 'prepared' then
    raise exception using errcode = '55006', message = 'CLOUD_RESTORE_ATTEMPT_PENDING';
  end if;
  select epoch into strict v_epoch from public.erp_cloud_restore_epoch where singleton = true;
  if v_epoch is distinct from v_attempt.expected_epoch then
    raise exception using errcode = '55000', message = 'CLOUD_RESTORE_ATTEMPT_EPOCH_MISMATCH';
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock', 0)) then
    raise exception using errcode = '55006', message = 'CLOUD_RESTORE_LOCK_CONFLICT';
  end if;
  v_execution_id := gen_random_uuid();
  update public.erp_cloud_restore_attempts
     set status = 'executing', execution_id = v_execution_id, execution_started_at = clock_timestamp()
   where attempt_id = v_attempt.attempt_id;
  return jsonb_build_object(
    'status','executing','attemptId',v_attempt.attempt_id,'traceId',v_attempt.trace_id,
    'executionId',v_execution_id,'expectedEpoch',v_attempt.expected_epoch,
    'effectiveFingerprint',v_attempt.effective_fingerprint,
    'reconcileAfter',clock_timestamp() + (v_attempt.timeout_budget_ms + v_attempt.grace_ms) * interval '1 millisecond'
  );
end;
$function$

public.erp_upload_restore_chunk_batch(uu.definition:
CREATE OR REPLACE FUNCTION public.erp_upload_restore_chunk_batch(p_request_id uuid, p_chunks jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '25s'
AS $function$
DECLARE c jsonb;results jsonb:='[]';started timestamptz:=clock_timestamp();
BEGIN
 PERFORM public.erp_restore_upload_owner(p_request_id);
 IF jsonb_typeof(p_chunks) IS DISTINCT FROM 'array' OR jsonb_array_length(p_chunks) NOT BETWEEN 1 AND 4 THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_BATCH_INVALID'; END IF;
 -- Fail BEFORE any OPS insert. Only this explicit size rejection can be split
 -- by the client; transport/permission/validation/unknown errors are not retried.
 IF pg_column_size(p_chunks)>2097152 THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_BATCH_SIZE_LIMIT'; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p_chunks) LOOP
  IF jsonb_typeof(c) IS DISTINCT FROM 'object' OR NOT(c ?& ARRAY['p_resource','p_ordinal','p_rows'])
   OR (SELECT count(*) FROM jsonb_object_keys(c))<>3 THEN
   RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_BATCH_INVALID'; END IF;
  results:=results||jsonb_build_array(public.erp_upload_restore_chunk(p_request_id,c->>'p_resource',(c->>'p_ordinal')::integer,c->'p_rows'));
 END LOOP;
 RETURN jsonb_build_object('chunks',results,'serverMs',(extract(epoch FROM clock_timestamp()-started)*1000)::bigint);
END;
$function$

public.erp_assert_waca_recognition_prese.definition:
CREATE OR REPLACE FUNCTION public.erp_assert_waca_recognition_preserved(p_snapshot jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r jsonb; old_batch jsonb; old_item public.waca_order_items%rowtype; q integer; epoch bigint;
begin
  select e.epoch into epoch from public.erp_cloud_restore_epoch e where singleton;
  for r in select value from jsonb_array_elements(coalesce(p_snapshot->'items','[]')) loop
    select * into old_item from public.waca_order_items where item_key=r->>'key';
    if (r->'recognition') is distinct from (old_item.payload->'recognition') then
      raise exception using errcode='23000',message='WACA_OWNER_DECISION_IMMUTABLE';
    end if;
    if old_item.payload->'recognition' is not null then
      if r->>'orderKey' is distinct from old_item.payload->>'orderKey'
        or public.erp_waca_variant_id(r->>'productVariantId') is distinct from old_item.product_variant_id then
        raise exception using errcode='23000',message='WACA_MANAGED_IDENTITY_CHANGED';
      end if;
      select case when coalesce((select o->>'status' from jsonb_array_elements(coalesce(p_snapshot->'orders','[]')) o
          where o->>'key'=r->>'orderKey'),(select status from public.waca_orders where id=old_item.order_id))
          in ('處理中','完成付款') then (r->>'quantity')::integer else 0 end into q;
      if old_item.payload->'recognition'->>'mode'='COUNT'
        and (r->>'countedQuantity')::integer is distinct from (old_item.payload->>'countedQuantity')::integer
        and (old_item.payload->'recognition'->>'restoreEpoch')::bigint is distinct from epoch then
        raise exception using errcode='23000',message='WACA_MANAGED_RESTORE_REVIEW_REQUIRED';
      end if;
      if old_item.payload->'recognition'->>'mode' in ('INCLUDED','HOLD') and (r->>'countedQuantity')::integer<>0
        or old_item.payload->'recognition'->>'mode'='COUNT' and (r->>'countedQuantity')::integer not in
          (q,(old_item.payload->>'countedQuantity')::integer) then
        raise exception using errcode='23000',message='WACA_OWNER_DECISION_CONFLICT';
      end if;
      if old_item.payload->'recognition'->>'mode'='INCLUDED' and r->>'countedReason' is distinct from 'BASELINE_INCLUDED'
        or old_item.payload->'recognition'->>'mode'='HOLD' and r->>'countedReason' is distinct from 'PENDING_REVIEW'
        or old_item.payload->'recognition'->>'mode'='COUNT' and coalesce(r->>'countedReason','') not in ('OWNER_CONFIRMED_NEW','SOURCE_CHANGE_APPLIED') then
        raise exception using errcode='23000',message='WACA_OWNER_DECISION_CONFLICT';
      end if;
      if (r->>'countedQuantity')::integer < (old_item.payload->>'countedQuantity')::integer
        and not public.erp_waca_reversal_proven(old_item.product_variant_id,epoch,old_item.item_key) then
        raise exception using errcode='23000',message='WACA_REVERSAL_PROOF_REQUIRED';
      end if;
    end if;
  end loop;
  for r in select value from jsonb_array_elements(coalesce(p_snapshot->'batches','[]')) loop
    select b.payload into old_batch from public.waca_import_batches b where b.batch_key=r->>'id';
    if (r->'recognition' is not null or old_batch->'recognition' is not null) and r is distinct from old_batch then
      raise exception using errcode='23000',message='WACA_RECOGNITION_RECEIPT_IMMUTABLE';
    end if;
  end loop;
  for r in select value from jsonb_array_elements(coalesce(p_snapshot->'cutoverAudit','[]')) loop
    if (r->'recognitionContinuity') is distinct from (select a.payload->'recognitionContinuity' from public.waca_cutover_audit a
      where a.product_variant_id=public.erp_waca_variant_id(r->>'productVariantId')) then
      raise exception using errcode='23000',message='WACA_RECOGNITION_PROOF_IMMUTABLE';
    end if;
  end loop;
end;
$function$

public.erp_stage_restore_upload_resource.definition:
CREATE OR REPLACE FUNCTION public.erp_stage_restore_upload_resource(p_request_id uuid, p_resource text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '25s'
AS $function$
DECLARE r public.erp_restore_upload_requests%rowtype;c record;rows jsonb;projected jsonb:='[]';
 columns_sql text;select_sql text;profile jsonb;transformed bigint:=0;n bigint:=0;
 started timestamptz:=clock_timestamp();existing jsonb;policy text;source_fp text;invalid_row jsonb;phase_at timestamptz;phase_timings jsonb:='{}';
BEGIN
 r:=public.erp_restore_upload_owner(p_request_id);
 IF r.completed_result IS NOT NULL THEN RETURN jsonb_build_object('resource',p_resource,'completed',true); END IF;
 IF NOT(r.manifest->'counts' ? p_resource) OR p_resource<>ALL(ARRAY[
  'inventory_items','product_groups','product_categories','product_variants','bundle_components',
  'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
  'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
  'waca_orders','waca_order_items','waca_mappings','waca_master_links','waca_import_batches','waca_cutover_audit','waca_state']) THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_RESOURCE_NOT_ALLOWED'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('erp-restore-stage:'||p_request_id||':'||p_resource,0)) THEN
  RAISE EXCEPTION USING errcode='55006',message='CLOUD_RESTORE_UPLOAD_BUSY'; END IF;
 IF r.source_generation IS DISTINCT FROM (SELECT generation FROM public.erp_restore_business_generation WHERE singleton)
  OR r.source_epoch IS DISTINCT FROM (SELECT epoch FROM public.erp_cloud_restore_epoch WHERE singleton) THEN
  RAISE EXCEPTION USING errcode='55000',message='STALE_RESTORE_PREPARE'; END IF;
 SELECT rp.profile INTO existing FROM public.erp_restore_upload_resource_proofs rp WHERE request_id=p_request_id AND resource=p_resource;
 IF FOUND THEN RETURN jsonb_build_object('resource',p_resource,'profile',existing,'replayed',true); END IF;
 IF (SELECT coalesce(sum(jsonb_array_length(ch.rows)),0) FROM public.erp_restore_upload_chunks ch
  WHERE request_id=p_request_id AND resource=p_resource) IS DISTINCT FROM (r.manifest->'counts'->>p_resource)::bigint THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_INCOMPLETE'; END IF;
 policy:=CASE WHEN r.restore_mode='strict' THEN 'strict' ELSE 'cross-environment-audit-null-v1' END;
 source_fp:=CASE WHEN r.restore_mode='strict' THEN r.manifest->>'snapshotFingerprint'
  ELSE r.manifest->'portability'->>'sourceSnapshotFingerprint' END;
 -- An incomplete proof is deliberately unexecutable: hash, relationship and
 -- source CAS stay NULL until final canonical validation succeeds atomically.
 IF NOT EXISTS(SELECT 1 FROM public.erp_cloud_restore_candidate_proofs p WHERE p.proof_id=p_request_id
  AND p.actor_key=r.actor_key AND p.manifest=r.manifest AND p.prepared_payload_hash IS NULL) THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_IDENTITY_MISMATCH'; END IF;
 phase_at:=clock_timestamp();
 WITH supplied_columns AS MATERIALIZED (
  SELECT DISTINCT supplied.key FROM public.erp_restore_upload_chunks ch
   CROSS JOIN LATERAL jsonb_array_elements(ch.rows) row_value
   CROSS JOIN LATERAL jsonb_object_keys(row_value) supplied(key)
  WHERE ch.request_id=p_request_id AND ch.resource=p_resource
  UNION SELECT 'updated_by' WHERE r.restore_mode='cross-environment'
 ) SELECT string_agg(quote_ident(a.attname),',' ORDER BY a.attnum),
  string_agg('v.'||quote_ident(a.attname),',' ORDER BY a.attnum)
 INTO columns_sql,select_sql FROM pg_attribute a JOIN supplied_columns s ON s.key=a.attname
 WHERE a.attrelid=format('public.%I',p_resource)::regclass AND a.attnum>0 AND NOT a.attisdropped AND a.attgenerated='';
 phase_timings:=jsonb_build_object('columns',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();
 FOR c IN SELECT * FROM public.erp_restore_upload_chunks WHERE request_id=p_request_id AND resource=p_resource ORDER BY ordinal LOOP
  rows:=c.rows;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(rows) x WHERE jsonb_typeof(x) IS DISTINCT FROM 'object') THEN
   RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_AUDIT_ROW_INVALID'; END IF;
  SELECT x INTO invalid_row FROM jsonb_array_elements(rows) x
   WHERE coalesce(btrim(x->>'id'),'') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' LIMIT 1;
  IF FOUND THEN
   IF p_resource=ANY(ARRAY['waca_orders','waca_order_items','waca_mappings','waca_master_links','waca_import_batches','waca_cutover_audit','waca_state']) THEN
    PERFORM public.erp_cloud_restore_validation_error(p_resource,coalesce(invalid_row->>'id','unknown'),'WACA_CANONICAL_IDENTITY_MISSING');
   END IF;
   RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_IDENTITY_REQUIRED:'||p_resource;
  END IF;
  IF r.restore_mode='cross-environment' THEN
   SELECT count(*) FILTER(WHERE x ? 'updated_by' AND jsonb_typeof(x->'updated_by') IS DISTINCT FROM 'null'),
    json_agg(x||jsonb_build_object('updated_by',NULL) ORDER BY ord)::jsonb
   INTO n,rows FROM jsonb_array_elements(rows) WITH ORDINALITY s(x,ord);
   transformed:=transformed+n;
  END IF;
  INSERT INTO public.erp_cloud_restore_prepared_chunks(proof_id,actor_key,resource,chunk_ordinal,row_count,rows,payload_hash,expires_at)
  SELECT p_request_id,r.actor_key,p_resource,c.ordinal*2+((ord-1)/256)::integer,count(*)::integer,
   json_agg(x ORDER BY ord)::jsonb,
   encode(extensions.digest(convert_to((json_agg(x ORDER BY ord)::jsonb)::text,'UTF8'),'sha256'),'hex'),r.expires_at
  FROM jsonb_array_elements(rows) WITH ORDINALITY s(x,ord) GROUP BY ((ord-1)/256)::integer;

 END LOOP;
 phase_timings:=phase_timings||jsonb_build_object('immutableChunks',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();
 -- Aggregate each resource ONCE; preserve exact transformed rows and ordering.
  SELECT coalesce(json_agg(public.erp_restore_validation_projection(x)||
   CASE WHEN NOT(x ? 'payload') THEN '{}'::jsonb
    WHEN jsonb_typeof(x->'payload')='object' THEN jsonb_build_object('payload',
     CASE WHEN x->'payload' ? 'key' THEN jsonb_build_object('key',x->'payload'->'key') ELSE '{}'::jsonb END)
    ELSE jsonb_build_object('payload',x->'payload') END ORDER BY ch.chunk_ordinal,ord),'[]'::json)::jsonb
  INTO projected FROM public.erp_cloud_restore_prepared_chunks ch
   CROSS JOIN LATERAL jsonb_array_elements(ch.rows) WITH ORDINALITY s(x,ord)
  WHERE ch.proof_id=p_request_id AND ch.resource=p_resource;
 phase_timings:=phase_timings||jsonb_build_object('validationProjection',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();
 profile:=public.erp_cloud_restore_prepared_profile(p_request_id,p_resource);
 IF (profile->>'missingIdentityCount')::bigint>0 THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_IDENTITY_REQUIRED:'||p_resource; END IF;
 IF (profile->>'duplicateIdentityCount')::bigint>0 THEN
  RAISE EXCEPTION USING errcode='23505',message='DUPLICATE_CANONICAL_ID:'||p_resource; END IF;
 IF p_resource='product_variants' AND (profile->>'duplicateAuxiliaryIdentityCount')::bigint>0 THEN
  RAISE EXCEPTION USING errcode='23505',message='DUPLICATE_VARIANT_LOCAL_ID'; END IF;
 phase_timings:=phase_timings||jsonb_build_object('identityProof',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 phase_at:=clock_timestamp();
 IF columns_sql IS NOT NULL THEN
  -- One set-based typed write per resource, not one dynamic INSERT per chunk.
  -- Omitted columns/defaults, supplied-column order and raw types are unchanged.
  EXECUTE format('insert into public.%I (restore_proof_id,%s) select $1,%s from public.erp_cloud_restore_prepared_chunks ch cross join lateral jsonb_populate_recordset(null::public.%I,ch.rows) v where ch.proof_id=$1 and ch.resource=$2',
   'erp_restore_stage_'||p_resource,columns_sql,select_sql,p_resource) USING p_request_id,p_resource;
 END IF;
 phase_timings:=phase_timings||jsonb_build_object('typedStage',(extract(epoch FROM clock_timestamp()-phase_at)*1000)::bigint);
 INSERT INTO public.erp_restore_upload_resource_proofs(request_id,resource,validation_rows,supplied_columns,profile,transformed_rows,server_ms)
 VALUES(p_request_id,p_resource,projected,columns_sql,profile,transformed,(extract(epoch FROM clock_timestamp()-started)*1000)::bigint);
 RETURN jsonb_build_object('resource',p_resource,'profile',profile,'phaseTimingsMs',phase_timings,'serverMs',(extract(epoch FROM clock_timestamp()-started)*1000)::bigint);
END;
$function$

public.erp_cloud_restore_insert_rows(reg.definition:
CREATE OR REPLACE FUNCTION public.erp_cloud_restore_insert_rows(p_table regclass, p_rows jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_columns text;
  v_count bigint;
  v_timestamp_count bigint;
  v_timestamp_mismatch_count bigint;
BEGIN
  IF p_table NOT IN (
    'public.inventory_items'::regclass,'public.product_groups'::regclass,'public.product_categories'::regclass,
    'public.product_variants'::regclass,'public.bundle_components'::regclass,'public.purchase_batches'::regclass,
    'public.purchase_batch_items'::regclass,'public.private_orders'::regclass,'public.private_order_items'::regclass,
    'public.sales_orders'::regclass,'public.sales_order_items'::regclass,'public.japan_packages'::regclass,
    'public.japan_package_items'::regclass,'public.outbound_shipments'::regclass,'public.outbound_shipment_items'::regclass,'public.import_batches'::regclass,
    'public.dashboard_category_images'::regclass,
    'public.waca_orders'::regclass,'public.waca_order_items'::regclass,
    'public.waca_mappings'::regclass,'public.waca_master_links'::regclass,
    'public.waca_import_batches'::regclass,'public.waca_cutover_audit'::regclass,
    'public.waca_state'::regclass
  ) THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'CLOUD_RESTORE_TABLE_NOT_ALLOWED';
  END IF;
  IF jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'CLOUD_RESTORE_RESOURCE_NOT_ARRAY';
  END IF;
  IF jsonb_array_length(p_rows) = 0 THEN RETURN 0; END IF;
  SELECT string_agg(quote_ident(a.attname), ',' ORDER BY a.attnum)
    INTO v_columns
    FROM pg_attribute a
   WHERE a.attrelid = p_table AND a.attnum > 0 AND NOT a.attisdropped AND a.attgenerated = ''
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_rows) row_value WHERE row_value ? a.attname);
  IF v_columns IS NULL THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'CLOUD_RESTORE_NO_ALLOWED_COLUMNS';
  END IF;
  EXECUTE format(
    'insert into %s (%s) select %s from jsonb_populate_recordset(null::%s, $1)',
    p_table, v_columns, v_columns, p_table
  ) USING p_rows;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- The INSERT trigger intentionally assigns the current clock time for normal
  -- business inserts. Atomic Restore corrects only its own inserted rows from
  -- the exact backup payload, inside the same transaction and before the
  -- caller performs the canonical integrity audit and COMMIT.
  IF p_table = 'public.outbound_shipments'::regclass THEN
    IF EXISTS (
      SELECT 1
        FROM jsonb_array_elements(p_rows) AS restored(row_value)
       WHERE jsonb_typeof(restored.row_value) IS DISTINCT FROM 'object'
          OR NOT (restored.row_value ? 'id')
          OR NOT (restored.row_value ? 'status_changed_at')
    ) THEN
      RAISE EXCEPTION USING errcode = '22023',
        message = 'CLOUD_RESTORE_OUTBOUND_TIMESTAMP_EVIDENCE_MISSING';
    END IF;

    WITH restored AS (
      SELECT row_data.id, row_data.status_changed_at
        FROM jsonb_to_recordset(p_rows)
          AS row_data(id uuid, status_changed_at timestamptz)
    )
    UPDATE public.outbound_shipments target
       SET status_changed_at = restored.status_changed_at
      FROM restored
     WHERE target.id = restored.id;
    GET DIAGNOSTICS v_timestamp_count = ROW_COUNT;
    IF v_timestamp_count IS DISTINCT FROM v_count THEN
      RAISE EXCEPTION USING errcode = '55000',
        message = 'CLOUD_RESTORE_OUTBOUND_TIMESTAMP_ROW_COUNT_MISMATCH';
    END IF;

    WITH restored AS (
      SELECT row_data.id, row_data.status_changed_at
        FROM jsonb_to_recordset(p_rows)
          AS row_data(id uuid, status_changed_at timestamptz)
    )
    SELECT count(*)
      INTO v_timestamp_mismatch_count
      FROM restored
      LEFT JOIN public.outbound_shipments target ON target.id = restored.id
     WHERE target.id IS NULL
        OR target.status_changed_at IS DISTINCT FROM restored.status_changed_at;
    IF v_timestamp_mismatch_count IS DISTINCT FROM 0 THEN
      RAISE EXCEPTION USING errcode = '55000',
        message = 'CLOUD_RESTORE_OUTBOUND_TIMESTAMP_MISMATCH';
    END IF;
  END IF;

  RETURN v_count;
END;
$function$

public.erp_inventory_import_core(uuid,js.definition:
CREATE OR REPLACE FUNCTION public.erp_inventory_import_core(p_key uuid, p_request jsonb, p_commit boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE
  actor uuid:=auth.uid(); receipt public.erp_idempotency_keys%ROWTYPE;
  ops jsonb; problem jsonb; shape record; keys text[]; columns_sql text; values_sql text;
  affected integer; total integer:=0; epoch bigint; result jsonb; rows jsonb;
  started timestamptz:=clock_timestamp(); phase_at timestamptz; phases jsonb;
  allowed constant text[]:=ARRAY['inventory_key','myacg_item_code','myacg_parent_code','product_id',
    'product_title','normalized_product_title','raw_variant_name','listing_type','final_price',
    'myacg_available_quantity','myacg_sold_quantity','myacg_demand_quantity','myacg_listed_at',
    'import_sort_index','latest_catalog_import_id','catalog_last_seen_at'];
BEGIN
  IF actor IS NULL OR NOT public.is_editor(actor) THEN
    RAISE EXCEPTION 'INVENTORY_IMPORT_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF p_key IS NULL OR jsonb_typeof(p_request) IS DISTINCT FROM 'object'
    OR p_request->>'family' IS DISTINCT FROM 'inventory_import'
    OR coalesce(p_request->>'batchId','') !~ '^catalog_import_[0-9a-f-]{36}$'
    OR jsonb_typeof(p_request->'restoreEpoch') IS DISTINCT FROM 'number'
    OR (p_request->>'restoreEpoch') !~ '^[0-9]+$'
    OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_request) k)
       IS DISTINCT FROM ARRAY['batchId','family','operations','restoreEpoch']::text[] THEN
    RAISE EXCEPTION 'INVENTORY_IMPORT_REQUEST_INVALID' USING ERRCODE='22023';
  END IF;
  ops:=p_request->'operations';
  IF jsonb_typeof(ops) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'INVENTORY_IMPORT_OPERATIONS_INVALID' USING ERRCODE='22023';
  END IF;
  IF jsonb_array_length(ops)>10000 THEN
    RAISE EXCEPTION 'INVENTORY_IMPORT_OPERATIONS_LIMIT' USING ERRCODE='22023';
  END IF;
  -- Same maintenance fence as business-generation triggers. Never wait behind
  -- an active Restore and then apply an old-generation intent.
  IF NOT pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) THEN
    RAISE EXCEPTION 'CLOUD_RESTORE_MAINTENANCE_LOCKED' USING ERRCODE='55006';
  END IF;
  SELECT e.epoch INTO STRICT epoch FROM public.erp_cloud_restore_epoch e WHERE e.singleton;
  IF epoch IS DISTINCT FROM (p_request->>'restoreEpoch')::bigint THEN
    RETURN jsonb_build_object('ok',false,'code','STALE_AFTER_RESTORE');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('inventory-import:'||actor::text||':'||p_key::text,0));
  SELECT * INTO receipt FROM public.erp_idempotency_keys WHERE actor_id=actor AND idempotency_key=p_key;
  IF FOUND THEN
    IF receipt.request_payload IS DISTINCT FROM p_request THEN
      RETURN jsonb_build_object('ok',false,'code','IDEMPOTENCY_KEY_PAYLOAD_MISMATCH');
    END IF;
    IF receipt.status<>'completed' THEN RETURN jsonb_build_object('ok',false,'code','INVENTORY_COMMIT_UNKNOWN'); END IF;
    RETURN receipt.canonical_result||jsonb_build_object('outcome','COMMITTED','replayed',true);
  END IF;
  -- Shape validation occurs before casting/expanding untrusted JSON.
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(ops) o WHERE jsonb_typeof(o)<>'object'
    OR coalesce(o->>'id','') !~ '^[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$'
    OR coalesce(o->>'kind','') NOT IN ('create','patch')) THEN
    RAISE EXCEPTION 'INVENTORY_IMPORT_OPERATION_INVALID' USING ERRCODE='22023';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(ops) o GROUP BY (o->>'id')::uuid HAVING count(*)>1) THEN
    RAISE EXCEPTION 'CLOUD_FIELD_CAS_DUPLICATE_OPERATION_ID' USING ERRCODE='22023';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(ops) o WHERE
    (o->>'kind'='create' AND jsonb_typeof(o->'values') IS DISTINCT FROM 'object') OR
    (o->>'kind'='patch' AND (jsonb_typeof(o->'changes') IS DISTINCT FROM 'object'
      OR jsonb_typeof(o->'expected') IS DISTINCT FROM 'object' OR o->'changes'='{}'
      OR jsonb_typeof(o->'observedVersion') IS DISTINCT FROM 'number'))) THEN
    RAISE EXCEPTION 'CLOUD_FIELD_CAS_PATCH_INVALID' USING ERRCODE='22023';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(ops) o WHERE
    (CASE WHEN o->>'kind'='create' THEN o->'values' ELSE o->'changes' END) - allowed <> '{}') THEN
    RAISE EXCEPTION 'CLOUD_FIELD_CAS_FIELD_NOT_ALLOWED' USING ERRCODE='22023';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(ops) o
    CROSS JOIN LATERAL jsonb_object_keys(o->'changes') k WHERE o->>'kind'='patch' AND NOT (o->'expected' ? k))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(ops) o
    CROSS JOIN LATERAL jsonb_object_keys(o->'expected') k WHERE o->>'kind'='patch' AND NOT (o->'changes' ? k)) THEN
    RAISE EXCEPTION 'CLOUD_FIELD_CAS_EXPECTED_KEYS_MISMATCH' USING ERRCODE='22023';
  END IF;
  phases:=jsonb_build_object('validationMs',extract(epoch FROM clock_timestamp()-started)*1000);
  phase_at:=clock_timestamp();
  -- The shared business-generation maintenance fence above is already exclusive
  -- across business writers. Existing rows additionally use ordered row locks;
  -- PK/unique constraints arbitrate new identities. Do not allocate 10,000
  -- advisory lock entries: lock-table capacity is finite on small Live compute.
  PERFORM i.id FROM public.inventory_items i JOIN jsonb_array_elements(ops) o ON i.id=(o->>'id')::uuid
    ORDER BY i.id FOR UPDATE OF i;
  phases:=phases||jsonb_build_object('lockMs',extract(epoch FROM clock_timestamp()-phase_at)*1000);
  phase_at:=clock_timestamp();
  WITH candidates AS MATERIALIZED (
    SELECT o, i.id, i.deleted_at, to_jsonb(i) current_row
    FROM jsonb_array_elements(ops) o LEFT JOIN public.inventory_items i ON i.id=(o->>'id')::uuid
  ), failures AS (
    SELECT o->>'id' id, CASE
      WHEN o->>'kind'='create' AND id IS NOT NULL THEN 'DUPLICATE_CREATE'
      WHEN o->>'kind'='patch' AND (id IS NULL OR deleted_at IS NOT NULL) THEN 'RECORD_DELETED_OR_MISSING'
      WHEN o->>'kind'='patch' AND EXISTS(SELECT 1 FROM jsonb_each(o->'expected') e
        WHERE current_row->e.key IS DISTINCT FROM e.value) THEN 'FIELD_CONFLICT' END code
    FROM candidates
  ) SELECT jsonb_build_object('ok',false,'code',code,'recordId',id,'entity','inventory_items')
    INTO problem FROM failures WHERE code IS NOT NULL ORDER BY id LIMIT 1;
  IF problem IS NOT NULL THEN RETURN problem; END IF;
  -- Keys, including tombstones, are never transferred to a different UUID.
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(ops) o JOIN public.inventory_items i ON
    i.inventory_key=(CASE WHEN o->>'kind'='create' THEN o->'values' ELSE o->'changes' END)->>'inventory_key'
    WHERE i.id<>(o->>'id')::uuid) THEN
    RETURN jsonb_build_object('ok',false,'code','INVENTORY_IDENTITY_REPLACEMENT_FORBIDDEN');
  END IF;
  phases:=phases||jsonb_build_object('casMs',extract(epoch FROM clock_timestamp()-phase_at)*1000);
  IF NOT p_commit THEN
    RETURN jsonb_build_object('ok',true,'outcome','NOT_COMMITTED','restoreEpoch',epoch);
  END IF;
  phase_at:=clock_timestamp();
  -- Field-shape batching preserves omitted-field defaults and explicit NULLs.
  -- Business replacement is ONE transaction; no per-row SQL or result concat.
  FOR shape IN
    SELECT kind, field_keys, jsonb_agg(payload ORDER BY payload->>'id') payloads, count(*) expected_count
    FROM (
      SELECT o->>'kind' kind,
        ARRAY(SELECT k FROM jsonb_object_keys(CASE WHEN o->>'kind'='create' THEN o->'values' ELSE o->'changes' END) k ORDER BY k) field_keys,
        (CASE WHEN o->>'kind'='create' THEN o->'values' ELSE o->'changes' END)||jsonb_build_object('id',o->>'id') payload
      FROM jsonb_array_elements(ops) o
    ) prepared GROUP BY kind,field_keys ORDER BY kind,field_keys
  LOOP
    keys:=shape.field_keys;
    IF shape.kind='create' THEN
      columns_sql:=array_to_string(ARRAY(SELECT format('%I',k) FROM unnest(keys) k),',');
      values_sql:=array_to_string(ARRAY(SELECT format('t.%I',k) FROM unnest(keys) k),',');
      EXECUTE format('INSERT INTO public.inventory_items(id,updated_by%s) SELECT t.id,auth.uid()%s FROM jsonb_populate_recordset(NULL::public.inventory_items,$1) t',
        CASE WHEN cardinality(keys)>0 THEN ','||columns_sql ELSE '' END,
        CASE WHEN cardinality(keys)>0 THEN ','||values_sql ELSE '' END) USING shape.payloads;
    ELSE
      columns_sql:=array_to_string(ARRAY(SELECT format('%I=t.%I',k,k) FROM unnest(keys) k),',');
      EXECUTE format('UPDATE public.inventory_items i SET %s,version=i.version+1,updated_at=clock_timestamp(),updated_by=auth.uid(),sync_status=''synced'' FROM jsonb_populate_recordset(NULL::public.inventory_items,$1) t WHERE i.id=t.id',columns_sql) USING shape.payloads;
    END IF;
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected<>shape.expected_count THEN RAISE EXCEPTION 'INVENTORY_WRITE_COUNT_MISMATCH'; END IF;
    total:=total+affected;
  END LOOP;
  phases:=phases||jsonb_build_object('writeMs',extract(epoch FROM clock_timestamp()-phase_at)*1000);
  phase_at:=clock_timestamp();
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',i.id,'version',i.version,'key',i.inventory_key) ORDER BY i.id),'[]')
    INTO rows FROM public.inventory_items i JOIN jsonb_array_elements(ops) o ON i.id=(o->>'id')::uuid;
  IF jsonb_array_length(rows)<>jsonb_array_length(ops) THEN RAISE EXCEPTION 'INVENTORY_RESULT_COUNT_MISMATCH'; END IF;
  phases:=phases||jsonb_build_object('resultMs',extract(epoch FROM clock_timestamp()-phase_at)*1000,
    'totalMs',extract(epoch FROM clock_timestamp()-started)*1000);
  result:=jsonb_build_object('ok',true,'outcome','COMMITTED','replayed',false,'idempotencyKey',p_key,
    'restoreEpoch',epoch,'affected',total,'rows',rows,'serverPhases',phases);
  INSERT INTO public.erp_idempotency_keys(actor_id,idempotency_key,operation_type,request_fingerprint,request_payload,status,canonical_result,completed_at)
    VALUES(actor,p_key,'edit',md5(p_request::text),p_request,'completed',result,clock_timestamp());
  RETURN result;
END; $function$

public.erp_reconcile_catalog_transaction.definition:
CREATE OR REPLACE FUNCTION public.erp_reconcile_catalog_transaction(p_idempotency_key uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '3s'
 SET lock_timeout TO '100ms'
AS $function$
DECLARE actor uuid:=auth.uid(); receipt public.erp_idempotency_keys%ROWTYPE;
BEGIN
  IF actor IS NULL OR NOT public.is_editor(actor) THEN RAISE EXCEPTION 'CATALOG_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF p_idempotency_key IS NULL OR jsonb_typeof(p_request) IS DISTINCT FROM 'object' OR p_request->>'family' IS DISTINCT FROM 'catalog' THEN
    RAISE EXCEPTION 'CATALOG_INVALID_REQUEST' USING ERRCODE='22023';
  END IF;
  -- A read-only, NOWAIT fence cannot mistake an uncommitted receipt for absence.
  -- Any concurrent mutation yields UNKNOWN rather than waiting or replaying.
  BEGIN
    LOCK TABLE public.erp_idempotency_keys IN SHARE MODE NOWAIT;
  EXCEPTION WHEN lock_not_available THEN
    RETURN jsonb_build_object('outcome','UNKNOWN','code','CATALOG_REQUEST_IN_FLIGHT');
  END;
  SELECT * INTO receipt FROM public.erp_idempotency_keys WHERE actor_id=actor AND idempotency_key=p_idempotency_key;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','NOT_COMMITTED','code','CATALOG_RECEIPT_ABSENT'); END IF;
  IF receipt.request_payload IS DISTINCT FROM p_request THEN
    RETURN jsonb_build_object('outcome','UNKNOWN','code','IDEMPOTENCY_KEY_PAYLOAD_MISMATCH');
  END IF;
  IF receipt.status='completed' AND receipt.canonical_result->>'ok'='true' THEN
    RETURN jsonb_build_object('outcome','COMMITTED','code','CATALOG_RECONCILED_COMMITTED','result',receipt.canonical_result);
  END IF;
  RETURN jsonb_build_object('outcome','UNKNOWN','code','CATALOG_RECEIPT_INCOMPLETE');
END; $function$

public.erp_apply_catalog_fields_set_base.definition:
CREATE OR REPLACE FUNCTION public.erp_apply_catalog_fields_set_based(p_entity text, p_operations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_table regclass;
  v_create_allowed text[];
  v_patch_allowed text[];
  v_reorder_allowed text[] := ARRAY[]::text[];
  v_operation jsonb;
  v_kind text;
  v_id uuid;
  v_current jsonb;
  v_values jsonb;
  v_changes jsonb;
  v_expected jsonb;
  v_keys text[];
  v_key text;
  v_set_sql text;
  v_columns_sql text;
  v_values_sql text;
  v_shape record;
  v_affected integer;
  v_total integer := 0;
  v_conflicts jsonb;
  v_expected_version integer;
  v_seen_ids text[] := ARRAY[]::text[];
  v_protected constant text[] := ARRAY[
    'id', 'created_at', 'updated_at', 'updated_by', 'version', 'deleted_at', 'sync_status'
  ];
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_editor(auth.uid()) THEN
    RAISE EXCEPTION 'CLOUD_FIELD_CAS_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_operations) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'CLOUD_FIELD_CAS_OPERATIONS_MUST_BE_ARRAY' USING ERRCODE = '22023';
  END IF;

  -- Both table and fields are resolved exclusively from this server-owned whitelist.
  CASE p_entity
    WHEN 'product_groups' THEN
      v_table := 'public.product_groups'::regclass;
      v_create_allowed := ARRAY['local_id','title','normalized_title','listing_type','priority','purchase_date','closing_date','release_month','has_official_site','product_url','proxy_agent','show_in_purchase_list'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
    WHEN 'product_categories' THEN
      v_table := 'public.product_categories'::regclass;
      v_create_allowed := ARRAY['local_id','product_group_id','title','sort_order'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
      v_reorder_allowed := ARRAY['sort_order'];
    WHEN 'product_variants' THEN
      v_table := 'public.product_variants'::regclass;
      v_create_allowed := ARRAY['local_id','product_group_id','product_category_id','myacg_item_code','product_title','variant_name','raw_variant_name','myacg_auto_quantity','effective_myacg_quantity','myacg_manual_adjustment','waca_auto_quantity','waca_manual_adjustment','private_manual_adjustment','purchased_manual_adjustment','note','sort_order','catalog_missing','source','default_jpy_cost','default_twd_cost'];
      v_patch_allowed := array_remove(v_create_allowed, 'local_id');
      v_reorder_allowed := ARRAY['sort_order'];
    ELSE
      RAISE EXCEPTION 'CLOUD_FIELD_CAS_ENTITY_NOT_ALLOWED:%', p_entity USING ERRCODE = '22023';
  END CASE;

  -- Phase 1: deterministic advisory locks + row locks + validation. No DML occurs here.
  FOR v_operation IN
    SELECT value FROM jsonb_array_elements(p_operations) ORDER BY value->>'id', value->>'kind'
  LOOP
    v_kind := v_operation->>'kind';
    BEGIN
      v_id := (v_operation->>'id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'CLOUD_FIELD_CAS_CANONICAL_UUID_REQUIRED' USING ERRCODE = '22023';
    END;
    IF v_id IS NULL THEN RAISE EXCEPTION 'CLOUD_FIELD_CAS_CANONICAL_UUID_REQUIRED' USING ERRCODE='22023'; END IF;
    IF v_id::text = ANY(v_seen_ids) THEN
      RAISE EXCEPTION 'CLOUD_FIELD_CAS_DUPLICATE_OPERATION_ID:%', v_id USING ERRCODE = '22023';
    END IF;
    v_seen_ids := array_append(v_seen_ids, v_id::text);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_entity || ':' || v_id::text, 0));
    EXECUTE format('SELECT to_jsonb(target) FROM %s AS target WHERE target.id = $1 FOR UPDATE', v_table)
      INTO v_current USING v_id;

    IF v_kind = 'create' THEN
      IF v_current IS NOT NULL THEN
        RETURN jsonb_build_object('ok', false, 'code', 'DUPLICATE_CREATE', 'entity', p_entity, 'recordId', v_id);
      END IF;
      v_values := COALESCE(v_operation->'values', '{}'::jsonb);
      IF jsonb_typeof(v_values) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_VALUES_MUST_BE_OBJECT' USING ERRCODE = '22023';
      END IF;
      SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[]) INTO v_keys FROM jsonb_object_keys(v_values) key;
      IF v_keys && v_protected OR NOT v_keys <@ v_create_allowed THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_CREATE_FIELD_NOT_ALLOWED' USING ERRCODE = '22023';
      END IF;
    ELSIF v_kind IN ('patch', 'reorder') THEN
      IF v_current IS NULL OR (v_current ? 'deleted_at' AND v_current->'deleted_at' <> 'null'::jsonb) THEN
        RETURN jsonb_build_object('ok', false, 'code', 'RECORD_DELETED_OR_MISSING', 'entity', p_entity, 'recordId', v_id);
      END IF;
      v_changes := COALESCE(v_operation->'changes', '{}'::jsonb);
      v_expected := COALESCE(v_operation->'expected', '{}'::jsonb);
      IF jsonb_typeof(v_changes) IS DISTINCT FROM 'object' OR jsonb_typeof(v_expected) IS DISTINCT FROM 'object' OR v_changes = '{}'::jsonb THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_PATCH_INVALID' USING ERRCODE = '22023';
      END IF;
      SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[]) INTO v_keys FROM jsonb_object_keys(v_changes) key;
      IF v_keys && v_protected OR (v_kind = 'patch' AND NOT v_keys <@ v_patch_allowed) OR (v_kind = 'reorder' AND NOT v_keys <@ v_reorder_allowed) THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_PATCH_FIELD_NOT_ALLOWED' USING ERRCODE = '22023';
      END IF;
      IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v_expected) key) IS DISTINCT FROM v_keys THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_EXPECTED_KEYS_MISMATCH' USING ERRCODE = '22023';
      END IF;
      IF v_kind = 'reorder' AND (v_current->>'version')::integer IS DISTINCT FROM (v_operation->>'expectedVersion')::integer THEN
        RETURN jsonb_build_object('ok', false, 'code', 'REORDER_CONFLICT', 'entity', p_entity, 'recordId', v_id);
      END IF;
      IF v_kind = 'patch' AND jsonb_typeof(v_operation->'observedVersion') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION 'CLOUD_FIELD_CAS_OBSERVED_VERSION_REQUIRED' USING ERRCODE = '22023';
      END IF;
      SELECT COALESCE(jsonb_agg(jsonb_build_object('field', key, 'expected', v_expected->key, 'current', v_current->key) ORDER BY key), '[]'::jsonb)
        INTO v_conflicts
        FROM unnest(v_keys) key
       WHERE NOT (v_current->key IS NOT DISTINCT FROM v_expected->key);
      IF jsonb_array_length(v_conflicts) > 0 THEN
        RETURN jsonb_build_object(
          'ok', false,
          'code', CASE WHEN v_kind = 'reorder' THEN 'REORDER_CONFLICT' ELSE 'FIELD_CONFLICT' END,
          'entity', p_entity,
          'recordId', v_id,
          'conflicts', v_conflicts
        );
      END IF;
    ELSIF v_kind = 'delete' THEN
      IF v_current IS NULL OR (v_current ? 'deleted_at' AND v_current->'deleted_at' <> 'null'::jsonb) THEN
        RETURN jsonb_build_object('ok', false, 'code', 'RECORD_DELETED_OR_MISSING', 'entity', p_entity, 'recordId', v_id);
      END IF;
      v_expected_version := (v_operation->>'expectedVersion')::integer;
      IF (v_current->>'version')::integer IS DISTINCT FROM v_expected_version THEN
        RETURN jsonb_build_object('ok', false, 'code', 'STALE_DELETE', 'entity', p_entity, 'recordId', v_id);
      END IF;
    ELSE
      RAISE EXCEPTION 'CLOUD_FIELD_CAS_OPERATION_NOT_ALLOWED:%', v_kind USING ERRCODE = '22023';
    END IF;
  END LOOP;


  -- A field shape is a server-validated set of touched columns. Keeping separate
  -- shapes preserves defaults for omitted CREATE fields and explicit NULL values.
  -- No full-row RETURNING or growing JSON result is needed by the Catalog caller.
  FOR v_shape IN
    SELECT kind, keys, jsonb_agg(payload ORDER BY payload->>'id') AS payloads, count(*) AS expected_count
    FROM (
      SELECT value->>'kind' AS kind,
        ARRAY(SELECT key FROM jsonb_object_keys(CASE WHEN value->>'kind'='create'
          THEN value->'values' WHEN value->>'kind' IN ('patch','reorder') THEN value->'changes'
          ELSE '{}'::jsonb END) key ORDER BY key) AS keys,
        CASE WHEN value->>'kind'='create' THEN coalesce(value->'values','{}'::jsonb)
          WHEN value->>'kind' IN ('patch','reorder') THEN value->'changes'
          ELSE '{}'::jsonb END || jsonb_build_object('id',value->>'id') AS payload
      FROM jsonb_array_elements(p_operations)
    ) prepared
    GROUP BY kind, keys ORDER BY kind, keys
  LOOP
    v_keys := v_shape.keys;
    IF v_shape.kind='create' THEN
      v_columns_sql := array_to_string(ARRAY(SELECT format('%I', key) FROM unnest(v_keys) key), ', ');
      v_values_sql := array_to_string(ARRAY(SELECT format('typed.%I', key) FROM unnest(v_keys) key), ', ');
      EXECUTE format(
        'INSERT INTO %s (id, updated_by%s) SELECT typed.id, auth.uid()%s FROM jsonb_populate_recordset(NULL::%s,$1) typed',
        v_table, CASE WHEN cardinality(v_keys)>0 THEN ', '||v_columns_sql ELSE '' END,
        CASE WHEN cardinality(v_keys)>0 THEN ', '||v_values_sql ELSE '' END, v_table
      ) USING v_shape.payloads;
    ELSIF v_shape.kind IN ('patch','reorder') THEN
      v_set_sql := array_to_string(ARRAY(SELECT format('%I = typed.%I', key, key) FROM unnest(v_keys) key), ', ');
      EXECUTE format(
        'UPDATE %s target SET %s, version=target.version+1, updated_at=clock_timestamp(), updated_by=auth.uid(), sync_status=''synced'' FROM jsonb_populate_recordset(NULL::%s,$1) typed WHERE target.id=typed.id',
        v_table,v_set_sql,v_table
      ) USING v_shape.payloads;
    ELSE
      EXECUTE format(
        'UPDATE %s target SET deleted_at=clock_timestamp(), version=target.version+1, updated_at=clock_timestamp(), updated_by=auth.uid(), sync_status=''synced'' FROM jsonb_to_recordset($1) typed(id uuid) WHERE target.id=typed.id',
        v_table
      ) USING v_shape.payloads;
    END IF;
    GET DIAGNOSTICS v_affected = ROW_COUNT;
    IF v_affected IS DISTINCT FROM v_shape.expected_count THEN
      RAISE EXCEPTION 'CATALOG_WRITE_COUNT_MISMATCH' USING ERRCODE='22023';
    END IF;
    v_total := v_total+v_affected;
  END LOOP;
  RETURN jsonb_build_object('ok',true,'entity',p_entity,'affected',v_total);
END;
$function$

public.erp_begin_restore_upload(uuid,jso.definition:
CREATE OR REPLACE FUNCTION public.erp_begin_restore_upload(p_request_id uuid, p_manifest jsonb, p_restore_mode text, p_source_environment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE r public.erp_restore_upload_requests%rowtype;g bigint;e bigint;k text;
 started timestamptz:=clock_timestamp();
BEGIN
 IF auth.uid() IS NULL OR NOT public.is_owner(auth.uid()) THEN
  RAISE EXCEPTION USING errcode='42501',message='CLOUD_RESTORE_OWNER_REQUIRED'; END IF;
 IF split_part(lower(coalesce(nullif(current_setting('request.headers',true),'')::jsonb->>'host','')),'.',1)<>'rhfdjsklfrgpoqsaqpkn' THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_TARGET_MISMATCH'; END IF;
 IF p_request_id IS NULL OR p_restore_mode NOT IN ('strict','cross-environment')
  OR jsonb_typeof(p_manifest) IS DISTINCT FROM 'object' OR p_manifest->>'resourceCount'<>'24'
  OR jsonb_typeof(p_manifest->'counts') IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(p_manifest->'counts'))<>24
  OR length(p_source_environment) NOT BETWEEN 1 AND 2048 THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_INPUT_INVALID'; END IF;
 SELECT generation INTO STRICT g FROM public.erp_restore_business_generation WHERE singleton;
 SELECT epoch INTO STRICT e FROM public.erp_cloud_restore_epoch WHERE singleton;
 k:=encode(extensions.digest(auth.uid()::text,'sha256'),'hex');
 -- Deliberately independent of all historical OPS cleanup.
 INSERT INTO public.erp_restore_upload_requests(request_id,actor_key,manifest,restore_mode,source_environment,source_generation,source_epoch,expires_at)
  VALUES(p_request_id,k,p_manifest,p_restore_mode,p_source_environment,g,e,clock_timestamp()+interval '30 minutes')
  ON CONFLICT DO NOTHING;
 r:=public.erp_restore_upload_owner(p_request_id);
 IF r.manifest IS DISTINCT FROM p_manifest OR r.restore_mode IS DISTINCT FROM p_restore_mode
  OR r.source_environment IS DISTINCT FROM p_source_environment THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_IDENTITY_MISMATCH'; END IF;
 RETURN jsonb_build_object('requestId',p_request_id,'sourceEpoch',r.source_epoch,'sourceGeneration',r.source_generation,
  'serverMs',extract(epoch FROM clock_timestamp()-started)*1000);
EXCEPTION WHEN query_canceled THEN
 RAISE EXCEPTION USING errcode='57014',message='RESTORE_PREPARE_BEGIN_TIMEOUT',
  detail=jsonb_build_object('phase','prepare-begin','requestId',p_request_id,'reasonCode','RESTORE_PREPARE_BEGIN_TIMEOUT')::text;
END;
$function$

public.erp_cloud_restore_validate_waca_d.definition:
CREATE OR REPLACE FUNCTION public.erp_cloud_restore_validate_waca_dataset(p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_mode text;
  v_row jsonb;
  v_identity text;
  v_payload_key text;
  v_resource text;
  v_key_name text;
BEGIN
  IF p_data ? 'outbound_shipments' THEN
    SELECT value INTO v_row FROM jsonb_array_elements(p_data->'outbound_shipments')
      WHERE NOT (value ? 'status_changed_at') LIMIT 1;
    IF FOUND THEN
      PERFORM public.erp_cloud_restore_validation_error('outbound_shipments',
        coalesce(v_row->>'id','unknown'),'OUTBOUND_TIMESTAMP_EVIDENCE_MISSING');
    END IF;
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(ARRAY[
      'import_batches','waca_orders','waca_order_items','waca_mappings','waca_master_links',
      'waca_import_batches','waca_cutover_audit','waca_state'
    ]) resource WHERE jsonb_typeof(p_data->resource) IS DISTINCT FROM 'array'
  ) OR jsonb_array_length(p_data->'waca_state') <> 1 THEN
    PERFORM public.erp_cloud_restore_validation_error('waca_state','singleton','WACA_RESTORE_RESOURCE_MISSING');
  END IF;

  v_mode := p_data->'waca_state'->0->>'mode';
  IF p_data->'waca_state'->0->>'id' <> '00000000-0000-4000-8000-000000000001'
     OR v_mode NOT IN ('LEGACY_QUANTITY_ACTIVE','ORDER_REBASELINE_REQUIRED','ORDER_DRIVEN_ACTIVE')
     OR (p_data->'waca_state'->0->>'revision') !~ '^[0-9]+$' THEN
    PERFORM public.erp_cloud_restore_validation_error('waca_state','singleton','WACA_CUTOVER_STATE_INVALID');
  END IF;

  FOREACH v_resource IN ARRAY ARRAY[
    'waca_orders','waca_order_items','waca_mappings','waca_master_links',
    'waca_import_batches','waca_cutover_audit','waca_state'
  ] LOOP
    SELECT value INTO v_row
      FROM jsonb_array_elements(p_data->v_resource)
     WHERE coalesce(btrim(value->>'id'),'') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
     LIMIT 1;
    IF FOUND THEN
      PERFORM public.erp_cloud_restore_validation_error(v_resource,coalesce(v_row->>'id','unknown'),'WACA_CANONICAL_IDENTITY_MISSING');
    END IF;
  END LOOP;

  FOR v_resource, v_key_name IN
    SELECT * FROM (VALUES
      ('waca_orders','order_key'),('waca_order_items','item_key'),('waca_mappings','feature'),
      ('waca_master_links','child_code'),('waca_import_batches','batch_key'),
      ('waca_cutover_audit','product_variant_id')
    ) spec(resource,key_name)
  LOOP
    SELECT value INTO v_row
      FROM jsonb_array_elements(p_data->v_resource)
     WHERE coalesce(btrim(value->>v_key_name),'')=''
     LIMIT 1;
    IF FOUND THEN
      PERFORM public.erp_cloud_restore_validation_error(v_resource,v_key_name,'WACA_BUSINESS_KEY_MISSING');
    END IF;
    SELECT value->>v_key_name INTO v_identity
      FROM jsonb_array_elements(p_data->v_resource)
     GROUP BY value->>v_key_name
    HAVING count(*) > 1
     LIMIT 1;
    IF FOUND THEN
      PERFORM public.erp_cloud_restore_validation_error(v_resource,coalesce(v_identity,v_key_name),'WACA_DUPLICATE_BUSINESS_KEY');
    END IF;
  END LOOP;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_data->'waca_orders') LOOP
    v_identity := coalesce(v_row->>'order_key', v_row->>'id', 'unknown');
    IF v_row->>'status' NOT IN ('處理中','完成付款','取消','失敗') THEN
      PERFORM public.erp_cloud_restore_validation_error('waca_orders',v_identity,'WACA_ORDER_STATUS_INVALID');
    END IF;
    IF jsonb_typeof(v_row->'payload') IS DISTINCT FROM 'object'
       OR coalesce(btrim(v_row->'payload'->>'key'),'') = '' THEN
      PERFORM public.erp_cloud_restore_validation_error('waca_orders',v_identity,'WACA_PAYLOAD_KEY_MISSING');
    END IF;
    v_payload_key := v_row->'payload'->>'key';
    IF v_payload_key IS DISTINCT FROM v_row->>'order_key' THEN
      PERFORM public.erp_cloud_restore_validation_error('waca_orders',v_identity,'WACA_PAYLOAD_KEY_MISMATCH');
    END IF;
  END LOOP;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_data->'waca_order_items') LOOP
    v_identity := coalesce(v_row->>'item_key', v_row->>'id', 'unknown');
    IF (v_row->>'quantity') !~ '^[0-9]+$' THEN
      PERFORM public.erp_cloud_restore_validation_error('waca_order_items',v_identity,'WACA_QUANTITY_INVALID');
    END IF;
    IF jsonb_typeof(v_row->'payload') IS DISTINCT FROM 'object'
       OR coalesce(btrim(v_row->'payload'->>'key'),'') = '' THEN
      PERFORM public.erp_cloud_restore_validation_error('waca_order_items',v_identity,'WACA_PAYLOAD_KEY_MISSING');
    END IF;
    v_payload_key := v_row->'payload'->>'key';
    IF v_payload_key IS DISTINCT FROM v_row->>'item_key' THEN
      PERFORM public.erp_cloud_restore_validation_error('waca_order_items',v_identity,'WACA_PAYLOAD_KEY_MISMATCH');
    END IF;
  END LOOP;

  SELECT item INTO v_row
    FROM jsonb_array_elements(p_data->'waca_order_items') item
   WHERE NOT EXISTS (
     SELECT 1 FROM jsonb_array_elements(p_data->'waca_orders') order_row
      WHERE order_row->>'id'=item->>'order_id'
   )
   LIMIT 1;
  IF FOUND THEN
    PERFORM public.erp_cloud_restore_validation_error(
      'waca_order_items',coalesce(v_row->>'item_key',v_row->>'id','unknown'),'WACA_ORDER_ITEM_ORPHAN'
    );
  END IF;

  SELECT mapping INTO v_row
    FROM jsonb_array_elements(p_data->'waca_mappings') mapping
   WHERE NOT EXISTS (
     SELECT 1 FROM jsonb_array_elements(p_data->'product_variants') variant
      WHERE variant->>'id'=mapping->>'product_variant_id'
   )
   LIMIT 1;
  IF FOUND THEN
    PERFORM public.erp_cloud_restore_validation_error(
      'waca_mappings',coalesce(v_row->>'feature',v_row->>'id','unknown'),'WACA_MAPPING_VARIANT_INVALID'
    );
  END IF;

  SELECT link INTO v_row
    FROM jsonb_array_elements(p_data->'waca_master_links') link
   WHERE coalesce(btrim(link->>'product_variant_id'),'')<>''
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(p_data->'product_variants') variant
        WHERE variant->>'id'=link->>'product_variant_id'
     )
   LIMIT 1;
  IF FOUND THEN
    PERFORM public.erp_cloud_restore_validation_error(
      'waca_master_links',coalesce(v_row->>'child_code',v_row->>'id','unknown'),'WACA_MASTER_LINK_INVALID'
    );
  END IF;

  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_data->'waca_order_items') item
      JOIN jsonb_array_elements(p_data->'waca_mappings') mapping
        ON mapping->>'feature'=item->>'feature'
     WHERE item->>'product_variant_id' IS NOT NULL
       AND item->>'product_variant_id' IS DISTINCT FROM mapping->>'product_variant_id'
  ) THEN
    PERFORM public.erp_cloud_restore_validation_error('waca_mappings','feature','WACA_MAPPING_MISMATCH');
  END IF;

  IF v_mode='ORDER_DRIVEN_ACTIVE' AND EXISTS (
    WITH quantities AS (
      SELECT item->>'product_variant_id' variant_id,
        sum((item->>'quantity')::integer) quantity
      FROM jsonb_array_elements(p_data->'waca_order_items') item
      JOIN jsonb_array_elements(p_data->'waca_orders') order_row
        ON order_row->>'id'=item->>'order_id'
      WHERE item->>'product_variant_id' IS NOT NULL
        AND order_row->>'status' IN ('處理中','完成付款')
      GROUP BY item->>'product_variant_id'
    )
    SELECT 1 FROM jsonb_array_elements(p_data->'product_variants') variant
    LEFT JOIN quantities q ON q.variant_id=variant->>'id'
    WHERE (variant->>'waca_auto_quantity')::integer IS DISTINCT FROM coalesce(q.quantity,0)
  ) THEN
    PERFORM public.erp_cloud_restore_validation_error('product_variants','waca_auto_quantity','WACA_QUANTITY_RECONCILIATION_FAILED');
  END IF;
END;
$function$

public.erp_commit_waca_snapshot(jsonb,bi.definition:
CREATE OR REPLACE FUNCTION public.erp_commit_waca_snapshot(p_snapshot jsonb, p_expected_revision bigint, p_update_auto_quantity boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
begin
  if auth.uid() is null or not public.is_owner(auth.uid()) then raise exception using errcode='42501',message='WACA_OWNER_REQUIRED'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) then
    raise exception using errcode='55006',message='CLOUD_RESTORE_MAINTENANCE_LOCKED'; end if;
  perform pg_advisory_xact_lock(hashtextextended('erp-waca-ledger-import',0));
  perform public.erp_assert_waca_recognition_preserved(p_snapshot);
  -- A managed ledger may not start a legacy merge from an already inconsistent
  -- source/auto projection. Do not let unrelated metadata writes hide drift.
  if exists(select 1 from public.product_variants v where exists(select 1 from public.waca_order_items m
      where m.product_variant_id=v.id and m.payload->'recognition' is not null)
    and v.waca_auto_quantity is distinct from (select coalesce(sum(i.quantity) filter(where o.status in ('處理中','完成付款')),0)::integer
      from public.waca_order_items i join public.waca_orders o on o.id=i.order_id where i.product_variant_id=v.id)) then
    raise exception using errcode='23000',message='WACA_MANAGED_LEDGER_DRIFT';
  end if;
  if p_update_auto_quantity and exists(select 1 from public.waca_order_items where payload->'recognition' is not null) then
    raise exception using errcode='23000',message='WACA_MANAGED_LEGACY_QUANTITY_DISABLED';
  end if;
  return public.erp_commit_waca_snapshot_v044(public.erp_prune_waca_recognition_evidence(p_snapshot),p_expected_revision,p_update_auto_quantity);
end;
$function$

public.erp_reconcile_cloud_restore_attem.definition:
CREATE OR REPLACE FUNCTION public.erp_reconcile_cloud_restore_attempt(p_attempt_id uuid, p_trace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '10s'
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_attempt public.erp_cloud_restore_attempts%rowtype;
  v_out jsonb;
  v_failure jsonb;
  v_epoch bigint;
  v_fingerprint text;
  v_after timestamptz;
  v_locked boolean;
begin
  if v_actor is null then raise exception using errcode='42501',message='AUTHENTICATION_REQUIRED'; end if;
  if not public.is_owner(v_actor) then raise exception using errcode='42501',message='CLOUD_RESTORE_OWNER_REQUIRED'; end if;
  v_locked:=pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-attempt:'||p_attempt_id::text,0));
  select * into v_attempt from public.erp_cloud_restore_attempts where attempt_id=p_attempt_id
    and trace_id=p_trace_id and actor_key=encode(digest(v_actor::text,'sha256'),'hex');
  if not found then raise exception using errcode='22023',message='CLOUD_RESTORE_ATTEMPT_NOT_FOUND'; end if;
  v_after:=coalesce(v_attempt.execution_started_at,v_attempt.submitted_at)
    +(v_attempt.timeout_budget_ms+v_attempt.grace_ms)*interval '1 millisecond';
  v_out:=jsonb_build_object('status','pending','attemptId',p_attempt_id,'traceId',p_trace_id,
    'executionId',v_attempt.execution_id,'expectedEpoch',v_attempt.expected_epoch,
    'effectiveFingerprint',v_attempt.effective_fingerprint,'reconcileAfter',v_after);
  if not v_locked then return v_out||jsonb_build_object('reason','active-execution-lock'); end if;
  begin
    select * into strict v_attempt from public.erp_cloud_restore_attempts where attempt_id=p_attempt_id for update nowait;
  exception when lock_not_available then return v_out||jsonb_build_object('reason','active-execution-lock');
  end;
  if v_attempt.status='completed' then
    return v_out||jsonb_build_object('status','completed','resultEpoch',v_attempt.result_epoch,'restoreResult',v_attempt.canonical_result);
  end if;
  if v_attempt.status='not_committed' then
    v_failure:=public.erp_cloud_restore_failure_result(p_attempt_id);
    return coalesce(v_failure,v_out||jsonb_build_object('status','not_committed'));
  end if;
  if v_attempt.status in ('prepared','executing') and clock_timestamp()<v_after then
    return v_out||jsonb_build_object('reason','timeout-grace-active');
  end if;
  if v_attempt.status not in ('prepared','executing') then
    return v_out||jsonb_build_object('reason','nonterminal-state-unrecognized');
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) then
    return v_out||jsonb_build_object('reason','active-execution-lock');
  end if;
  select epoch,snapshot_fingerprint into strict v_epoch,v_fingerprint
    from public.erp_cloud_restore_epoch where singleton=true;
  if v_epoch is distinct from v_attempt.expected_epoch
     or v_fingerprint is not distinct from v_attempt.effective_fingerprint
     or exists(select 1 from public.erp_cloud_restore_requests where idempotency_key=p_attempt_id) then
    return v_out||jsonb_build_object('reason','epoch-or-request-ambiguous');
  end if;
  update public.erp_cloud_restore_attempts
     set status='not_committed',reconciled_at=clock_timestamp()
   where attempt_id=p_attempt_id;
  insert into public.erp_cloud_restore_failures(
    attempt_id,trace_id,execution_id,phase,category,code,timeout_classification,evidence
  ) values(
    p_attempt_id,p_trace_id,v_attempt.execution_id,'reconcile',case when pg_postmaster_start_time()>v_attempt.submitted_at and pg_postmaster_start_time()<=v_after then 'DATABASE_INTERRUPTED' else 'UNKNOWN' end,
    case when pg_postmaster_start_time()>v_attempt.submitted_at and pg_postmaster_start_time()<=v_after then 'CLOUD_RESTORE_FAILURE_DATABASE_INTERRUPTED' else 'CLOUD_RESTORE_FAILURE_UNKNOWN' end,'unobserved','reconciled-noncommit'
  );
  raise log 'CLOUD_RESTORE_ATTEMPT_PHASE attempt=% trace=% execution=% phase=RECONCILING event=closed-noncommit prior_status=%',
    p_attempt_id,p_trace_id,v_attempt.execution_id,v_attempt.status;
  return public.erp_cloud_restore_failure_result(p_attempt_id);
end;
$function$

public.erp_apply_japan_package_transacti.definition:
CREATE OR REPLACE FUNCTION public.erp_apply_japan_package_transaction(p_idempotency_key uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_transaction_type text;
  v_operation_type text;
  v_package_id uuid;
  v_package_operation jsonb;
  v_item_operations jsonb;
  v_expected_package_version integer;
  v_request_fingerprint text;
  v_existing public.erp_idempotency_keys%ROWTYPE;
  v_claimed boolean;
  v_operation jsonb;
  v_item_id uuid;
  v_purchase_item public.purchase_batch_items%ROWTYPE;
  v_current_package public.japan_packages%ROWTYPE;
  v_current_item public.japan_package_items%ROWTYPE;
  v_mutation_result jsonb;
  v_failure jsonb;
  v_package jsonb;
  v_items jsonb;
  v_result jsonb;
  v_all_checked boolean;
  v_any_checked boolean;
  v_target_status text;
  v_top_level_keys text[];
  v_change_keys text[];
  v_expected_keys text[];
  v_request_headers jsonb;
  v_request_host text;
BEGIN
  IF v_actor IS NULL OR NOT public.is_editor(v_actor) THEN
    RAISE EXCEPTION 'F3_JAPAN_PACKAGE_TRANSACTION_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'F3_IDEMPOTENCY_KEY_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_request) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'F3_REQUEST_MUST_BE_OBJECT' USING ERRCODE = '22023';
  END IF;
  SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[])
    INTO v_top_level_keys FROM jsonb_object_keys(p_request) key;
  IF v_top_level_keys IS DISTINCT FROM ARRAY[
    'expectedPackageVersion','itemOperations','packageId','packageOperation',
    'targetProjectRef','transactionType'
  ]::text[] THEN
    RAISE EXCEPTION 'F3_REQUEST_FIELDS_INVALID' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(p_request->>'targetProjectRef', '') !~ '^[a-z0-9]{20}$' THEN
    RAISE EXCEPTION 'F3_TARGET_PROJECT_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  BEGIN
    v_request_headers := NULLIF(pg_catalog.current_setting('request.headers', true), '')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'F3_TARGET_PROJECT_FORBIDDEN' USING ERRCODE = '42501';
  END;
  v_request_host := pg_catalog.lower(pg_catalog.split_part(COALESCE(v_request_headers->>'host', ''), ':', 1));
  IF v_request_host IS DISTINCT FROM (p_request->>'targetProjectRef') || '.supabase.co' THEN
    RAISE EXCEPTION 'F3_TARGET_PROJECT_FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  v_transaction_type := p_request->>'transactionType';
  IF v_transaction_type NOT IN ('create-package','attach-items','set-receiving') THEN
    RAISE EXCEPTION 'F3_TRANSACTION_TYPE_INVALID' USING ERRCODE = '22023';
  END IF;
  v_operation_type := CASE WHEN v_transaction_type = 'create-package' THEN 'create' ELSE 'edit' END;
  BEGIN
    v_package_id := (p_request->>'packageId')::uuid;
  EXCEPTION WHEN invalid_text_representation OR null_value_not_allowed THEN
    RAISE EXCEPTION 'F3_PACKAGE_UUID_REQUIRED' USING ERRCODE = '22023';
  END;
  v_package_operation := p_request->'packageOperation';
  v_item_operations := p_request->'itemOperations';
  IF jsonb_typeof(v_item_operations) IS DISTINCT FROM 'array' OR jsonb_array_length(v_item_operations) > 1000 THEN
    RAISE EXCEPTION 'F3_ITEM_OPERATIONS_INVALID' USING ERRCODE = '22023';
  END IF;

  IF v_transaction_type = 'create-package' THEN
    IF jsonb_typeof(v_package_operation) IS DISTINCT FROM 'object'
       OR v_package_operation->>'kind' IS DISTINCT FROM 'create'
       OR v_package_operation->>'id' IS DISTINCT FROM v_package_id::text
       OR jsonb_array_length(v_item_operations) <> 0
       OR jsonb_typeof(p_request->'expectedPackageVersion') IS DISTINCT FROM 'null' THEN
      RAISE EXCEPTION 'F3_CREATE_CONTRACT_INVALID' USING ERRCODE = '22023';
    END IF;
    IF v_package_operation->'values'->>'status' NOT IN ('registered','arrived','confirmed','problem') THEN
      RAISE EXCEPTION 'F3_PACKAGE_STATUS_INVALID' USING ERRCODE = '22023';
    END IF;
  ELSE
    IF jsonb_typeof(v_package_operation) IS DISTINCT FROM 'null'
       OR jsonb_typeof(p_request->'expectedPackageVersion') IS DISTINCT FROM 'number' THEN
      RAISE EXCEPTION 'F3_EXISTING_PACKAGE_CONTRACT_INVALID' USING ERRCODE = '22023';
    END IF;
    v_expected_package_version := (p_request->>'expectedPackageVersion')::integer;
    IF v_expected_package_version < 1 THEN
      RAISE EXCEPTION 'F3_PACKAGE_VERSION_INVALID' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_transaction_type IN ('attach-items','set-receiving') AND jsonb_array_length(v_item_operations) = 0 THEN
    RAISE EXCEPTION 'F3_ITEM_OPERATION_REQUIRED' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(p_request::text);
  BEGIN
    INSERT INTO public.erp_idempotency_keys (
      actor_id, idempotency_key, operation_type, request_fingerprint,
      request_payload, status
    ) VALUES (
      v_actor, p_idempotency_key, v_operation_type, v_request_fingerprint,
      p_request, 'processing'
    )
    ON CONFLICT (actor_id, idempotency_key) DO NOTHING
    RETURNING true INTO v_claimed;

    IF COALESCE(v_claimed, false) IS FALSE THEN
      SELECT * INTO v_existing FROM public.erp_idempotency_keys
       WHERE actor_id = v_actor AND idempotency_key = p_idempotency_key
       FOR UPDATE;
      IF v_existing.operation_type IS DISTINCT FROM v_operation_type
         OR v_existing.request_fingerprint IS DISTINCT FROM v_request_fingerprint
         OR v_existing.request_payload IS DISTINCT FROM p_request THEN
        RETURN jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_KEY_PAYLOAD_MISMATCH', 'recordId', v_package_id);
      END IF;
      IF v_existing.status = 'completed' AND v_existing.canonical_result IS NOT NULL THEN
        RETURN jsonb_set(v_existing.canonical_result, '{replayed}', 'true'::jsonb, true);
      END IF;
      RAISE EXCEPTION 'F3_IDEMPOTENCY_INCOMPLETE' USING ERRCODE = '55000';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('japan_packages:' || v_package_id::text, 0));

    IF v_transaction_type = 'create-package' THEN
      v_mutation_result := public.erp_apply_field_mutations('japan_packages', jsonb_build_array(v_package_operation));
      IF v_mutation_result->>'ok' IS DISTINCT FROM 'true' THEN
        v_failure := v_mutation_result;
        RAISE EXCEPTION 'F3_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
      END IF;
    ELSE
      SELECT * INTO v_current_package FROM public.japan_packages
       WHERE id = v_package_id AND deleted_at IS NULL FOR UPDATE;
      IF NOT FOUND THEN
        v_failure := jsonb_build_object('ok', false, 'code', 'RECORD_DELETED_OR_MISSING', 'entity', 'japan_packages', 'recordId', v_package_id);
        RAISE EXCEPTION 'F3_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
      END IF;
      IF v_current_package.version IS DISTINCT FROM v_expected_package_version THEN
        v_failure := jsonb_build_object('ok', false, 'code', 'FIELD_CONFLICT', 'entity', 'japan_packages', 'recordId', v_package_id);
        RAISE EXCEPTION 'F3_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
      END IF;

      FOR v_operation IN SELECT value FROM jsonb_array_elements(v_item_operations) ORDER BY value->>'id'
      LOOP
        BEGIN
          v_item_id := (v_operation->>'id')::uuid;
        EXCEPTION WHEN invalid_text_representation OR null_value_not_allowed THEN
          RAISE EXCEPTION 'F3_ITEM_UUID_REQUIRED' USING ERRCODE = '22023';
        END;
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('japan_package_items:' || v_item_id::text, 0));

        IF v_transaction_type = 'attach-items' THEN
          IF v_operation->>'kind' IS DISTINCT FROM 'create'
             OR v_operation->'values'->>'japan_package_id' IS DISTINCT FROM v_package_id::text
             OR COALESCE((v_operation->'values'->>'quantity')::integer, 0) <= 0
             OR COALESCE(v_operation->'values'->>'checked', 'false')::boolean THEN
            RAISE EXCEPTION 'F3_ATTACH_ITEM_CONTRACT_INVALID' USING ERRCODE = '22023';
          END IF;
          IF v_operation->'values'->>'purchase_batch_item_id' IS NOT NULL THEN
            SELECT * INTO v_purchase_item FROM public.purchase_batch_items
             WHERE id = (v_operation->'values'->>'purchase_batch_item_id')::uuid
               AND deleted_at IS NULL FOR SHARE;
            IF NOT FOUND
               OR v_purchase_item.purchase_batch_id::text IS DISTINCT FROM v_operation->'values'->>'purchase_batch_id'
               OR v_purchase_item.product_variant_id::text IS DISTINCT FROM v_operation->'values'->>'product_variant_id'
               OR (v_operation->'values'->>'quantity')::integer > v_purchase_item.quantity THEN
              RAISE EXCEPTION 'F3_PURCHASE_ITEM_RELATION_INVALID' USING ERRCODE = '23503';
            END IF;
            IF EXISTS (
              SELECT 1 FROM public.japan_package_items existing
               WHERE existing.purchase_batch_item_id = v_purchase_item.id AND existing.deleted_at IS NULL
            ) THEN
              v_failure := jsonb_build_object('ok', false, 'code', 'DUPLICATE_RELATION', 'entity', 'japan_package_items', 'recordId', v_item_id);
              RAISE EXCEPTION 'F3_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
            END IF;
          END IF;
        ELSE
          IF v_operation->>'kind' IS DISTINCT FROM 'patch' THEN
            RAISE EXCEPTION 'F3_RECEIVING_PATCH_REQUIRED' USING ERRCODE = '22023';
          END IF;
          SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[]) INTO v_change_keys
            FROM jsonb_object_keys(v_operation->'changes') key;
          SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[]) INTO v_expected_keys
            FROM jsonb_object_keys(v_operation->'expected') key;
          IF v_change_keys IS DISTINCT FROM v_expected_keys
             OR NOT v_change_keys <@ ARRAY['checked','checked_at']::text[]
             OR NOT ('checked' = ANY(v_change_keys))
             OR jsonb_typeof(v_operation->'observedVersion') IS DISTINCT FROM 'number' THEN
            RAISE EXCEPTION 'F3_RECEIVING_FIELDS_INVALID' USING ERRCODE = '22023';
          END IF;
          SELECT * INTO v_current_item FROM public.japan_package_items
           WHERE id = v_item_id AND japan_package_id = v_package_id AND deleted_at IS NULL FOR UPDATE;
          IF NOT FOUND THEN
            v_failure := jsonb_build_object('ok', false, 'code', 'RECORD_DELETED_OR_MISSING', 'entity', 'japan_package_items', 'recordId', v_item_id);
            RAISE EXCEPTION 'F3_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
          END IF;
          IF v_current_item.version IS DISTINCT FROM (v_operation->>'observedVersion')::integer THEN
            v_failure := jsonb_build_object('ok', false, 'code', 'FIELD_CONFLICT', 'entity', 'japan_package_items', 'recordId', v_item_id);
            RAISE EXCEPTION 'F3_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
          END IF;
          IF (v_operation->'changes'->>'checked')::boolean AND jsonb_typeof(v_operation->'changes'->'checked_at') IS DISTINCT FROM 'string' THEN
            RAISE EXCEPTION 'F3_CHECKED_AT_REQUIRED' USING ERRCODE = '22023';
          END IF;
          IF NOT (v_operation->'changes'->>'checked')::boolean AND v_operation->'changes'->'checked_at' <> 'null'::jsonb THEN
            RAISE EXCEPTION 'F3_UNCHECKED_AT_MUST_BE_NULL' USING ERRCODE = '22023';
          END IF;
        END IF;
      END LOOP;

      v_mutation_result := public.erp_apply_field_mutations('japan_package_items', v_item_operations);
      IF v_mutation_result->>'ok' IS DISTINCT FROM 'true' THEN
        v_failure := v_mutation_result;
        RAISE EXCEPTION 'F3_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
      END IF;

      SELECT bool_and(item.checked) AND count(*) > 0,
             bool_or(item.checked)
        INTO v_all_checked, v_any_checked
        FROM public.japan_package_items item
       WHERE item.japan_package_id = v_package_id AND item.deleted_at IS NULL;
      v_target_status := v_current_package.status;
      IF v_current_package.status <> 'problem' THEN
        IF COALESCE(v_all_checked, false) THEN
          v_target_status := 'confirmed';
        ELSIF COALESCE(v_any_checked, false)
              OR v_current_package.status IN ('arrived', 'confirmed') THEN
          v_target_status := 'arrived';
        END IF;
      END IF;
      IF v_transaction_type = 'attach-items'
         OR v_target_status IS DISTINCT FROM v_current_package.status THEN
        UPDATE public.japan_packages
           SET status = v_target_status,
               arrived_at = CASE WHEN v_target_status IN ('arrived','confirmed') THEN COALESCE(arrived_at, CURRENT_DATE) ELSE arrived_at END,
               version = version + 1,
               updated_at = clock_timestamp(),
               updated_by = v_actor,
               sync_status = 'synced'
         WHERE id = v_package_id;
      END IF;
    END IF;

    SELECT to_jsonb(package_row) INTO v_package FROM public.japan_packages package_row
     WHERE package_row.id = v_package_id AND package_row.deleted_at IS NULL;
    SELECT COALESCE(jsonb_agg(to_jsonb(item) ORDER BY item.id), '[]'::jsonb) INTO v_items
      FROM public.japan_package_items item
     WHERE item.japan_package_id = v_package_id AND item.deleted_at IS NULL;
    IF v_package IS NULL THEN
      RAISE EXCEPTION 'F3_CANONICAL_PACKAGE_MISSING' USING ERRCODE = '55000';
    END IF;

    v_result := jsonb_build_object(
      'ok', true,
      'transactionType', v_transaction_type,
      'idempotencyKey', p_idempotency_key,
      'replayed', false,
      'package', v_package,
      'items', v_items
    );
    UPDATE public.erp_idempotency_keys
       SET status = 'completed', canonical_result = v_result, completed_at = clock_timestamp()
     WHERE actor_id = v_actor AND idempotency_key = p_idempotency_key;
    RETURN v_result;
  EXCEPTION
    WHEN SQLSTATE 'P0001' THEN
      IF SQLERRM = 'F3_STRUCTURED_ROLLBACK' AND v_failure IS NOT NULL THEN RETURN v_failure; END IF;
      RAISE;
    WHEN check_violation OR foreign_key_violation OR not_null_violation OR unique_violation THEN
      RETURN jsonb_build_object('ok', false, 'code', 'TRANSACTION_CONSTRAINT_FAILED', 'recordId', v_package_id);
  END;
END;
$function$

public.erp_apply_private_order_transacti.definition:
CREATE OR REPLACE FUNCTION public.erp_apply_private_order_transaction(p_idempotency_key uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor uuid := auth.uid(); order_id uuid; action text; claimed boolean;
  old_request public.erp_idempotency_keys%ROWTYPE;
  operation jsonb; result jsonb; failure jsonb; parent jsonb; children jsonb;
  current_version integer; current_items jsonb; actual_parent uuid;
BEGIN
  IF actor IS NULL OR NOT public.is_editor(actor) THEN
    RAISE EXCEPTION 'PRIVATE_ORDER_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL OR jsonb_typeof(p_request) IS DISTINCT FROM 'object'
    OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_request) k) IS DISTINCT FROM
      ARRAY['action','expectedItems','expectedParentVersion','family','itemOperations','orderId','orderOperations']::text[]
    OR p_request->>'family' IS DISTINCT FROM 'private-order' THEN
    RAISE EXCEPTION 'PRIVATE_ORDER_INVALID_REQUEST' USING ERRCODE = '22023';
  END IF;
  order_id := (p_request->>'orderId')::uuid; action := p_request->>'action';
  IF order_id IS NULL OR action IS NULL OR action NOT IN ('create','edit','delete')
    OR jsonb_typeof(p_request->'orderOperations') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_request->'itemOperations') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_request->'expectedItems') IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_request->'orderOperations') > 1
    OR jsonb_array_length(p_request->'itemOperations') > 1000 THEN
    RAISE EXCEPTION 'PRIVATE_ORDER_INVALID_OPERATIONS' USING ERRCODE = '22023';
  END IF;
  IF (action IN ('create','delete') AND jsonb_array_length(p_request->'orderOperations') <> 1)
    OR (action = 'create' AND jsonb_array_length(p_request->'itemOperations') = 0)
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_request->'orderOperations') op WHERE
      op->>'id' IS DISTINCT FROM order_id::text OR op->>'kind' IS DISTINCT FROM
        CASE action WHEN 'create' THEN 'create' WHEN 'delete' THEN 'delete' ELSE 'patch' END) THEN
    RAISE EXCEPTION 'PRIVATE_ORDER_INVALID_PARENT' USING ERRCODE = '22023';
  END IF;
  FOR operation IN SELECT value FROM jsonb_array_elements(p_request->'itemOperations') LOOP
    IF operation->>'kind' IS NULL OR operation->>'kind' NOT IN ('create','patch','delete')
      OR (operation->>'kind' = 'create' AND operation->'values'->>'private_order_id' IS DISTINCT FROM order_id::text)
      OR (operation->'changes' ? 'private_order_id' AND operation->'changes'->>'private_order_id' IS DISTINCT FROM order_id::text)
      OR (action = 'delete' AND operation->>'kind' <> 'delete') THEN
      RAISE EXCEPTION 'PRIVATE_ORDER_CHILD_SCOPE_INVALID' USING ERRCODE = '22023';
    END IF;
    IF coalesce(operation->'values',operation->'changes','{}') ? 'quantity' AND
      ((coalesce(operation->'values',operation->'changes')->>'quantity')::numeric <= 0
       OR trunc((coalesce(operation->'values',operation->'changes')->>'quantity')::numeric)
          IS DISTINCT FROM (coalesce(operation->'values',operation->'changes')->>'quantity')::numeric) THEN
      RAISE EXCEPTION 'PRIVATE_ORDER_QUANTITY_INVALID' USING ERRCODE='22023';
    END IF;
  END LOOP;

  BEGIN
    INSERT INTO public.erp_idempotency_keys(actor_id,idempotency_key,operation_type,request_fingerprint,request_payload,status)
      VALUES(actor,p_idempotency_key,CASE WHEN action='create' THEN 'create' ELSE 'edit' END,md5(p_request::text),p_request,'processing')
      ON CONFLICT(actor_id,idempotency_key) DO NOTHING RETURNING true INTO claimed;
    IF NOT coalesce(claimed,false) THEN
      SELECT * INTO old_request FROM public.erp_idempotency_keys
        WHERE actor_id=actor AND idempotency_key=p_idempotency_key FOR UPDATE;
      IF old_request.request_payload IS DISTINCT FROM p_request THEN
        RETURN jsonb_build_object('ok',false,'code','IDEMPOTENCY_KEY_PAYLOAD_MISMATCH');
      END IF;
      IF old_request.status <> 'completed' THEN RAISE EXCEPTION 'PRIVATE_ORDER_INCOMPLETE'; END IF;
      RETURN jsonb_set(old_request.canonical_result,'{replayed}','true',true);
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('private_orders:'||order_id::text,0));
    SELECT version INTO current_version FROM public.private_orders WHERE id=order_id AND deleted_at IS NULL FOR UPDATE;
    IF action='create' THEN
      IF FOUND OR p_request->'expectedParentVersion' IS DISTINCT FROM 'null'::jsonb THEN
        RAISE EXCEPTION 'PRIVATE_ORDER_DUPLICATE_CREATE';
      END IF;
    ELSIF current_version IS NULL OR current_version IS DISTINCT FROM (p_request->>'expectedParentVersion')::integer THEN
      failure := jsonb_build_object('ok',false,'code','FIELD_CONFLICT','entity','private_orders','recordId',order_id);
      RAISE EXCEPTION 'PRIVATE_ORDER_ROLLBACK' USING ERRCODE='P0001';
    END IF;
    PERFORM 1 FROM public.private_order_items WHERE private_order_id=order_id AND deleted_at IS NULL ORDER BY id FOR UPDATE;
    SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version) ORDER BY id),'[]') INTO current_items
      FROM public.private_order_items WHERE private_order_id=order_id AND deleted_at IS NULL;
    IF current_items IS DISTINCT FROM p_request->'expectedItems' THEN
      failure := jsonb_build_object('ok',false,'code','FIELD_CONFLICT','entity','private_order_items','recordId',order_id);
      RAISE EXCEPTION 'PRIVATE_ORDER_ROLLBACK' USING ERRCODE='P0001';
    END IF;
    FOR operation IN SELECT value FROM jsonb_array_elements(p_request->'itemOperations') WHERE value->>'kind'<>'create' LOOP
      SELECT private_order_id INTO actual_parent FROM public.private_order_items
        WHERE id=(operation->>'id')::uuid AND deleted_at IS NULL FOR UPDATE;
      IF actual_parent IS DISTINCT FROM order_id THEN RAISE EXCEPTION 'PRIVATE_ORDER_CHILD_SCOPE_INVALID'; END IF;
    END LOOP;
    IF action<>'delete' AND jsonb_array_length(p_request->'orderOperations')>0 THEN
      result := public.erp_apply_field_mutations('private_orders',p_request->'orderOperations');
      IF result->>'ok' IS DISTINCT FROM 'true' THEN failure:=result; RAISE EXCEPTION 'PRIVATE_ORDER_ROLLBACK'; END IF;
    END IF;
    IF jsonb_array_length(p_request->'itemOperations')>0 THEN
      result := public.erp_apply_field_mutations('private_order_items',p_request->'itemOperations');
      IF result->>'ok' IS DISTINCT FROM 'true' THEN failure:=result; RAISE EXCEPTION 'PRIVATE_ORDER_ROLLBACK'; END IF;
    END IF;
    IF action='delete' THEN
      IF EXISTS(SELECT 1 FROM public.private_order_items WHERE private_order_id=order_id AND deleted_at IS NULL) THEN
        RAISE EXCEPTION 'PRIVATE_ORDER_ACTIVE_CHILDREN';
      END IF;
      result := public.erp_apply_field_mutations('private_orders',p_request->'orderOperations');
      IF result->>'ok' IS DISTINCT FROM 'true' THEN failure:=result; RAISE EXCEPTION 'PRIVATE_ORDER_ROLLBACK'; END IF;
    ELSE
      IF EXISTS(SELECT 1 FROM public.private_orders WHERE id=order_id AND deleted_at IS NULL AND btrim(customer_name)='') THEN
        RAISE EXCEPTION 'PRIVATE_ORDER_CUSTOMER_REQUIRED';
      END IF;
      IF EXISTS(SELECT 1 FROM public.private_order_items i
        JOIN public.private_orders o ON o.id=i.private_order_id
        LEFT JOIN public.product_variants v ON v.id=i.product_variant_id
        WHERE i.private_order_id=order_id AND i.deleted_at IS NULL AND
          (v.id IS NULL OR v.deleted_at IS NOT NULL OR v.product_group_id IS DISTINCT FROM o.product_group_id
           OR i.quantity<=0 OR i.amount<0)) THEN RAISE EXCEPTION 'PRIVATE_ORDER_RELATIONSHIP_INVALID'; END IF;
    END IF;
    SELECT to_jsonb(o) INTO parent FROM public.private_orders o WHERE id=order_id AND deleted_at IS NULL;
    SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY id),'[]') INTO children FROM public.private_order_items i
      WHERE private_order_id=order_id AND deleted_at IS NULL;
    result:=jsonb_build_object('ok',true,'replayed',false,'idempotencyKey',p_idempotency_key,'order',parent,'items',children);
    UPDATE public.erp_idempotency_keys SET status='completed',canonical_result=result,completed_at=clock_timestamp()
      WHERE actor_id=actor AND idempotency_key=p_idempotency_key;
    RETURN result;
  EXCEPTION WHEN OTHERS THEN
    IF failure IS NOT NULL THEN RETURN failure; END IF;
    -- The exception block rolls back *all* business rows and the replay claim.
    RETURN jsonb_build_object('ok',false,'code','TRANSACTION_REJECTED','sqlstate',SQLSTATE);
  END;
END; $function$

public.erp_apply_purchase_batch_transact.definition:
CREATE OR REPLACE FUNCTION public.erp_apply_purchase_batch_transaction(p_idempotency_key uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_operation_type text;
  v_batch_id uuid;
  v_batch_operations jsonb;
  v_item_operations jsonb;
  v_operation jsonb;
  v_existing public.erp_idempotency_keys%ROWTYPE;
  v_claimed boolean;
  v_request_fingerprint text;
  v_mutation_result jsonb;
  v_failure jsonb;
  v_batch jsonb;
  v_items jsonb;
  v_result jsonb;
  v_top_level_keys text[];
  v_item_batch_id uuid;
BEGIN
  IF v_actor IS NULL OR NOT public.is_editor(v_actor) THEN
    RAISE EXCEPTION 'P0_4_PURCHASE_TRANSACTION_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'P0_4_IDEMPOTENCY_KEY_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_request) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'P0_4_REQUEST_MUST_BE_OBJECT' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[])
    INTO v_top_level_keys FROM jsonb_object_keys(p_request) key;
  IF v_top_level_keys IS DISTINCT FROM ARRAY[
    'batchId','batchOperations','itemOperations','operationType'
  ]::text[] THEN
    RAISE EXCEPTION 'P0_4_REQUEST_FIELDS_INVALID' USING ERRCODE = '22023';
  END IF;

  v_operation_type := p_request->>'operationType';
  IF v_operation_type NOT IN ('create', 'edit') THEN
    RAISE EXCEPTION 'P0_4_OPERATION_TYPE_INVALID' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_batch_id := (p_request->>'batchId')::uuid;
  EXCEPTION WHEN invalid_text_representation OR null_value_not_allowed THEN
    RAISE EXCEPTION 'P0_4_BATCH_UUID_REQUIRED' USING ERRCODE = '22023';
  END;
  IF v_batch_id IS NULL THEN
    RAISE EXCEPTION 'P0_4_BATCH_UUID_REQUIRED' USING ERRCODE = '22023';
  END IF;
  v_batch_operations := p_request->'batchOperations';
  v_item_operations := p_request->'itemOperations';
  IF jsonb_typeof(v_batch_operations) IS DISTINCT FROM 'array'
     OR jsonb_typeof(v_item_operations) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'P0_4_OPERATIONS_MUST_BE_ARRAYS' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(v_batch_operations) > 1 THEN
    RAISE EXCEPTION 'P0_4_SINGLE_BATCH_OPERATION_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_batch_operations) operation
     WHERE operation->>'id' IS DISTINCT FROM v_batch_id::text
        OR (v_operation_type = 'create' AND operation->>'kind' IS DISTINCT FROM 'create')
        OR (v_operation_type = 'edit' AND operation->>'kind' IS DISTINCT FROM 'patch')
  ) THEN
    RAISE EXCEPTION 'P0_4_BATCH_OPERATION_INVALID' USING ERRCODE = '22023';
  END IF;
  IF v_operation_type = 'create' AND jsonb_array_length(v_batch_operations) <> 1 THEN
    RAISE EXCEPTION 'P0_4_CREATE_BATCH_OPERATION_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF v_operation_type = 'create' AND jsonb_array_length(v_item_operations) = 0 THEN
    RAISE EXCEPTION 'P0_4_CREATE_ITEM_OPERATION_REQUIRED' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(v_item_operations) > 1000 THEN
    RAISE EXCEPTION 'P0_4_ITEM_OPERATION_LIMIT_EXCEEDED' USING ERRCODE = '54000';
  END IF;

  -- Child operations are structurally bound to exactly one Batch. Existing-row
  -- ownership is checked below only after the same advisory/row locks used by CAS.
  FOR v_operation IN SELECT value FROM jsonb_array_elements(v_item_operations)
  LOOP
    IF v_operation->>'kind' = 'create' THEN
      IF v_operation->'values'->>'purchase_batch_id' IS DISTINCT FROM v_batch_id::text THEN
        RAISE EXCEPTION 'P0_4_ITEM_BATCH_SCOPE_INVALID' USING ERRCODE = '22023';
      END IF;
    ELSIF v_operation->>'kind' IN ('patch', 'delete', 'reorder') THEN
      IF v_operation->>'kind' IN ('patch', 'reorder')
         AND v_operation->'changes' ? 'purchase_batch_id'
         AND v_operation->'changes'->>'purchase_batch_id' IS DISTINCT FROM v_batch_id::text THEN
        RAISE EXCEPTION 'P0_4_ITEM_BATCH_REPARENT_FORBIDDEN' USING ERRCODE = '22023';
      END IF;
    ELSE
      RAISE EXCEPTION 'P0_4_ITEM_OPERATION_INVALID' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  v_request_fingerprint := md5(p_request::text);

  -- This block is a PostgreSQL subtransaction. Any structured conflict or constraint
  -- failure rolls back the idempotency claim and every Batch/Item mutation together.
  BEGIN
    INSERT INTO public.erp_idempotency_keys (
      actor_id, idempotency_key, operation_type, request_fingerprint,
      request_payload, status
    ) VALUES (
      v_actor, p_idempotency_key, v_operation_type, v_request_fingerprint,
      p_request, 'processing'
    )
    ON CONFLICT (actor_id, idempotency_key) DO NOTHING
    RETURNING true INTO v_claimed;

    IF COALESCE(v_claimed, false) IS FALSE THEN
      SELECT * INTO v_existing
        FROM public.erp_idempotency_keys
       WHERE actor_id = v_actor AND idempotency_key = p_idempotency_key
       FOR UPDATE;
      IF v_existing.operation_type IS DISTINCT FROM v_operation_type
         OR v_existing.request_fingerprint IS DISTINCT FROM v_request_fingerprint
         OR v_existing.request_payload IS DISTINCT FROM p_request THEN
        RETURN jsonb_build_object(
          'ok', false,
          'code', 'IDEMPOTENCY_KEY_PAYLOAD_MISMATCH',
          'recordId', v_batch_id
        );
      END IF;
      IF v_existing.status = 'completed' AND v_existing.canonical_result IS NOT NULL THEN
        RETURN jsonb_set(v_existing.canonical_result, '{replayed}', 'true'::jsonb, true);
      END IF;
      RAISE EXCEPTION 'P0_4_IDEMPOTENCY_INCOMPLETE' USING ERRCODE = '55000';
    END IF;

    -- Freeze the parent and every existing child in deterministic order before the
    -- first mutation. This closes the gap where another transaction could delete or
    -- re-parent an Item after the structural check but before the P0-3 CAS call.
    IF v_operation_type = 'edit' THEN
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('purchase_batches:' || v_batch_id::text, 0)
      );
      PERFORM 1
        FROM public.purchase_batches batch
       WHERE batch.id = v_batch_id
         AND batch.deleted_at IS NULL
       FOR UPDATE;
      IF NOT FOUND THEN
        v_failure := jsonb_build_object(
          'ok', false, 'code', 'RECORD_DELETED_OR_MISSING',
          'entity', 'purchase_batches', 'recordId', v_batch_id
        );
        RAISE EXCEPTION 'P0_4_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
      END IF;
    END IF;

    FOR v_operation IN
      SELECT value
        FROM jsonb_array_elements(v_item_operations)
       WHERE value->>'kind' IN ('patch', 'delete', 'reorder')
       ORDER BY value->>'id'
    LOOP
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'purchase_batch_items:' || (v_operation->>'id'), 0
        )
      );
      v_item_batch_id := NULL;
      SELECT item.purchase_batch_id
        INTO v_item_batch_id
        FROM public.purchase_batch_items item
       WHERE item.id = (v_operation->>'id')::uuid
         AND item.deleted_at IS NULL
       FOR UPDATE;
      IF NOT FOUND OR v_item_batch_id IS DISTINCT FROM v_batch_id THEN
        v_failure := jsonb_build_object(
          'ok', false, 'code', 'RECORD_DELETED_OR_MISSING',
          'entity', 'purchase_batch_items', 'recordId', v_operation->>'id'
        );
        RAISE EXCEPTION 'P0_4_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
      END IF;
    END LOOP;

    -- The existing P0-3 function remains authoritative for field whitelists, locks,
    -- field-aware expected-value checks, stale delete, and version increments.
    IF jsonb_array_length(v_batch_operations) > 0 THEN
      v_mutation_result := public.erp_apply_field_mutations('purchase_batches', v_batch_operations);
      IF v_mutation_result->>'ok' IS DISTINCT FROM 'true' THEN
        v_failure := v_mutation_result;
        RAISE EXCEPTION 'P0_4_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
      END IF;
    END IF;

    IF jsonb_array_length(v_item_operations) > 0 THEN
      v_mutation_result := public.erp_apply_field_mutations('purchase_batch_items', v_item_operations);
      IF v_mutation_result->>'ok' IS DISTINCT FROM 'true' THEN
        v_failure := v_mutation_result;
        RAISE EXCEPTION 'P0_4_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
      END IF;
    END IF;

    SELECT to_jsonb(batch) INTO v_batch
      FROM public.purchase_batches batch
     WHERE batch.id = v_batch_id AND batch.deleted_at IS NULL;
    IF v_batch IS NULL THEN
      v_failure := jsonb_build_object(
        'ok', false, 'code', 'RECORD_DELETED_OR_MISSING',
        'entity', 'purchase_batches', 'recordId', v_batch_id
      );
      RAISE EXCEPTION 'P0_4_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(item) ORDER BY item.id), '[]'::jsonb)
      INTO v_items
      FROM public.purchase_batch_items item
     WHERE item.purchase_batch_id = v_batch_id AND item.deleted_at IS NULL;

    v_result := jsonb_build_object(
      'ok', true,
      'operationType', v_operation_type,
      'idempotencyKey', p_idempotency_key,
      'replayed', false,
      'batch', v_batch,
      'items', v_items
    );
    UPDATE public.erp_idempotency_keys
       SET status = 'completed', canonical_result = v_result, completed_at = clock_timestamp()
     WHERE actor_id = v_actor AND idempotency_key = p_idempotency_key;
    RETURN v_result;
  EXCEPTION
    WHEN SQLSTATE 'P0001' THEN
      IF SQLERRM = 'P0_4_STRUCTURED_ROLLBACK' AND v_failure IS NOT NULL THEN
        RETURN v_failure;
      END IF;
      RAISE;
    WHEN check_violation OR foreign_key_violation OR not_null_violation OR unique_violation THEN
      RETURN jsonb_build_object(
        'ok', false,
        'code', 'TRANSACTION_CONSTRAINT_FAILED',
        'entity', 'purchase_batch_items',
        'recordId', v_batch_id
      );
  END;
END;
$function$

public.erp_upload_restore_chunk(uuid,tex.definition:
CREATE OR REPLACE FUNCTION public.erp_upload_restore_chunk(p_request_id uuid, p_resource text, p_ordinal integer, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE r public.erp_restore_upload_requests%rowtype;h text;n integer;expected integer;previous text;
BEGIN
 r:=public.erp_restore_upload_owner(p_request_id);
 IF r.completed_result IS NOT NULL THEN RAISE EXCEPTION USING errcode='55000',message='CLOUD_RESTORE_UPLOAD_CLOSED'; END IF;
 IF NOT (r.manifest->'counts' ? p_resource) OR p_resource<>ALL(ARRAY[
  'inventory_items','product_groups','product_categories','product_variants','bundle_components',
  'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
  'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
  'waca_orders','waca_order_items','waca_mappings','waca_master_links','waca_import_batches','waca_cutover_audit','waca_state'])
  OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR p_ordinal IS NULL OR p_ordinal<0
  OR pg_column_size(p_rows)>2097152 THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_CHUNK_INVALID'; END IF;
 n:=jsonb_array_length(p_rows);expected:=(r.manifest->'counts'->>p_resource)::integer;
 IF n<>least(512,expected-p_ordinal*512) OR n NOT BETWEEN 1 AND 512 THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_CHUNK_COUNT_MISMATCH'; END IF;
 h:=encode(extensions.digest(convert_to(p_rows::text,'UTF8'),'sha256'),'hex');
 INSERT INTO public.erp_restore_upload_chunks(request_id,resource,ordinal,rows,payload_hash)
  VALUES(p_request_id,p_resource,p_ordinal,p_rows,h) ON CONFLICT DO NOTHING;
 SELECT payload_hash INTO STRICT previous FROM public.erp_restore_upload_chunks
  WHERE request_id=p_request_id AND resource=p_resource AND ordinal=p_ordinal;
 IF h<>previous THEN RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_UPLOAD_CHUNK_IDENTITY_MISMATCH'; END IF;
 RETURN jsonb_build_object('resource',p_resource,'ordinal',p_ordinal,'rows',n,'hash',h);
END;
$function$

public.erp_verify_committed_cloud_restor.definition:
CREATE OR REPLACE FUNCTION public.erp_verify_committed_cloud_restore(p_attempt_id uuid, p_trace_id uuid, p_execution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '15s'
AS $function$
DECLARE
 a public.erp_cloud_restore_attempts%rowtype;
 r public.erp_cloud_restore_requests%rowtype;
 actor uuid:=auth.uid(); epoch bigint; generation bigint;
 gx text; rx text; ex text; current_fp text;
 names constant text[]:=ARRAY['inventory_items','product_groups','product_categories','product_variants','bundle_components',
 'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
 'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
 'waca_orders','waca_order_items','waca_mappings','waca_master_links','waca_import_batches','waca_cutover_audit','waca_state'];
 name text; profile jsonb; counts jsonb:='{}'; total bigint:=0; duplicates bigint:=0;
 missing bigint:=0; orphans bigint:=0; relationships text; matched boolean:=true; coverage boolean:=true;
 started timestamptz:=clock_timestamp();
BEGIN
 IF actor IS NULL OR NOT public.is_owner(actor) THEN
  RAISE EXCEPTION USING errcode='42501',message='RESTORE_READBACK_PERMISSION_ERROR';
 END IF;
 SELECT * INTO a FROM public.erp_cloud_restore_attempts WHERE attempt_id=p_attempt_id AND trace_id=p_trace_id
  AND execution_id=p_execution_id AND actor_key=encode(extensions.digest(actor::text,'sha256'),'hex');
 IF NOT FOUND OR a.status<>'completed' THEN
  RAISE EXCEPTION USING errcode='22023',message='RESTORE_COMMITTED_RECEIPT_REQUIRED';
 END IF;
 SELECT * INTO r FROM public.erp_cloud_restore_requests WHERE idempotency_key=p_attempt_id AND actor_id=actor;
 IF NOT FOUND OR r.status<>'completed' OR r.canonical_result->>'ok'<>'true'
  OR r.canonical_result->>'restoreEpoch' IS DISTINCT FROM a.result_epoch::text
  OR r.canonical_result->>'snapshotFingerprint' IS DISTINCT FROM a.effective_fingerprint
  OR a.canonical_result->>'snapshotFingerprint' IS DISTINCT FROM a.effective_fingerprint THEN
  RAISE EXCEPTION USING errcode='22023',message='RESTORE_COMMITTED_RECEIPT_MISMATCH';
 END IF;
 SELECT e.epoch,e.snapshot_fingerprint,e.xmin::text INTO STRICT epoch,current_fp,ex FROM public.erp_cloud_restore_epoch e WHERE singleton;
 SELECT g.generation,g.xmin::text INTO STRICT generation,gx FROM public.erp_restore_business_generation g WHERE singleton;
 SELECT q.xmin::text INTO STRICT rx FROM public.erp_cloud_restore_requests q WHERE q.idempotency_key=p_attempt_id AND q.actor_id=actor;
 -- 058 advances the singleton in EVERY INSERT/UPDATE/DELETE statement on all
 -- 24 resources, in the same transaction/subtransaction as the epoch+receipt.
 -- Matching unfrozen MVCC provenance is an unchanged-business-generation proof,
 -- not merely a belief in the receipt. A changed field (even unchanged counts),
 -- missing/disabled generation trigger, frozen/old receipt or newer restore
 -- fails closed. No XIDs, business rows or auth identity leave this RPC.
 FOREACH name IN ARRAY names LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=format('public.%I',name)::regclass
   AND t.tgname='erp_restore_business_generation' AND t.tgfoid='public.erp_restore_track_business_generation()'::regprocedure
   AND t.tgenabled IN('O','A') AND t.tgtype=28) THEN coverage:=false; END IF;
  profile:=public.erp_cloud_restore_table_profile(format('public.%I',name)::regclass,NULL::jsonb);
  counts:=counts||jsonb_build_object(name,(profile->>'count')::bigint);
  total:=total+(profile->>'count')::bigint;
  duplicates:=duplicates+(profile->>'duplicateIdentityCount')::bigint+(profile->>'duplicateAuxiliaryIdentityCount')::bigint;
  missing:=missing+(profile->>'missingIdentityCount')::bigint;
  matched:=matched AND (profile->>'count') IS NOT DISTINCT FROM (r.canonical_result->'manifest'->'counts'->>name);
 END LOOP;
 relationships:=public.erp_cloud_restore_live_relationship_hash();
 SELECT count(*) INTO orphans FROM (
  SELECT 1 FROM public.product_categories i LEFT JOIN public.product_groups p ON p.id=i.product_group_id WHERE p.id IS NULL
  UNION ALL SELECT 1 FROM public.product_variants i LEFT JOIN public.product_groups p ON p.id=i.product_group_id WHERE p.id IS NULL
  UNION ALL SELECT 1 FROM public.purchase_batch_items i LEFT JOIN public.purchase_batches p ON p.id=i.purchase_batch_id WHERE p.id IS NULL
  UNION ALL SELECT 1 FROM public.private_order_items i LEFT JOIN public.private_orders p ON p.id=i.private_order_id WHERE p.id IS NULL
  UNION ALL SELECT 1 FROM public.sales_order_items i LEFT JOIN public.sales_orders p ON p.id=i.order_id WHERE p.id IS NULL
  UNION ALL SELECT 1 FROM public.japan_package_items i LEFT JOIN public.japan_packages p ON p.id=i.japan_package_id WHERE p.id IS NULL
  UNION ALL SELECT 1 FROM public.outbound_shipment_items i LEFT JOIN public.outbound_shipments p ON p.id=i.outbound_shipment_id WHERE p.id IS NULL
  UNION ALL SELECT 1 FROM public.waca_order_items i LEFT JOIN public.waca_orders p ON p.id=i.order_id WHERE p.id IS NULL
 ) orphan_rows;
 matched:=matched AND epoch=a.result_epoch AND current_fp=r.canonical_result->>'serverSnapshotFingerprint'
  AND total=(r.canonical_result->'manifest'->>'totalRows')::bigint
  AND (r.canonical_result->'manifest'->>'resourceCount')::integer=24
  AND relationships=r.canonical_result->>'serverRelationshipHash'
  AND gx=rx AND rx=ex AND gx::bigint>2 AND coverage AND duplicates=0 AND missing=0 AND orphans=0;
 -- The certified transaction already ran FK, WACA, canonical and relationship
 -- proofs. Validate WACA again against this statement's authoritative snapshot.
 PERFORM public.erp_cloud_restore_validate_live_waca();
 RETURN jsonb_build_object('contract','restore-committed-verification-v1',
  'status',CASE WHEN matched THEN 'RESTORE_COMMITTED_VERIFIED' ELSE 'RESTORE_COMMITTED_STATE_MISMATCH' END,
  'attemptId',p_attempt_id,'traceId',p_trace_id,'executionId',p_execution_id,
  'restoreEpoch',epoch,'businessGeneration',generation,'snapshotFingerprint',a.effective_fingerprint,
  'serverSnapshotFingerprint',current_fp,'serverRelationshipHash',relationships,
  'counts',counts,'totalRows',total,'duplicateCount',duplicates,'missingIdentityCount',missing,'orphanCount',orphans,
  'generationCertified',gx=rx AND rx=ex AND gx::bigint>2 AND coverage,
  'elapsedMs',(extract(epoch FROM clock_timestamp()-started)*1000)::bigint);
END;
$function$

public.erp_apply_outbound_shipment_trans.definition:
CREATE OR REPLACE FUNCTION public.erp_apply_outbound_shipment_transaction(p_idempotency_key uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '15s'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_shipment_id uuid;
  v_shipment_operation jsonb;
  v_item_operations jsonb;
  v_operation jsonb;
  v_existing public.erp_idempotency_keys%ROWTYPE;
  v_claimed boolean;
  v_request_fingerprint text;
  v_mutation_result jsonb;
  v_failure jsonb;
  v_result jsonb;
  v_top_level_keys text[];
  v_request_headers jsonb;
  v_request_host text;
  v_active_item_ids uuid[];
  v_requested_item_ids uuid[];
BEGIN
  IF v_actor IS NULL OR NOT public.is_editor(v_actor) THEN
    RAISE EXCEPTION 'F4_OUTBOUND_TRANSACTION_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL OR jsonb_typeof(p_request) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'F4_OUTBOUND_REQUEST_INVALID' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(key ORDER BY key), ARRAY[]::text[])
    INTO v_top_level_keys FROM jsonb_object_keys(p_request) key;
  IF v_top_level_keys IS DISTINCT FROM ARRAY[
    'itemOperations','shipmentId','shipmentOperation','targetProjectRef','transactionType'
  ]::text[] THEN
    RAISE EXCEPTION 'F4_OUTBOUND_REQUEST_FIELDS_INVALID' USING ERRCODE = '22023';
  END IF;
  IF p_request->>'transactionType' IS DISTINCT FROM 'delete-shipment'
     OR COALESCE(p_request->>'targetProjectRef', '') !~ '^[a-z0-9]{20}$' THEN
    RAISE EXCEPTION 'F4_OUTBOUND_REQUEST_SCOPE_INVALID' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_request_headers := NULLIF(pg_catalog.current_setting('request.headers', true), '')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_request_headers := NULL;
  END;
  v_request_host := pg_catalog.lower(pg_catalog.split_part(COALESCE(v_request_headers->>'host', ''), ':', 1));
  IF v_request_host IS DISTINCT FROM (p_request->>'targetProjectRef') || '.supabase.co' THEN
    RAISE EXCEPTION 'F4_OUTBOUND_TARGET_PROJECT_MISMATCH' USING ERRCODE = '42501';
  END IF;
  BEGIN
    v_shipment_id := (p_request->>'shipmentId')::uuid;
  EXCEPTION WHEN invalid_text_representation OR null_value_not_allowed THEN
    RAISE EXCEPTION 'F4_OUTBOUND_SHIPMENT_UUID_REQUIRED' USING ERRCODE = '22023';
  END;

  v_shipment_operation := p_request->'shipmentOperation';
  v_item_operations := p_request->'itemOperations';
  IF jsonb_typeof(v_shipment_operation) IS DISTINCT FROM 'object'
     OR v_shipment_operation->>'kind' IS DISTINCT FROM 'delete'
     OR v_shipment_operation->>'id' IS DISTINCT FROM v_shipment_id::text
     OR jsonb_typeof(v_shipment_operation->'expectedVersion') IS DISTINCT FROM 'number'
     OR jsonb_typeof(v_item_operations) IS DISTINCT FROM 'array'
     OR jsonb_array_length(v_item_operations) > 1000 THEN
    RAISE EXCEPTION 'F4_OUTBOUND_DELETE_OPERATIONS_INVALID' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_item_operations) operation
     WHERE operation->>'kind' IS DISTINCT FROM 'delete'
        OR jsonb_typeof(operation->'expectedVersion') IS DISTINCT FROM 'number'
  ) THEN
    RAISE EXCEPTION 'F4_OUTBOUND_ITEM_DELETE_OPERATION_INVALID' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(p_request::text);
  BEGIN
    INSERT INTO public.erp_idempotency_keys (
      actor_id, idempotency_key, operation_type, request_fingerprint,
      request_payload, status
    ) VALUES (
      v_actor, p_idempotency_key, 'edit', v_request_fingerprint,
      p_request, 'processing'
    )
    ON CONFLICT (actor_id, idempotency_key) DO NOTHING
    RETURNING true INTO v_claimed;

    IF COALESCE(v_claimed, false) IS FALSE THEN
      SELECT * INTO v_existing
        FROM public.erp_idempotency_keys
       WHERE actor_id = v_actor AND idempotency_key = p_idempotency_key
       FOR UPDATE;
      IF v_existing.operation_type IS DISTINCT FROM 'edit'
         OR v_existing.request_fingerprint IS DISTINCT FROM v_request_fingerprint
         OR v_existing.request_payload IS DISTINCT FROM p_request THEN
        RETURN jsonb_build_object('ok', false, 'code', 'IDEMPOTENCY_KEY_PAYLOAD_MISMATCH', 'recordId', v_shipment_id);
      END IF;
      IF v_existing.status = 'completed' AND v_existing.canonical_result IS NOT NULL THEN
        RETURN jsonb_set(v_existing.canonical_result, '{replayed}', 'true'::jsonb, true);
      END IF;
      RAISE EXCEPTION 'F4_OUTBOUND_IDEMPOTENCY_INCOMPLETE' USING ERRCODE = '55000';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('outbound_shipments:' || v_shipment_id::text, 0)
    );
    PERFORM 1 FROM public.outbound_shipments shipment
     WHERE shipment.id = v_shipment_id AND shipment.deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN
      v_failure := jsonb_build_object('ok', false, 'code', 'RECORD_DELETED_OR_MISSING', 'entity', 'outbound_shipments', 'recordId', v_shipment_id);
      RAISE EXCEPTION 'F4_OUTBOUND_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(array_agg(item.id ORDER BY item.id), ARRAY[]::uuid[])
      INTO v_active_item_ids
      FROM public.outbound_shipment_items item
     WHERE item.outbound_shipment_id = v_shipment_id AND item.deleted_at IS NULL;
    SELECT COALESCE(array_agg((operation->>'id')::uuid ORDER BY (operation->>'id')::uuid), ARRAY[]::uuid[])
      INTO v_requested_item_ids
      FROM jsonb_array_elements(v_item_operations) operation;
    IF v_requested_item_ids IS DISTINCT FROM v_active_item_ids THEN
      RAISE EXCEPTION 'F4_OUTBOUND_ITEM_SCOPE_MISMATCH' USING ERRCODE = '22023';
    END IF;

    FOR v_operation IN SELECT value FROM jsonb_array_elements(v_item_operations) ORDER BY value->>'id'
    LOOP
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('outbound_shipment_items:' || (v_operation->>'id'), 0)
      );
      PERFORM 1 FROM public.outbound_shipment_items item
       WHERE item.id = (v_operation->>'id')::uuid
         AND item.outbound_shipment_id = v_shipment_id
         AND item.deleted_at IS NULL
       FOR UPDATE;
      IF NOT FOUND THEN
        v_failure := jsonb_build_object('ok', false, 'code', 'RECORD_DELETED_OR_MISSING', 'entity', 'outbound_shipment_items', 'recordId', v_operation->>'id');
        RAISE EXCEPTION 'F4_OUTBOUND_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
      END IF;
    END LOOP;

    IF jsonb_array_length(v_item_operations) > 0 THEN
      v_mutation_result := public.erp_apply_field_mutations('outbound_shipment_items', v_item_operations);
      IF v_mutation_result->>'ok' IS DISTINCT FROM 'true' THEN
        v_failure := v_mutation_result;
        RAISE EXCEPTION 'F4_OUTBOUND_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
      END IF;
    END IF;
    v_mutation_result := public.erp_apply_field_mutations('outbound_shipments', jsonb_build_array(v_shipment_operation));
    IF v_mutation_result->>'ok' IS DISTINCT FROM 'true' THEN
      v_failure := v_mutation_result;
      RAISE EXCEPTION 'F4_OUTBOUND_STRUCTURED_ROLLBACK' USING ERRCODE = 'P0001';
    END IF;

    v_result := jsonb_build_object(
      'ok', true,
      'transactionType', 'delete-shipment',
      'idempotencyKey', p_idempotency_key,
      'replayed', false,
      'shipmentId', v_shipment_id,
      'itemIds', to_jsonb(v_active_item_ids)
    );
    UPDATE public.erp_idempotency_keys
       SET status = 'completed', canonical_result = v_result, completed_at = clock_timestamp()
     WHERE actor_id = v_actor AND idempotency_key = p_idempotency_key;
    RETURN v_result;
  EXCEPTION
    WHEN SQLSTATE 'P0001' THEN
      IF SQLERRM = 'F4_OUTBOUND_STRUCTURED_ROLLBACK' AND v_failure IS NOT NULL THEN RETURN v_failure; END IF;
      RAISE;
    WHEN check_violation OR foreign_key_violation OR not_null_violation OR unique_violation THEN
      RETURN jsonb_build_object('ok', false, 'code', 'TRANSACTION_CONSTRAINT_FAILED', 'recordId', v_shipment_id);
  END;
END;
$function$

public.erp_commit_waca_snapshot_v044(jso.definition:
CREATE OR REPLACE FUNCTION public.erp_commit_waca_snapshot_v044(p_snapshot jsonb, p_expected_revision bigint, p_update_auto_quantity boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
declare
  v_actor uuid := auth.uid(); v_revision bigint; v_previous_mode text;
  v_row jsonb; v_order_id uuid; v_variant_id uuid;
  v_effective integer; v_total integer;
  v_unmatched integer; v_reconciliation_status text;
  v_first_cutover boolean; v_checked_at text := to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
begin
  if v_actor is null or not public.is_owner(v_actor) then
    raise exception using errcode='42501',message='WACA_OWNER_REQUIRED';
  end if;
  if jsonb_typeof(p_snapshot) is distinct from 'object' or p_expected_revision < 0 then
    raise exception using errcode='22023',message='WACA_SNAPSHOT_INVALID';
  end if;
  if exists(select 1 from unnest(array['orders','items','mappings','batches','masterLinks','cutoverAudit']) k
    where jsonb_typeof(p_snapshot->k) is distinct from 'array') then
    raise exception using errcode='22023',message='WACA_SNAPSHOT_COLLECTION_MISSING';
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) then
    raise exception using errcode='55006',message='CLOUD_RESTORE_MAINTENANCE_LOCKED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('erp-waca-ledger-import',0));
  select revision,mode into v_revision,v_previous_mode from public.waca_state for update;
  v_revision := coalesce(v_revision,0);
  v_previous_mode := coalesce(v_previous_mode,'LEGACY_QUANTITY_ACTIVE');
  if v_revision <> p_expected_revision then
    raise exception using errcode='40001',message='WACA_STALE_REVISION';
  end if;
  v_first_cutover := p_update_auto_quantity and v_previous_mode <> 'ORDER_DRIVEN_ACTIVE';

  -- Every operation below shares the caller's PostgreSQL transaction. A raised
  -- validation/reconciliation error rolls back batch, ledger and quantity.
  for v_row in select value from jsonb_array_elements(p_snapshot->'orders') loop
    if coalesce(v_row->>'key','')='' or coalesce(v_row->>'orderNumber','')=''
      or v_row->>'status' not in ('處理中','完成付款','取消','失敗') then
      raise exception using errcode='22023',message='WACA_ORDER_INVALID';
    end if;
    insert into public.waca_orders(order_key,status,payload,updated_by)
    values(v_row->>'key',v_row->>'status',v_row,v_actor)
    on conflict(order_key) do update set status=excluded.status,payload=excluded.payload,
      updated_at=now(),updated_by=v_actor;
  end loop;

  for v_row in select value from jsonb_array_elements(p_snapshot->'items') loop
    select id into v_order_id from public.waca_orders where order_key=v_row->>'orderKey';
    if v_order_id is null or coalesce(v_row->>'key','')=''
       or coalesce(v_row->>'feature','')=''
       or (v_row->>'quantity') !~ '^[0-9]+$' then
      raise exception using errcode='22023',message='WACA_ITEM_INVALID';
    end if;
    v_variant_id := public.erp_waca_variant_id(v_row->>'productVariantId');
    insert into public.waca_order_items(item_key,order_id,feature,product_variant_id,quantity,payload,updated_by)
    values(v_row->>'key',v_order_id,v_row->>'feature',v_variant_id,(v_row->>'quantity')::integer,v_row,v_actor)
    on conflict(item_key) do update set order_id=excluded.order_id,feature=excluded.feature,
      product_variant_id=excluded.product_variant_id,quantity=excluded.quantity,payload=excluded.payload,
      updated_at=now(),updated_by=v_actor;
  end loop;

  for v_row in select value from jsonb_array_elements(p_snapshot->'mappings') loop
    v_variant_id := public.erp_waca_variant_id(v_row->>'productVariantId');
    if v_variant_id is null or coalesce(v_row->>'feature','')='' then
      raise exception using errcode='22023',message='WACA_MAPPING_INVALID';
    end if;
    insert into public.waca_mappings(feature,product_variant_id,payload,updated_by)
    values(v_row->>'feature',v_variant_id,v_row,v_actor)
    on conflict(feature) do update set product_variant_id=excluded.product_variant_id,payload=excluded.payload,
      updated_at=now(),updated_by=v_actor;
  end loop;

  for v_row in select value from jsonb_array_elements(p_snapshot->'masterLinks') loop
    v_variant_id := public.erp_waca_variant_id(v_row->>'productVariantId');
    if coalesce(v_row->>'childCode','')='' or coalesce(v_row->>'mainCode','')='' then
      raise exception using errcode='22023',message='WACA_MASTER_LINK_INVALID';
    end if;
    insert into public.waca_master_links(child_code,main_code,product_variant_id,payload,updated_by)
    values(v_row->>'childCode',v_row->>'mainCode',v_variant_id,v_row,v_actor)
    on conflict(child_code) do update set main_code=excluded.main_code,
      product_variant_id=excluded.product_variant_id,payload=excluded.payload,
      updated_at=now(),updated_by=v_actor;
  end loop;

  for v_row in select value from jsonb_array_elements(p_snapshot->'batches') loop
    if coalesce(v_row->>'id','')='' then raise exception using errcode='22023',message='WACA_BATCH_INVALID'; end if;
    insert into public.waca_import_batches(batch_key,payload,updated_by)
    values(v_row->>'id',v_row,v_actor)
    on conflict(batch_key) do update set payload=excluded.payload,updated_at=now(),updated_by=v_actor;
  end loop;

  for v_row in select value from jsonb_array_elements(p_snapshot->'cutoverAudit') loop
    v_variant_id := public.erp_waca_variant_id(v_row->>'productVariantId');
    if v_variant_id is null then raise exception using errcode='22023',message='WACA_CUTOVER_AUDIT_INVALID'; end if;
    insert into public.waca_cutover_audit(product_variant_id,payload,updated_by)
    values(v_variant_id,v_row,v_actor)
    on conflict(product_variant_id) do update set payload=excluded.payload,updated_at=now(),updated_by=v_actor;
  end loop;

  if exists(select 1 from public.waca_order_items i
    join public.waca_mappings m on m.feature=i.feature
    where i.product_variant_id is not null and i.product_variant_id<>m.product_variant_id) then
    raise exception using errcode='23000',message='WACA_MAPPING_RECONCILIATION_FAILED';
  end if;

  if p_update_auto_quantity then
    if v_first_cutover then
      insert into public.waca_cutover_audit(product_variant_id,payload,updated_by)
      select v.id,jsonb_build_object(
        'productVariantId',coalesce(v.local_id,v.id::text),
        'sku',v.myacg_item_code,'productTitle',v.product_title,'variantTitle',v.variant_name,
        'legacyWacaQuantity',v.waca_auto_quantity+v.waca_manual_adjustment,
        'legacyAutoQuantity',v.waca_auto_quantity,
        'unverifiedPreCutoverManualQuantity',v.waca_manual_adjustment,
        'newOrderDerivedQuantity',coalesce(q.quantity,0),
        'difference',coalesce(q.quantity,0)-v.waca_auto_quantity-v.waca_manual_adjustment,
        'cutoverAt',v_checked_at),v_actor
      from public.product_variants v
      left join (select i.product_variant_id,sum(i.quantity)::integer quantity
        from public.waca_order_items i join public.waca_orders o on o.id=i.order_id
        where i.product_variant_id is not null and o.status in ('處理中','完成付款')
        group by i.product_variant_id) q on q.product_variant_id=v.id
      on conflict(product_variant_id) do nothing;
    end if;
    update public.product_variants v set
      waca_auto_quantity=coalesce(q.quantity,0),
      waca_manual_adjustment=case when v_first_cutover then 0 else v.waca_manual_adjustment end,
      updated_at=now(),updated_by=v_actor,version=v.version+1
    from (select v2.id, sum(i.quantity) filter(where o.status in ('處理中','完成付款'))::integer quantity
      from public.product_variants v2
      left join public.waca_order_items i on i.product_variant_id=v2.id
      left join public.waca_orders o on o.id=i.order_id group by v2.id) q
    where q.id=v.id and (v.waca_auto_quantity is distinct from coalesce(q.quantity,0)
      or (v_first_cutover and v.waca_manual_adjustment <> 0));
  end if;

  select coalesce(sum(i.quantity),0)::integer into v_effective
    from public.waca_order_items i join public.waca_orders o on o.id=i.order_id
    where o.status in ('處理中','完成付款');
  select count(distinct feature)::integer into v_total from public.waca_order_items where product_variant_id is not null;
  select count(distinct i.feature)::integer into v_unmatched
    from public.waca_order_items i join public.waca_orders o on o.id=i.order_id
    where i.product_variant_id is null and i.quantity>0 and o.status in ('處理中','完成付款');
  v_reconciliation_status := case when v_unmatched=0 then 'PASS' else 'FAIL' end;
  if p_update_auto_quantity and exists(
    select 1 from public.product_variants v left join (
      select i.product_variant_id,sum(i.quantity)::integer quantity
      from public.waca_order_items i join public.waca_orders o on o.id=i.order_id
      where i.product_variant_id is not null and o.status in ('處理中','完成付款')
      group by i.product_variant_id) q on q.product_variant_id=v.id
    where v.waca_auto_quantity is distinct from coalesce(q.quantity,0)
  ) then raise exception using errcode='23000',message='WACA_RECONCILIATION_FAILED'; end if;
  if p_update_auto_quantity then
    update public.waca_import_batches b set
      payload=b.payload || jsonb_build_object('reconciliation',jsonb_build_object(
        'status',v_reconciliation_status,'passed',v_total,'total',v_total+v_unmatched,
        'effectiveQuantity',v_effective,'checkedAt',v_checked_at)),updated_at=now()
      where b.batch_key in (select value->>'id' from jsonb_array_elements(p_snapshot->'batches'));
  end if;
  insert into public.waca_state(id,revision,mode,payload,updated_by)
    values('00000000-0000-4000-8000-000000000001',v_revision+1,
      case when p_update_auto_quantity then 'ORDER_DRIVEN_ACTIVE' else v_previous_mode end,
      jsonb_build_object('mode',case when p_update_auto_quantity then 'ORDER_DRIVEN_ACTIVE' else v_previous_mode end,
        'updatedAt',v_checked_at,'sourceBackupFormatVersion',p_snapshot->'cutoverState'->'sourceBackupFormatVersion'),v_actor)
    on conflict(id) do update set revision=excluded.revision,mode=excluded.mode,
      payload=excluded.payload,updated_at=now(),updated_by=v_actor;
  return jsonb_build_object('revision',v_revision+1,'reconciliation',v_reconciliation_status,
    'effectiveQuantity',v_effective,'unmatchedFeatures',v_unmatched);
end;
$function$

public.erp_prove_cloud_restore_candidate.definition:
CREATE OR REPLACE FUNCTION public.erp_prove_cloud_restore_candidate(p_source_snapshot jsonb, p_manifest jsonb, p_restore_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_started_at timestamptz := clock_timestamp();
  v_request_headers jsonb;
  v_request_host text;
  v_policy text;
  v_expected_source_fingerprint text;
  v_source_fingerprint text;
  v_effective_fingerprint text;
  v_effective jsonb;
  v_validation jsonb;
  v_audit jsonb;
  v_integrity jsonb;
  v_coverage_count integer;
  v_transformed bigint := 0;
begin
  if v_actor is null then
    raise exception using errcode='42501', message='AUTHENTICATION_REQUIRED';
  end if;
  if public.is_owner(v_actor) is distinct from true then
    raise exception using errcode='42501', message='CLOUD_RESTORE_OWNER_REQUIRED';
  end if;
  begin
    v_request_headers := nullif(current_setting('request.headers',true),'')::jsonb;
  exception when others then
    raise exception using errcode='22023', message='CLOUD_RESTORE_PROOF_TARGET_MISMATCH';
  end;
  v_request_host := lower(split_part(coalesce(v_request_headers->>'host',''),':',1));
  if split_part(v_request_host,'.',1) is distinct from 'rhfdjsklfrgpoqsaqpkn' then
    raise exception using errcode='22023', message='CLOUD_RESTORE_PROOF_TARGET_MISMATCH';
  end if;
  if jsonb_typeof(p_source_snapshot) is distinct from 'object'
     or jsonb_typeof(p_manifest) is distinct from 'object'
     or p_restore_mode is null
     or p_restore_mode not in ('strict','cross-environment') then
    raise exception using errcode='22023', message='CLOUD_RESTORE_PROOF_INPUT_INVALID';
  end if;

  if p_restore_mode='cross-environment' then
    if jsonb_typeof(p_manifest->'portability') is distinct from 'object'
       or p_manifest->'portability'->>'policyVersion' is distinct from 'cross-environment-audit-null-v1'
       or p_manifest->'portability'->>'mode' is distinct from 'cross-environment'
       or p_manifest->'portability'->>'targetProjectRef' is distinct from 'rhfdjsklfrgpoqsaqpkn'
       or jsonb_typeof(p_manifest->'portability'->'totalTransformedRows') is distinct from 'number'
       or coalesce(p_manifest->'portability'->>'totalTransformedRows','') !~ '^[0-9]+$' then
      raise exception using errcode='22023', message='CLOUD_RESTORE_PROOF_POLICY_INVALID';
    end if;
    v_policy := p_manifest->'portability'->>'policyVersion';
    v_expected_source_fingerprint := p_manifest->'portability'->>'sourceSnapshotFingerprint';
    v_transformed := (p_manifest->'portability'->>'totalTransformedRows')::bigint;
  else
    if p_manifest ? 'portability' then
      raise exception using errcode='22023', message='CLOUD_RESTORE_PROOF_POLICY_INVALID';
    end if;
    v_policy := 'strict';
    v_expected_source_fingerprint := p_manifest->>'snapshotFingerprint';
  end if;
  if coalesce(v_expected_source_fingerprint,'') !~ '^[0-9a-f]{64}$'
     or coalesce(p_manifest->>'snapshotFingerprint','') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023', message='CLOUD_RESTORE_PROOF_FINGERPRINT_INVALID';
  end if;

  v_source_fingerprint := encode(extensions.digest(convert_to(
    public.erp_cloud_restore_canonical_json_text(p_source_snapshot),'UTF8'
  ),'sha256'),'hex');
  if v_source_fingerprint is distinct from v_expected_source_fingerprint then
    raise exception using errcode='22023', message='CLOUD_RESTORE_PROOF_SOURCE_FINGERPRINT_MISMATCH';
  end if;

  v_effective := public.erp_cloud_restore_build_effective_snapshot(
    p_source_snapshot,
    p_manifest,
    p_restore_mode
  );
  if p_restore_mode='cross-environment' then
    v_validation := public.erp_cloud_restore_validate_portability(
      v_effective,
      p_manifest,
      'rhfdjsklfrgpoqsaqpkn'
    );
    if v_validation->>'ok' is distinct from 'true' then
      raise exception using errcode='22023', message='CLOUD_RESTORE_PROOF_PORTABILITY_INVALID';
    end if;
  end if;

  -- Closed dataset coverage is checked before fingerprints so unknown resources
  -- cannot be disguised as a generic hash mismatch.
  perform public.erp_cloud_restore_validate_waca_dataset(v_effective);
  v_audit := public.erp_cloud_restore_audit_dataset(v_effective);
  v_effective_fingerprint := encode(extensions.digest(convert_to(
    public.erp_cloud_restore_canonical_json_text(v_effective),'UTF8'
  ),'sha256'),'hex');
  if v_effective_fingerprint is distinct from p_manifest->>'snapshotFingerprint' then
    raise exception using errcode='22023', message='CLOUD_RESTORE_PROOF_EFFECTIVE_FINGERPRINT_MISMATCH';
  end if;
  v_integrity := v_audit->'integrity';
  select count(*) into v_coverage_count from jsonb_object_keys(v_audit->'table_counts');
  if jsonb_typeof(p_manifest->'resourceCount') is distinct from 'number'
     or jsonb_typeof(p_manifest->'totalRows') is distinct from 'number'
     or jsonb_typeof(p_manifest->'orphanCount') is distinct from 'number'
     or jsonb_typeof(p_manifest->'duplicateVariantIdCount') is distinct from 'number'
     or jsonb_typeof(p_manifest->'duplicateVariantLocalIdCount') is distinct from 'number'
     or jsonb_typeof(p_manifest->'duplicateCanonicalIdCount') is distinct from 'number'
     or jsonb_typeof(p_manifest->'canonicalIdentityAnomalyCount') is distinct from 'number'
     or jsonb_typeof(p_manifest->'unknownProductCount') is distinct from 'number'
     or jsonb_typeof(p_manifest->'optionalMetadataMissingReferenceCount') is distinct from 'number'
     or v_coverage_count <> 24
     or p_manifest->>'resourceCount' is distinct from '24'
     or jsonb_typeof(p_manifest->'counts') is distinct from 'object'
     or p_manifest->'counts' is distinct from v_audit->'table_counts'
     or (p_manifest->>'totalRows')::bigint is distinct from (v_audit->>'total_rows')::bigint
     or p_manifest->>'relationshipHash' is distinct from v_audit->>'relationship_hash'
     or (p_manifest->>'orphanCount')::bigint is distinct from (v_integrity->>'orphan_count')::bigint
     or (p_manifest->>'duplicateVariantIdCount')::bigint is distinct from (v_integrity->>'duplicate_variant_id_count')::bigint
     or (p_manifest->>'duplicateVariantLocalIdCount')::bigint is distinct from (v_integrity->>'duplicate_variant_local_id_count')::bigint
     or (p_manifest->>'duplicateCanonicalIdCount')::bigint is distinct from (v_integrity->>'duplicate_canonical_id_count')::bigint
     or (p_manifest->>'canonicalIdentityAnomalyCount')::bigint is distinct from (v_integrity->>'canonical_identity_anomaly_count')::bigint
     or (p_manifest->>'unknownProductCount')::bigint is distinct from (v_integrity->>'unknown_product_count')::bigint
     or (p_manifest->>'optionalMetadataMissingReferenceCount')::bigint is distinct from (v_integrity->>'optional_metadata_missing_reference_count')::bigint
     or (v_integrity->>'duplicate_inventory_key_count')::bigint <> 0
     or (v_integrity->>'missing_inventory_key_count')::bigint <> 0
     or (p_restore_mode='cross-environment' and (
       (v_audit->'audit_policy'->>'covered_updated_by_non_null_count')::bigint <> 0
       or (v_audit->'audit_policy'->>'covered_updated_by_null_count')::bigint
          is distinct from (v_audit->>'total_rows')::bigint
     )) then
    raise exception using errcode='22023', message='CLOUD_RESTORE_PROOF_CANDIDATE_INVALID';
  end if;

  return jsonb_build_object(
    'ok',true,
    'candidate_valid',true,
    'schema_version','cloud-restore-candidate-proof-v1',
    'policy',v_policy,
    'resource_count',24,
    'coverage_count',v_coverage_count,
    'total_rows',(v_audit->>'total_rows')::bigint,
    'table_counts',v_audit->'table_counts',
    'transformed_updated_by_count',v_transformed,
    'source_fingerprint',v_source_fingerprint,
    'effective_fingerprint',v_effective_fingerprint,
    'relationship_hash',v_audit->>'relationship_hash',
    'integrity',v_integrity,
    'elapsed_ms',(extract(epoch from clock_timestamp()-v_started_at)*1000)::bigint
  );
end;
$function$

public.erp_reconcile_private_order_trans.definition:
CREATE OR REPLACE FUNCTION public.erp_reconcile_private_order_transaction(p_idempotency_key uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); prior public.erp_idempotency_keys%ROWTYPE;
BEGIN
  IF actor IS NULL OR NOT public.is_editor(actor) THEN RAISE EXCEPTION 'PRIVATE_ORDER_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF p_idempotency_key IS NULL OR p_request->>'family' IS DISTINCT FROM 'private-order' THEN
    RAISE EXCEPTION 'PRIVATE_ORDER_INVALID_REQUEST' USING ERRCODE='22023'; END IF;
  SELECT * INTO prior FROM public.erp_idempotency_keys WHERE actor_id=actor AND idempotency_key=p_idempotency_key;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',true,'committed',false); END IF;
  IF prior.request_payload IS DISTINCT FROM p_request THEN RAISE EXCEPTION 'PRIVATE_ORDER_REQUEST_MISMATCH' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('ok',true,'committed',prior.status='completed');
END; $function$

public.erp_commit_waca_counted_snapshot(.definition:
CREATE OR REPLACE FUNCTION public.erp_commit_waca_counted_snapshot(p_snapshot jsonb, p_expected_revision bigint, p_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
declare result jsonb; clean jsonb; epoch bigint; v record; keys jsonb;
begin
  if auth.uid() is null or not public.is_owner(auth.uid()) then raise exception using errcode='42501',message='WACA_OWNER_REQUIRED'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) then
    raise exception using errcode='55006',message='CLOUD_RESTORE_MAINTENANCE_LOCKED'; end if;
  perform pg_advisory_xact_lock(hashtextextended('erp-waca-ledger-import',0));
  perform public.erp_assert_waca_recognition_preserved(p_snapshot);
  select e.epoch into epoch from public.erp_cloud_restore_epoch e where singleton;
  -- Preserve a line's credit only across an unbroken controlled-write chain.
  -- A manual edit invalidates old credits permanently; a later import must NOT
  -- launder them into a new "safe" receipt.
  perform 1 from public.product_variants pv where pv.id in (
    select public.erp_waca_variant_id(k) from jsonb_object_keys(p_plan->'expectedDisplay') k
  ) order by pv.id for update;
  create temporary table _waca_recognition_credits on commit drop as
    select pv.id,pv.version,public.erp_waca_reversal_keys(pv.id,epoch) keys,
      coalesce((select jsonb_object_agg(i.item_key,coalesce((i.payload->>'countedQuantity')::integer,0))
        from public.waca_order_items i where i.product_variant_id=pv.id),'{}'::jsonb) counts
    from public.product_variants pv where pv.id in (
      select public.erp_waca_variant_id(k) from jsonb_object_keys(p_plan->'expectedDisplay') k);
  clean:=public.erp_prune_waca_recognition_evidence(p_snapshot);
  result:=public.erp_commit_waca_counted_snapshot_v074(clean,p_expected_revision,p_plan);
  for v in select pv.*,c.keys,c.counts from public.product_variants pv join _waca_recognition_credits c on c.id=pv.id
    where pv.version<>c.version loop
    if exists(select 1 from jsonb_array_elements(p_plan->'overwriteVariantIds') x where public.erp_waca_variant_id(x#>>'{}')=v.id) then keys:='[]'::jsonb;
    else
      select coalesce(jsonb_agg(i.item_key order by i.item_key),'[]'::jsonb) into keys from public.waca_order_items i
        where i.product_variant_id=v.id and coalesce((i.payload->>'countedQuantity')::integer,0)>0
          and (v.keys ? i.item_key or coalesce((v.counts->>i.item_key)::integer,0)=0);
    end if;
    perform public.erp_store_waca_recognition_continuity(v.id,epoch,keys);
  end loop;
  return result;
end;
$function$

public.erp_cloud_restore_idempotency_fin.definition:
CREATE OR REPLACE FUNCTION public.erp_cloud_restore_idempotency_fingerprint(p_snapshot jsonb, p_manifest jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if p_manifest ? 'portability' then
    perform public.erp_cloud_restore_validate_portability(
      p_snapshot,
      p_manifest,
      p_manifest->'portability'->>'targetProjectRef'
    );
    return encode(digest(convert_to(jsonb_build_object(
      'snapshot', p_snapshot,
      'portability', p_manifest->'portability'
    )::text, 'UTF8'), 'sha256'), 'hex');
  end if;
  return encode(digest(convert_to(p_snapshot::text, 'UTF8'), 'sha256'), 'hex');
end;
$function$

public.erp_restore_cloud_snapshot(uuid,t.definition:
CREATE OR REPLACE FUNCTION public.erp_restore_cloud_snapshot(p_idempotency_key uuid, p_snapshot_fingerprint text, p_snapshot jsonb, p_manifest jsonb, p_source_environment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_existing public.erp_cloud_restore_requests%rowtype;
  v_rollback_id uuid;
  v_before jsonb;
  v_before_counts jsonb := '{}'::jsonb;
  v_before_manifest jsonb;
  v_before_fingerprint text;
  v_expected_profiles jsonb := '{}'::jsonb;
  v_expected_profile jsonb;
  v_actual_profile jsonb;
  v_counts jsonb := '{}'::jsonb;
  v_table text;
  v_expected bigint;
  v_epoch bigint;
  v_result jsonb;
  v_server_fingerprint text;
  v_expected_relationship_hash text;
  v_actual_relationship_hash text;
  v_started_at timestamptz := clock_timestamp();
  v_phase_started_at timestamptz := clock_timestamp();
  v_phase_ms bigint;
  v_phase_timings jsonb := '{}'::jsonb;
  v_current_phase text := 'auth';
begin
  raise log 'CLOUD_RESTORE_TIMING phase=auth event=start';
  if v_actor is null then raise exception using errcode = '42501', message = 'AUTHENTICATION_REQUIRED'; end if;
  if not public.is_owner(v_actor) then raise exception using errcode = '42501', message = 'CLOUD_RESTORE_OWNER_REQUIRED'; end if;
  if p_idempotency_key is null or p_snapshot_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_REQUEST_INVALID';
  end if;
  if jsonb_typeof(p_snapshot) is distinct from 'object' then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_SNAPSHOT_INVALID';
  end if;
  if jsonb_typeof(p_manifest) is distinct from 'object'
     or p_manifest->>'schemaVersion' is distinct from 'cloud-erp-snapshot-v2' then
    raise exception using errcode = '22023', message = 'UNSUPPORTED_SCHEMA_VERSION';
  end if;
  if jsonb_typeof(p_manifest->'counts') is distinct from 'object'
     or (p_manifest->>'resourceCount')::bigint <> 24
     or coalesce((p_manifest->>'orphanCount')::bigint, -1) <> 0
     or coalesce((p_manifest->>'duplicateVariantIdCount')::bigint, -1) <> 0
     or coalesce((p_manifest->>'duplicateVariantLocalIdCount')::bigint, -1) <> 0 then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_MANIFEST_INVALID';
  end if;
  v_phase_ms := (extract(epoch from clock_timestamp() - v_phase_started_at) * 1000)::bigint;
  v_phase_timings := v_phase_timings || jsonb_build_object('auth', v_phase_ms);
  raise log 'CLOUD_RESTORE_TIMING phase=auth event=complete duration_ms=%', v_phase_ms;

  v_phase_started_at := clock_timestamp();
  v_current_phase := 'lock_idempotency';
  raise log 'CLOUD_RESTORE_TIMING phase=lock_idempotency event=start';
  v_server_fingerprint := public.erp_cloud_restore_idempotency_fingerprint(p_snapshot, p_manifest);
  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock', 0)) then
    raise exception using errcode = '55006', message = 'CLOUD_RESTORE_LOCK_CONFLICT';
  end if;
  insert into public.erp_cloud_restore_requests(actor_id,idempotency_key,snapshot_fingerprint,status)
  values(v_actor,p_idempotency_key,v_server_fingerprint,'processing')
  on conflict(actor_id,idempotency_key) do nothing;
  select * into v_existing from public.erp_cloud_restore_requests
   where actor_id=v_actor and idempotency_key=p_idempotency_key for update;
  if v_existing.snapshot_fingerprint <> v_server_fingerprint then
    raise exception using errcode = '22023', message = 'RESTORE_IDEMPOTENCY_PAYLOAD_MISMATCH';
  end if;
  if v_existing.status = 'completed' then
    raise log 'CLOUD_RESTORE_TIMING phase=lock_idempotency event=replay duration_ms=%',
      (extract(epoch from clock_timestamp() - v_phase_started_at) * 1000)::bigint;
    return v_existing.canonical_result || jsonb_build_object('replayed', true);
  end if;
  v_phase_ms := (extract(epoch from clock_timestamp() - v_phase_started_at) * 1000)::bigint;
  v_phase_timings := v_phase_timings || jsonb_build_object('lockIdempotency', v_phase_ms);
  raise log 'CLOUD_RESTORE_TIMING phase=lock_idempotency event=complete duration_ms=%', v_phase_ms;

  v_phase_started_at := clock_timestamp();
  v_current_phase := 'input_validation';
  raise log 'CLOUD_RESTORE_TIMING phase=input_validation event=start';
  foreach v_table in array array[
    'inventory_items','product_groups','product_categories','product_variants','bundle_components',
    'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
    'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
    'waca_orders','waca_order_items','waca_mappings','waca_master_links',
    'waca_import_batches','waca_cutover_audit','waca_state'
  ] loop
    if jsonb_typeof(p_snapshot->v_table) <> 'array' then
      raise exception using errcode = '22023', message = 'CLOUD_RESTORE_RESOURCE_REQUIRED:' || v_table;
    end if;
    v_expected_profile := public.erp_cloud_restore_table_profile(
      format('public.%I', v_table)::regclass,
      p_snapshot->v_table
    );
    v_expected := (v_expected_profile->>'count')::bigint;
    if coalesce((p_manifest->'counts'->>v_table)::bigint, -1) <> v_expected then
      raise exception using errcode = '22023', message = 'CLOUD_RESTORE_MANIFEST_COUNT_MISMATCH:' || v_table;
    end if;
    if (v_expected_profile->>'missingIdentityCount')::bigint > 0 then
      raise exception using errcode = '22023', message = 'CLOUD_RESTORE_IDENTITY_REQUIRED:' || v_table;
    end if;
    if (v_expected_profile->>'duplicateIdentityCount')::bigint > 0 then
      raise exception using errcode = '23505', message = 'DUPLICATE_CANONICAL_ID:' || v_table;
    end if;
    if v_table = 'product_variants'
       and (v_expected_profile->>'duplicateAuxiliaryIdentityCount')::bigint > 0 then
      raise exception using errcode = '23505', message = 'DUPLICATE_VARIANT_LOCAL_ID';
    end if;
    v_expected_profiles := v_expected_profiles || jsonb_build_object(v_table, v_expected_profile);
    v_counts := v_counts || jsonb_build_object(v_table, v_expected);
  end loop;
  if coalesce((p_manifest->>'totalRows')::bigint, -1)
     <> (select coalesce(sum(value::bigint), 0) from jsonb_each_text(v_counts)) then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_MANIFEST_TOTAL_MISMATCH';
  end if;
  perform public.erp_cloud_restore_validate_waca_dataset(p_snapshot);
  v_expected_relationship_hash := public.erp_cloud_restore_relationship_hash(p_snapshot);
  v_phase_ms := (extract(epoch from clock_timestamp() - v_phase_started_at) * 1000)::bigint;
  v_phase_timings := v_phase_timings || jsonb_build_object('inputValidation', v_phase_ms);
  raise log 'CLOUD_RESTORE_TIMING phase=input_validation event=complete duration_ms=%', v_phase_ms;

  v_phase_started_at := clock_timestamp();
  v_current_phase := 'before_snapshot';
  raise log 'CLOUD_RESTORE_TIMING phase=before_snapshot event=start';
  v_before := public.erp_cloud_restore_snapshot();
  foreach v_table in array array[
    'inventory_items','product_groups','product_categories','product_variants','bundle_components',
    'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
    'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
    'waca_orders','waca_order_items','waca_mappings','waca_master_links',
    'waca_import_batches','waca_cutover_audit','waca_state'
  ] loop
    v_before_counts := v_before_counts || jsonb_build_object(v_table, jsonb_array_length(v_before->v_table));
  end loop;
  v_before_fingerprint := encode(digest(convert_to(v_before::text, 'UTF8'), 'sha256'), 'hex');
  v_before_manifest := jsonb_build_object(
    'schemaVersion', 'cloud-erp-snapshot-v2',
    'resourceCount', 24,
    'counts', v_before_counts,
    'totalRows', (select coalesce(sum(value::bigint), 0) from jsonb_each_text(v_before_counts)),
    'snapshotFingerprint', v_before_fingerprint,
    'relationshipHash', public.erp_cloud_restore_relationship_hash(v_before),
    'restoreSourceEnvironment', p_source_environment
  );
  v_phase_ms := (extract(epoch from clock_timestamp() - v_phase_started_at) * 1000)::bigint;
  v_phase_timings := v_phase_timings || jsonb_build_object('beforeSnapshot', v_phase_ms);
  raise log 'CLOUD_RESTORE_TIMING phase=before_snapshot event=complete duration_ms=%', v_phase_ms;

  v_phase_started_at := clock_timestamp();
  v_current_phase := 'rollback_row';
  raise log 'CLOUD_RESTORE_TIMING phase=rollback_row event=start';
  insert into public.erp_cloud_restore_snapshots(actor_id,source_environment,snapshot_fingerprint,manifest,snapshot)
  values(
    v_actor,
    coalesce(nullif(current_setting('request.headers', true), '')::jsonb->>'host', 'unknown'),
    v_before_fingerprint,
    v_before_manifest,
    v_before
  )
  returning id into v_rollback_id;
  v_phase_ms := (extract(epoch from clock_timestamp() - v_phase_started_at) * 1000)::bigint;
  v_phase_timings := v_phase_timings || jsonb_build_object('rollbackRow', v_phase_ms);
  raise log 'CLOUD_RESTORE_TIMING phase=rollback_row event=complete duration_ms=%', v_phase_ms;

  perform set_config('erp.cloud_restore_active','on',true);
  v_phase_started_at := clock_timestamp();
  v_current_phase := 'delete';
  raise log 'CLOUD_RESTORE_TIMING phase=delete event=start';
  delete from public.outbound_shipment_items where id is not null;
  delete from public.outbound_shipments where id is not null;
  delete from public.japan_package_items where id is not null;
  delete from public.japan_packages where id is not null;
  delete from public.private_order_items where id is not null;
  delete from public.purchase_batch_items where id is not null;
  delete from public.sales_order_items where id is not null;
  delete from public.bundle_components where id is not null;
  delete from public.private_orders where id is not null;
  delete from public.purchase_batches where id is not null;
  delete from public.dashboard_category_images where id is not null;
  delete from public.waca_order_items where id is not null;
  delete from public.waca_mappings where id is not null;
  delete from public.waca_master_links where id is not null;
  delete from public.waca_cutover_audit where id is not null;
  delete from public.waca_import_batches where id is not null;
  delete from public.waca_state where id is not null;
  delete from public.waca_orders where id is not null;
  delete from public.import_batches where id is not null;
  delete from public.product_variants where id is not null;
  delete from public.product_categories where id is not null;
  delete from public.sales_orders where id is not null;
  delete from public.product_groups where id is not null;
  delete from public.inventory_items where id is not null;
  v_phase_ms := (extract(epoch from clock_timestamp() - v_phase_started_at) * 1000)::bigint;
  v_phase_timings := v_phase_timings || jsonb_build_object('delete', v_phase_ms);
  raise log 'CLOUD_RESTORE_TIMING phase=delete event=complete duration_ms=%', v_phase_ms;

  v_phase_started_at := clock_timestamp();
  v_current_phase := 'insert';
  raise log 'CLOUD_RESTORE_TIMING phase=insert event=start';
  perform public.erp_cloud_restore_insert_rows('public.inventory_items', p_snapshot->'inventory_items');
  perform public.erp_cloud_restore_insert_rows('public.product_groups', p_snapshot->'product_groups');
  perform public.erp_cloud_restore_insert_rows('public.product_categories', p_snapshot->'product_categories');
  perform public.erp_cloud_restore_insert_rows('public.product_variants', p_snapshot->'product_variants');
  perform public.erp_cloud_restore_insert_rows('public.bundle_components', p_snapshot->'bundle_components');
  perform public.erp_cloud_restore_insert_rows('public.purchase_batches', p_snapshot->'purchase_batches');
  perform public.erp_cloud_restore_insert_rows('public.purchase_batch_items', p_snapshot->'purchase_batch_items');
  perform public.erp_cloud_restore_insert_rows('public.private_orders', p_snapshot->'private_orders');
  perform public.erp_cloud_restore_insert_rows('public.private_order_items', p_snapshot->'private_order_items');
  perform public.erp_cloud_restore_insert_rows('public.sales_orders', p_snapshot->'sales_orders');
  perform public.erp_cloud_restore_insert_rows('public.sales_order_items', p_snapshot->'sales_order_items');
  perform public.erp_cloud_restore_insert_rows('public.japan_packages', p_snapshot->'japan_packages');
  perform public.erp_cloud_restore_insert_rows('public.japan_package_items', p_snapshot->'japan_package_items');
  perform public.erp_cloud_restore_insert_rows('public.outbound_shipments', p_snapshot->'outbound_shipments');
  perform public.erp_cloud_restore_insert_rows('public.outbound_shipment_items', p_snapshot->'outbound_shipment_items');
  perform public.erp_cloud_restore_insert_rows('public.dashboard_category_images', p_snapshot->'dashboard_category_images');
  perform public.erp_cloud_restore_insert_rows('public.import_batches', p_snapshot->'import_batches');
  perform public.erp_cloud_restore_insert_rows('public.waca_orders', p_snapshot->'waca_orders');
  perform public.erp_cloud_restore_insert_rows('public.waca_order_items', p_snapshot->'waca_order_items');
  perform public.erp_cloud_restore_insert_rows('public.waca_mappings', p_snapshot->'waca_mappings');
  perform public.erp_cloud_restore_insert_rows('public.waca_master_links', p_snapshot->'waca_master_links');
  perform public.erp_cloud_restore_insert_rows('public.waca_import_batches', p_snapshot->'waca_import_batches');
  perform public.erp_cloud_restore_insert_rows('public.waca_cutover_audit', p_snapshot->'waca_cutover_audit');
  perform public.erp_cloud_restore_insert_rows('public.waca_state', p_snapshot->'waca_state');
  perform public.erp_cloud_restore_recompute_waca_quantities();
  perform public.erp_cloud_restore_validate_waca_dataset(public.erp_cloud_restore_snapshot());
  v_phase_ms := (extract(epoch from clock_timestamp() - v_phase_started_at) * 1000)::bigint;
  v_phase_timings := v_phase_timings || jsonb_build_object('insert', v_phase_ms);
  raise log 'CLOUD_RESTORE_TIMING phase=insert event=complete duration_ms=%', v_phase_ms;

  v_phase_started_at := clock_timestamp();
  v_current_phase := 'integrity';
  raise log 'CLOUD_RESTORE_TIMING phase=integrity event=start';
  foreach v_table in array array[
    'inventory_items','product_groups','product_categories','product_variants','bundle_components',
    'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
    'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
    'waca_orders','waca_order_items','waca_mappings','waca_master_links',
    'waca_import_batches','waca_cutover_audit','waca_state'
  ] loop
    v_actual_profile := public.erp_cloud_restore_table_profile(format('public.%I', v_table)::regclass, null::jsonb);
    v_expected_profile := v_expected_profiles->v_table;
    if (v_actual_profile->>'count')::bigint <> (v_expected_profile->>'count')::bigint then
      raise exception using errcode = '23000', message = 'CLOUD_RESTORE_POST_INTEGRITY_COUNT_MISMATCH:' || v_table;
    end if;
    if v_actual_profile->>'identityHash' is distinct from v_expected_profile->>'identityHash' then
      raise exception using errcode = '23000', message = 'CLOUD_RESTORE_POST_INTEGRITY_IDENTITY_HASH_MISMATCH:' || v_table;
    end if;
  end loop;

  if exists (
    select 1 from public.product_variants v left join public.product_groups g on g.id=v.product_group_id where g.id is null
    union all select 1 from public.purchase_batch_items i left join public.purchase_batches b on b.id=i.purchase_batch_id where b.id is null
    union all select 1 from public.private_order_items i left join public.private_orders o on o.id=i.private_order_id where o.id is null
    union all select 1 from public.sales_order_items i left join public.sales_orders o on o.id=i.order_id where o.id is null
    union all select 1 from public.japan_package_items i left join public.japan_packages p on p.id=i.japan_package_id where p.id is null
    union all select 1 from public.outbound_shipment_items i left join public.outbound_shipments s on s.id=i.outbound_shipment_id where s.id is null
  ) then raise exception using errcode = '23503', message = 'CLOUD_RESTORE_POST_INTEGRITY_ORPHAN'; end if;
  v_actual_relationship_hash := public.erp_cloud_restore_live_relationship_hash();
  if v_actual_relationship_hash <> v_expected_relationship_hash then
    raise exception using errcode = '23000', message = 'CLOUD_RESTORE_POST_INTEGRITY_RELATIONSHIP_HASH_MISMATCH';
  end if;
  v_phase_ms := (extract(epoch from clock_timestamp() - v_phase_started_at) * 1000)::bigint;
  v_phase_timings := v_phase_timings || jsonb_build_object('integrity', v_phase_ms);
  raise log 'CLOUD_RESTORE_TIMING phase=integrity event=complete duration_ms=%', v_phase_ms;

  v_phase_started_at := clock_timestamp();
  v_current_phase := 'epoch_idempotency';
  raise log 'CLOUD_RESTORE_TIMING phase=epoch_idempotency event=start';
  update public.erp_cloud_restore_epoch
     set epoch=epoch+1, restored_at=now(), restored_by=v_actor, snapshot_fingerprint=v_server_fingerprint
   where singleton=true returning epoch into v_epoch;
  v_result := jsonb_build_object(
    'ok',true,'replayed',false,'idempotencyKey',p_idempotency_key,
    'snapshotFingerprint',p_snapshot_fingerprint,'serverSnapshotFingerprint',v_server_fingerprint,'rollbackSnapshotId',v_rollback_id,
    'restoreEpoch',v_epoch,'manifest',p_manifest,'serverRelationshipHash',v_actual_relationship_hash,
    'timingsMs',v_phase_timings
  );
  update public.erp_cloud_restore_requests set status='completed',rollback_snapshot_id=v_rollback_id,
    canonical_result=v_result,completed_at=now()
   where actor_id=v_actor and idempotency_key=p_idempotency_key;
  v_phase_ms := (extract(epoch from clock_timestamp() - v_phase_started_at) * 1000)::bigint;
  v_phase_timings := v_phase_timings || jsonb_build_object('epochIdempotency', v_phase_ms);
  v_phase_timings := v_phase_timings || jsonb_build_object(
    'total', (extract(epoch from clock_timestamp() - v_started_at) * 1000)::bigint
  );
  v_result := jsonb_set(v_result, '{timingsMs}', v_phase_timings, true);
  update public.erp_cloud_restore_requests
     set canonical_result=v_result
   where actor_id=v_actor and idempotency_key=p_idempotency_key;
  raise log 'CLOUD_RESTORE_TIMING phase=epoch_idempotency event=complete duration_ms=% total_ms=%',
    v_phase_ms, v_phase_timings->>'total';
  return v_result;
exception
  when query_canceled then
    raise log 'CLOUD_RESTORE_TIMING phase=failure failed_phase=% classification=statement_timeout sqlstate=% total_ms=%',
      v_current_phase, sqlstate, (extract(epoch from clock_timestamp() - v_started_at) * 1000)::bigint;
    raise;
  when others then
    raise log 'CLOUD_RESTORE_TIMING phase=failure failed_phase=% classification=error sqlstate=% total_ms=%',
      v_current_phase, sqlstate, (extract(epoch from clock_timestamp() - v_started_at) * 1000)::bigint;
    raise;
end;
$function$

public.erp_cloud_restore_insert_staged_r.definition:
CREATE OR REPLACE FUNCTION public.erp_cloud_restore_insert_staged_rows(p_table regclass, p_proof_id uuid, p_resource text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_columns text; v_count bigint; v_expected bigint;
BEGIN
  IF p_resource<>ALL(ARRAY['inventory_items','product_groups','product_categories','product_variants','bundle_components','purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items','japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches','waca_orders','waca_order_items','waca_mappings','waca_master_links','waca_import_batches','waca_cutover_audit','waca_state']) OR p_table IS DISTINCT FROM format('public.%I',p_resource)::regclass THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_TABLE_NOT_ALLOWED';
  END IF;
  SELECT prepared_columns->>p_resource INTO v_columns FROM public.erp_cloud_restore_candidate_proofs WHERE proof_id=p_proof_id;
  IF v_columns IS NULL THEN RETURN 0; END IF;
  EXECUTE format('insert into %s (%s) select %s from public.%I where restore_proof_id=$1',p_table,v_columns,v_columns,
    'erp_restore_stage_'||p_resource) USING p_proof_id;
  GET DIAGNOSTICS v_count=ROW_COUNT;
  IF p_resource='outbound_shipments' THEN
    UPDATE public.outbound_shipments t SET status_changed_at=s.status_changed_at
      FROM public.erp_restore_stage_outbound_shipments s WHERE s.restore_proof_id=p_proof_id AND t.id=s.id;
    GET DIAGNOSTICS v_expected=ROW_COUNT;
    IF v_expected<>v_count OR EXISTS(SELECT 1 FROM public.erp_restore_stage_outbound_shipments s
      LEFT JOIN public.outbound_shipments t USING(id) WHERE s.restore_proof_id=p_proof_id
      AND (t.id IS NULL OR t.status_changed_at IS DISTINCT FROM s.status_changed_at)) THEN
      RAISE EXCEPTION USING errcode='55000',message='CLOUD_RESTORE_OUTBOUND_TIMESTAMP_MISMATCH';
    END IF;
  END IF;
  RETURN v_count;
END;
$function$

public.erp_cloud_restore_validate_portab.definition:
CREATE OR REPLACE FUNCTION public.erp_cloud_restore_validate_portability(p_snapshot jsonb, p_manifest jsonb, p_target_project_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_policy jsonb;
  v_counts jsonb;
  v_table text;
  v_table_oid oid;
  v_column_attnum smallint;
  v_request_headers jsonb;
  v_request_host text;
  v_total_transformed bigint := 0;
  v_external_reference_count integer := 0;
  v_tables constant text[] := array[
    'inventory_items','product_groups','product_categories','product_variants','bundle_components',
    'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
    'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
    'waca_orders','waca_order_items','waca_mappings','waca_master_links',
    'waca_import_batches','waca_cutover_audit','waca_state'
  ];
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'AUTHENTICATION_REQUIRED';
  end if;
  if not public.is_owner(v_actor) then
    raise exception using errcode = '42501', message = 'CLOUD_RESTORE_OWNER_REQUIRED';
  end if;
  if p_target_project_ref is distinct from 'rhfdjsklfrgpoqsaqpkn' then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_TARGET_MISMATCH';
  end if;

  begin
    v_request_headers := nullif(current_setting('request.headers', true), '')::jsonb;
  exception when others then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_TARGET_MISMATCH';
  end;
  v_request_host := lower(split_part(coalesce(v_request_headers->>'host', ''), ':', 1));
  if split_part(v_request_host, '.', 1) is distinct from p_target_project_ref then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_TARGET_MISMATCH';
  end if;

  if jsonb_typeof(p_snapshot) is distinct from 'object'
     or jsonb_typeof(p_manifest) is distinct from 'object'
     or jsonb_typeof(p_manifest->'portability') is distinct from 'object' then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_POLICY_INVALID';
  end if;
  v_policy := p_manifest->'portability';
  v_counts := v_policy->'transformedCounts';
  if v_policy->>'policyVersion' is distinct from 'cross-environment-audit-null-v1'
     or v_policy->>'mode' is distinct from 'cross-environment'
     or v_policy->>'targetProjectRef' is distinct from p_target_project_ref
     or coalesce(v_policy->>'sourceFileSha256', '') !~ '^[0-9a-f]{64}$'
     or coalesce(v_policy->>'sourceSnapshotFingerprint', '') !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(v_counts) is distinct from 'object'
     or jsonb_typeof(v_policy->'totalTransformedRows') is distinct from 'number'
     or (v_policy->>'totalTransformedRows') !~ '^[0-9]+$'
     or exists (
       select 1 from jsonb_object_keys(v_policy) key
        where key not in (
          'policyVersion','mode','targetProjectRef','sourceFileSha256',
          'sourceSnapshotFingerprint','transformedCounts','totalTransformedRows'
        )
     ) then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_POLICY_INVALID';
  end if;

  foreach v_table in array v_tables loop
    if jsonb_typeof(p_snapshot->v_table) is distinct from 'array'
       or not (v_counts ? v_table)
       or jsonb_typeof(v_counts->v_table) is distinct from 'number'
       or (v_counts->>v_table) !~ '^[0-9]+$'
       or (v_counts->>v_table)::bigint > jsonb_array_length(p_snapshot->v_table) then
      raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_POLICY_INVALID:' || v_table;
    end if;
    v_total_transformed := v_total_transformed + (v_counts->>v_table)::bigint;

    select c.oid, a.attnum
      into v_table_oid, v_column_attnum
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      join pg_attribute a on a.attrelid = c.oid
     where n.nspname = 'public'
       and c.relname = v_table
       and c.relkind in ('r','p')
       and a.attname = 'updated_by'
       and a.attnum > 0
       and not a.attisdropped
       and not a.attnotnull
       and format_type(a.atttypid, a.atttypmod) = 'uuid';

    if v_table_oid is null
       or not exists (
         select 1
           from pg_constraint fk
           join pg_class parent on parent.oid = fk.confrelid
           join pg_namespace parent_ns on parent_ns.oid = parent.relnamespace
          where fk.contype = 'f'
            and fk.conrelid = v_table_oid
            and fk.conkey = array[v_column_attnum]::smallint[]
            and parent_ns.nspname = 'auth'
            and parent.relname = 'users'
            and fk.confkey = array[(
              select attnum from pg_attribute
               where attrelid = fk.confrelid and attname = 'id' and attnum > 0 and not attisdropped
            )]::smallint[]
            and fk.confdeltype = 'n'
            and fk.convalidated
       ) then
      raise exception using errcode = '55000', message = 'CLOUD_RESTORE_PORTABILITY_SCHEMA_MISMATCH:' || v_table || '.updated_by';
    end if;

    if exists (
      select 1
        from jsonb_array_elements(p_snapshot->v_table) row_value
       where not (row_value ? 'updated_by')
          or jsonb_typeof(row_value->'updated_by') is distinct from 'null'
    ) then
      raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_AUDIT_VALUE_NOT_NULL:' || v_table;
    end if;
  end loop;

  if (select count(*) from jsonb_object_keys(v_counts)) <> cardinality(v_tables)
     or v_total_transformed <> (v_policy->>'totalTransformedRows')::bigint then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_POLICY_INVALID';
  end if;

  select count(*)
    into v_external_reference_count
    from pg_constraint fk
    join pg_class child on child.oid = fk.conrelid
    join pg_namespace child_ns on child_ns.oid = child.relnamespace
    join pg_class parent on parent.oid = fk.confrelid
    join pg_namespace parent_ns on parent_ns.oid = parent.relnamespace
   where fk.contype = 'f'
     and child_ns.nspname = 'public'
     and child.relname = any(v_tables)
     and not (parent_ns.nspname = 'public' and parent.relname = any(v_tables));

  if v_external_reference_count <> cardinality(v_tables)
     or exists (
       select 1
         from pg_constraint fk
         join pg_class child on child.oid = fk.conrelid
         join pg_namespace child_ns on child_ns.oid = child.relnamespace
         join pg_class parent on parent.oid = fk.confrelid
         join pg_namespace parent_ns on parent_ns.oid = parent.relnamespace
         join lateral unnest(fk.conkey, fk.confkey) with ordinality key_pair(child_attnum,parent_attnum,ordinality) on true
         join pg_attribute child_column on child_column.attrelid = fk.conrelid and child_column.attnum = key_pair.child_attnum
         join pg_attribute parent_column on parent_column.attrelid = fk.confrelid and parent_column.attnum = key_pair.parent_attnum
        where fk.contype = 'f'
          and child_ns.nspname = 'public'
          and child.relname = any(v_tables)
          and not (parent_ns.nspname = 'public' and parent.relname = any(v_tables))
          and not (
            cardinality(fk.conkey) = 1
            and child_column.attname = 'updated_by'
            and parent_ns.nspname = 'auth'
            and parent.relname = 'users'
            and parent_column.attname = 'id'
            and fk.confdeltype = 'n'
            and fk.convalidated
          )
     ) then
    raise exception using errcode = '55000', message = 'CLOUD_RESTORE_PORTABILITY_EXTERNAL_REFERENCE_BLOCKED';
  end if;

  return jsonb_build_object(
    'ok', true,
    'policyVersion', v_policy->>'policyVersion',
    'targetProjectRef', p_target_project_ref,
    'policyFingerprint', encode(digest(convert_to(v_policy::text, 'UTF8'), 'sha256'), 'hex'),
    'externalReferenceCount', v_external_reference_count
  );
end;
$function$

public.erp_store_waca_recognition_contin.definition:
CREATE OR REPLACE FUNCTION public.erp_store_waca_recognition_continuity(p_variant uuid, p_epoch bigint, p_keys jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v public.product_variants%rowtype; n bigint;
begin
  select * into v from public.product_variants where id=p_variant;
  insert into public.waca_cutover_audit(product_variant_id,payload,updated_by)
  values(v.id,jsonb_build_object('productVariantId',v.id,'sku',v.myacg_item_code,'productTitle',v.product_title,
    'variantTitle',v.variant_name,'legacyWacaQuantity',v.waca_auto_quantity+v.waca_manual_adjustment,
    'legacyAutoQuantity',v.waca_auto_quantity,'unverifiedPreCutoverManualQuantity',v.waca_manual_adjustment,
    'newOrderDerivedQuantity',v.waca_auto_quantity,'difference',0,'cutoverAt',now()),auth.uid())
    on conflict(product_variant_id) do nothing;
  update public.waca_cutover_audit set payload=payload||jsonb_build_object('recognitionContinuity',jsonb_build_object(
    'epoch',p_epoch,'version',v.version,'auto',v.waca_auto_quantity,'manual',v.waca_manual_adjustment,'itemKeys',p_keys)),
    updated_at=now(),updated_by=auth.uid() where product_variant_id=p_variant;
  get diagnostics n=row_count;
  if n<>1 then raise exception using errcode='23514',message='WACA_RECOGNITION_PROOF_UPDATE_MISMATCH'; end if;
end;
$function$

public.erp_commit_waca_counted_snapshot_.definition:
CREATE OR REPLACE FUNCTION public.erp_commit_waca_counted_snapshot_v074(p_snapshot jsonb, p_expected_revision bigint, p_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_revision bigint; v_mode text; v_payload jsonb; v_driven boolean; v_first boolean;
  v_epoch bigint; v_restored_at timestamptz; v_epoch_fp text; v_transition jsonb;
  v_row jsonb; v_overwrite uuid[] := '{}'; v_id uuid; v_bad text;
  v_effective integer; v_total integer; v_unmatched integer; v_status text;
  v_state_rows bigint;
  v_now timestamptz := now();
  v_checked_at text := to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
begin
  if v_actor is null or not public.is_owner(v_actor) then
    raise exception using errcode='42501',message='WACA_OWNER_REQUIRED';
  end if;
  if jsonb_typeof(p_plan) is distinct from 'object' or p_plan->>'contract' is distinct from 'waca-counted-import-v1'
     or jsonb_typeof(p_plan->'overwriteVariantIds') is distinct from 'array'
     or jsonb_typeof(p_plan->'expectedDisplay') is distinct from 'object'
     or (p_plan->>'restoreEpoch') !~ '^[0-9]+$' then
    raise exception using errcode='22023',message='WACA_COUNTED_PLAN_INVALID';
  end if;
  if jsonb_typeof(p_snapshot) is distinct from 'object' or jsonb_typeof(p_snapshot->'items') is distinct from 'array' then
    raise exception using errcode='22023',message='WACA_SNAPSHOT_INVALID';
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) then
    raise exception using errcode='55006',message='CLOUD_RESTORE_MAINTENANCE_LOCKED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('erp-waca-ledger-import',0));

  select revision,mode,payload into v_revision,v_mode,v_payload from public.waca_state for update;
  v_revision := coalesce(v_revision,0); v_mode := coalesce(v_mode,'LEGACY_QUANTITY_ACTIVE');
  v_payload := coalesce(v_payload,'{}'::jsonb);
  if v_revision <> p_expected_revision then
    raise exception using errcode='40001',message='WACA_STALE_REVISION';
  end if;
  select e.epoch,e.restored_at,e.snapshot_fingerprint into v_epoch,v_restored_at,v_epoch_fp
    from public.erp_cloud_restore_epoch e where e.singleton;
  if (p_plan->>'restoreEpoch')::bigint is distinct from coalesce(v_epoch,0) then
    raise exception using errcode='40001',message='WACA_RESTORE_EPOCH_CHANGED';
  end if;
  v_driven := v_mode = 'ORDER_DRIVEN_ACTIVE';
  v_first := not v_driven;

  -- Every submitted item must declare a valid counted quantity.
  select coalesce(value->>'key','?') into v_bad from jsonb_array_elements(p_snapshot->'items')
   where coalesce(value->>'countedQuantity','') !~ '^[0-9]+$' limit 1;
  if found then raise exception using errcode='22023',message='WACA_COUNTED_QUANTITY_INVALID',detail=v_bad; end if;

  for v_row in select value from jsonb_array_elements(p_plan->'overwriteVariantIds') loop
    v_id := public.erp_waca_variant_id(v_row#>>'{}');
    v_overwrite := array_append(v_overwrite, v_id);
  end loop;

  create temporary table _waca_counted_before on commit drop as
    select i.product_variant_id variant_id,
      sum(case when o.status in ('處理中','完成付款') then i.quantity else 0 end)::integer q,
      sum(coalesce((i.payload->>'countedQuantity')::integer,
        case when v_driven and o.status in ('處理中','完成付款') then i.quantity else 0 end))::integer c
    from public.waca_order_items i join public.waca_orders o on o.id=i.order_id
    where i.product_variant_id is not null group by i.product_variant_id;
  create temporary table _waca_variant_before on commit drop as
    select v.id, v.waca_auto_quantity auto_q, v.waca_manual_adjustment manual_q,
      v.myacg_item_code, v.product_title, v.variant_name, v.local_id
    from public.product_variants v;

  -- Ledger upsert through the existing, unchanged RPC (no quantity update, mode preserved).
  perform public.erp_commit_waca_snapshot(p_snapshot, p_expected_revision, false);

  create temporary table _waca_counted_after on commit drop as
    select i.product_variant_id variant_id,
      sum(case when o.status in ('處理中','完成付款') then i.quantity else 0 end)::integer q,
      sum(coalesce((i.payload->>'countedQuantity')::integer,
        case when v_driven and o.status in ('處理中','完成付款') then i.quantity else 0 end))::integer c,
      bool_and(coalesce((i.payload->>'countedQuantity')::integer, -1)
        = case when o.status in ('處理中','完成付款') then i.quantity else 0 end) fully_counted
    from public.waca_order_items i join public.waca_orders o on o.id=i.order_id
    where i.product_variant_id is not null group by i.product_variant_id;

  if exists(select 1 from unnest(v_overwrite) w left join _waca_counted_after a on a.variant_id=w
            where a.variant_id is not null and not a.fully_counted) then
    raise exception using errcode='23000',message='WACA_OVERWRITE_NOT_FULLY_COUNTED';
  end if;

  create temporary table _waca_counted_plan on commit drop as
    select b.id variant_id, b.auto_q, b.manual_q, b.auto_q+b.manual_q display_before,
      coalesce(a.q,0) auto_after,
      case when b.id = any(v_overwrite) then 0
        else b.auto_q+b.manual_q+coalesce(a.c,0)-coalesce(cb.c,0)-coalesce(a.q,0) end manual_after
    from _waca_variant_before b
    left join _waca_counted_after a on a.variant_id=b.id
    left join _waca_counted_before cb on cb.variant_id=b.id;

  -- A counted import can never produce a negative WACA demand: the Purchase Records clamp at 0 must not
  -- be able to hide an anomaly written here (history >= 0 and every countedQuantity >= 0 by construction).
  select p.variant_id::text into v_bad from _waca_counted_plan p
   where (p.auto_after <> p.auto_q or p.manual_after <> p.manual_q) and p.auto_after + p.manual_after < 0 limit 1;
  if found then raise exception using errcode='23514',message='WACA_COUNTED_NEGATIVE_DISPLAY',detail=v_bad; end if;

  -- Fail closed unless every changing variant matches the reviewed preview exactly.
  select p.variant_id::text into v_bad from _waca_counted_plan p
   where (p.auto_after <> p.auto_q or p.manual_after <> p.manual_q or p.variant_id = any(v_overwrite))
     and (p_plan->'expectedDisplay'->(p.variant_id::text) is null
       or (p_plan->'expectedDisplay'->(p.variant_id::text)->>'before')::integer is distinct from p.display_before
       or (p_plan->'expectedDisplay'->(p.variant_id::text)->>'after')::integer is distinct from p.auto_after+p.manual_after)
   limit 1;
  if found then raise exception using errcode='40001',message='WACA_COUNTED_PREVIEW_MISMATCH',detail=v_bad; end if;

  if v_first then
    insert into public.waca_cutover_audit(product_variant_id,payload,updated_by)
    select p.variant_id,jsonb_build_object(
      'productVariantId',coalesce(v.local_id,p.variant_id::text),
      'sku',v.myacg_item_code,'productTitle',v.product_title,'variantTitle',v.variant_name,
      'legacyWacaQuantity',p.display_before,'legacyAutoQuantity',p.auto_q,
      'unverifiedPreCutoverManualQuantity',p.manual_q,
      'newOrderDerivedQuantity',p.auto_after,'difference',p.auto_after-p.display_before,
      'cutoverAt',v_checked_at,'transition','counted-v1'),v_actor
    from _waca_counted_plan p join _waca_variant_before v on v.id=p.variant_id
    on conflict(product_variant_id) do nothing;
  end if;

  update public.product_variants v set waca_auto_quantity=p.auto_after, waca_manual_adjustment=p.manual_after,
    updated_at=v_now, updated_by=v_actor, version=v.version+1
  from _waca_counted_plan p
  where p.variant_id=v.id and (p.auto_after<>p.auto_q or p.manual_after<>p.manual_q);

  if exists(select 1 from public.product_variants v left join (
      select i.product_variant_id,sum(i.quantity)::integer quantity
      from public.waca_order_items i join public.waca_orders o on o.id=i.order_id
      where i.product_variant_id is not null and o.status in ('處理中','完成付款')
      group by i.product_variant_id) q on q.product_variant_id=v.id
    where v.waca_auto_quantity is distinct from coalesce(q.quantity,0)) then
    raise exception using errcode='23000',message='WACA_RECONCILIATION_FAILED';
  end if;

  select coalesce(sum(i.quantity),0)::integer into v_effective
    from public.waca_order_items i join public.waca_orders o on o.id=i.order_id where o.status in ('處理中','完成付款');
  select count(distinct feature)::integer into v_total from public.waca_order_items where product_variant_id is not null;
  select count(distinct i.feature)::integer into v_unmatched
    from public.waca_order_items i join public.waca_orders o on o.id=i.order_id
    where i.product_variant_id is null and i.quantity>0 and o.status in ('處理中','完成付款');
  v_status := case when v_unmatched=0 then 'PASS' else 'FAIL' end;
  update public.waca_import_batches b set
    payload=b.payload || jsonb_build_object('reconciliation',jsonb_build_object(
      'status',v_status,'passed',v_total,'total',v_total+v_unmatched,'effectiveQuantity',v_effective,'checkedAt',v_checked_at)),
    updated_at=v_now
    where b.batch_key in (select value->>'id' from jsonb_array_elements(coalesce(p_snapshot->'batches','[]'::jsonb)));

  v_transition := case when v_first then jsonb_build_object(
      'contract','waca-counted-import-v1','restoreEpoch',coalesce(v_epoch,0),
      'baselineAt',to_char(coalesce(v_restored_at,v_now) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      'restoreSnapshotFingerprint',v_epoch_fp,'previousMode',v_mode,'establishedAt',v_checked_at)
    else v_payload->'transition' end;
  update public.waca_state set mode='ORDER_DRIVEN_ACTIVE',
    payload=jsonb_build_object('mode','ORDER_DRIVEN_ACTIVE','updatedAt',v_checked_at,
      'sourceBackupFormatVersion',p_snapshot->'cutoverState'->'sourceBackupFormatVersion')
      || case when v_transition is null then '{}'::jsonb else jsonb_build_object('transition',v_transition) end,
    updated_at=v_now, updated_by=v_actor
    where id='00000000-0000-4000-8000-000000000001'::uuid and revision=v_revision+1;
  get diagnostics v_state_rows = row_count;
  if v_state_rows <> 1 then
    raise exception using errcode='23514',message='WACA_COUNTED_STATE_UPDATE_MISMATCH';
  end if;

  return jsonb_build_object('revision',v_revision+1,'reconciliation',v_status,'effectiveQuantity',v_effective,
    'unmatchedFeatures',v_unmatched,'transitionEstablished',v_first,'transition',v_transition);
end;
$function$

public.erp_cloud_restore_build_effective.definition:
CREATE OR REPLACE FUNCTION public.erp_cloud_restore_build_effective_snapshot(p_source_snapshot jsonb, p_manifest jsonb, p_restore_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_effective jsonb := p_source_snapshot;
  v_policy jsonb;
  v_counts jsonb;
  v_table text;
  v_rows jsonb;
  v_actual_transformed bigint;
  v_total_transformed bigint := 0;
  v_tables constant text[] := array[
    'inventory_items','product_groups','product_categories','product_variants','bundle_components',
    'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
    'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
    'waca_orders','waca_order_items','waca_mappings','waca_master_links',
    'waca_import_batches','waca_cutover_audit','waca_state'
  ];
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'AUTHENTICATION_REQUIRED';
  end if;
  if not public.is_owner(v_actor) then
    raise exception using errcode = '42501', message = 'CLOUD_RESTORE_OWNER_REQUIRED';
  end if;
  if jsonb_typeof(p_source_snapshot) is distinct from 'object'
     or jsonb_typeof(p_manifest) is distinct from 'object' then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_EFFECTIVE_SOURCE_INVALID';
  end if;

  if p_restore_mode = 'strict' then
    if p_manifest ? 'portability' then
      raise exception using errcode = '22023', message = 'CLOUD_RESTORE_STRICT_POLICY_MISMATCH';
    end if;
    return p_source_snapshot;
  end if;
  if p_restore_mode is distinct from 'cross-environment' then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_MODE_INVALID';
  end if;

  v_policy := p_manifest->'portability';
  v_counts := v_policy->'transformedCounts';
  if jsonb_typeof(v_policy) is distinct from 'object'
     or v_policy->>'policyVersion' is distinct from 'cross-environment-audit-null-v1'
     or v_policy->>'mode' is distinct from 'cross-environment'
     or v_policy->>'targetProjectRef' is distinct from 'rhfdjsklfrgpoqsaqpkn'
     or jsonb_typeof(v_counts) is distinct from 'object'
     or jsonb_typeof(v_policy->'totalTransformedRows') is distinct from 'number'
     or (v_policy->>'totalTransformedRows') !~ '^[0-9]+$' then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_POLICY_INVALID';
  end if;

  foreach v_table in array v_tables loop
    if jsonb_typeof(p_source_snapshot->v_table) is distinct from 'array'
       or not (v_counts ? v_table)
       or jsonb_typeof(v_counts->v_table) is distinct from 'number'
       or (v_counts->>v_table) !~ '^[0-9]+$' then
      raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_COVERAGE_INVALID:' || v_table;
    end if;

    -- Count transformed values, validate row shape, and materialize the effective
    -- table in one traversal. 035 performed separate count and aggregation scans.
    select
      count(*) filter (
        where row_value ? 'updated_by'
          and jsonb_typeof(row_value->'updated_by') is distinct from 'null'
      ),
      coalesce(
        jsonb_agg(row_value || jsonb_build_object('updated_by', null) order by ordinality),
        '[]'::jsonb
      )
      into v_actual_transformed, v_rows
      from jsonb_array_elements(p_source_snapshot->v_table)
           with ordinality source_row(row_value, ordinality)
     where case
       when jsonb_typeof(row_value) = 'object' then true
       else public.erp_cloud_restore_reject_invalid_portable_row(v_table)
     end;

    if v_actual_transformed <> (v_counts->>v_table)::bigint then
      raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_TRANSFORM_COUNT_MISMATCH:' || v_table;
    end if;
    v_total_transformed := v_total_transformed + v_actual_transformed;
    v_effective := jsonb_set(v_effective, array[v_table], v_rows, false);
  end loop;

  if (select count(*) from jsonb_object_keys(v_counts)) <> cardinality(v_tables)
     or v_total_transformed <> (v_policy->>'totalTransformedRows')::bigint then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_PORTABILITY_COVERAGE_INVALID';
  end if;

  -- Final schema/external-reference/NULL-policy validation remains authoritative
  -- in erp_cloud_restore_idempotency_fingerprint(), before the first DELETE.
  return v_effective;
end;
$function$

public.erp_restore_staged_cloud_snapshot.definition:
CREATE OR REPLACE FUNCTION public.erp_restore_staged_cloud_snapshot(p_idempotency_key uuid, p_proof_id uuid, p_snapshot_fingerprint text, p_manifest jsonb, p_source_environment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();
  v_actor_key text;
  v_proof public.erp_cloud_restore_candidate_proofs%rowtype;
  v_existing public.erp_cloud_restore_requests%rowtype;
  v_rollback_id uuid;
  v_before jsonb;
  v_source_generation bigint;
  v_source_epoch bigint;
  v_before_fingerprint text;
  v_table text;
  v_expected_profile jsonb;
  v_actual_profile jsonb;
  v_actual_relationship_hash text;
  v_epoch bigint;
  v_result jsonb;
  v_live_waca jsonb;
  v_started_at timestamptz:=clock_timestamp();
  v_phase_started_at timestamptz:=clock_timestamp();
  v_phase_timings jsonb:='{}'::jsonb;
  v_phase text:='auth';
  v_phase_ms bigint;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION USING errcode='42501',message='AUTHENTICATION_REQUIRED'; END IF;
  IF NOT public.is_owner(v_actor) THEN RAISE EXCEPTION USING errcode='42501',message='CLOUD_RESTORE_OWNER_REQUIRED'; END IF;
  v_actor_key:=encode(extensions.digest(v_actor::text,'sha256'),'hex');
  SELECT * INTO v_proof FROM public.erp_cloud_restore_candidate_proofs
   WHERE proof_id=p_proof_id AND actor_key=v_actor_key FOR UPDATE;
  IF NOT FOUND OR v_proof.expires_at<=clock_timestamp() THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_NOT_FOUND';
  END IF;
  IF v_proof.effective_fingerprint IS DISTINCT FROM p_snapshot_fingerprint
     OR v_proof.manifest IS DISTINCT FROM p_manifest
     OR v_proof.prepared_payload_hash IS NULL
     OR v_proof.expected_relationship_hash IS NULL
     OR (SELECT coalesce(sum(row_count),0) FROM public.erp_cloud_restore_prepared_chunks WHERE proof_id=p_proof_id)
        IS DISTINCT FROM v_proof.prepared_row_count THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_STAGED_PROOF_MISMATCH';
  END IF;
  v_phase_ms:=(extract(epoch FROM clock_timestamp()-v_phase_started_at)*1000)::bigint;
  v_phase_timings:=v_phase_timings||jsonb_build_object('auth',v_phase_ms);

  v_phase:='lock_idempotency';v_phase_started_at:=clock_timestamp();
  IF NOT pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) THEN
    RAISE EXCEPTION USING errcode='55006',message='CLOUD_RESTORE_LOCK_CONFLICT';
  END IF;
  INSERT INTO public.erp_cloud_restore_requests(actor_id,idempotency_key,snapshot_fingerprint,status)
  VALUES(v_actor,p_idempotency_key,v_proof.prepared_payload_hash,'processing') ON CONFLICT(actor_id,idempotency_key) DO NOTHING;
  SELECT * INTO v_existing FROM public.erp_cloud_restore_requests
   WHERE actor_id=v_actor AND idempotency_key=p_idempotency_key FOR UPDATE;
  IF v_existing.snapshot_fingerprint<>v_proof.prepared_payload_hash THEN
    RAISE EXCEPTION USING errcode='22023',message='RESTORE_IDEMPOTENCY_PAYLOAD_MISMATCH';
  END IF;
  IF v_existing.status='completed' THEN RETURN v_existing.canonical_result||jsonb_build_object('replayed',true); END IF;
  v_phase_ms:=(extract(epoch FROM clock_timestamp()-v_phase_started_at)*1000)::bigint;
  v_phase_timings:=v_phase_timings||jsonb_build_object('lockIdempotency',v_phase_ms);

  v_phase:='source_generation';v_phase_started_at:=clock_timestamp();
  SELECT generation INTO STRICT v_source_generation FROM public.erp_restore_business_generation WHERE singleton FOR UPDATE;
  SELECT epoch INTO STRICT v_source_epoch FROM public.erp_cloud_restore_epoch WHERE singleton;
  IF v_proof.source_generation IS NULL OR v_proof.source_restore_epoch IS NULL
     OR v_source_generation IS DISTINCT FROM v_proof.source_generation
     OR v_source_epoch IS DISTINCT FROM v_proof.source_restore_epoch THEN
    RAISE EXCEPTION USING errcode='55000',message='STALE_RESTORE_PREPARE';
  END IF;
  -- This is an immutable SOURCE GENERATION receipt, NOT a rollback backup.
  -- Full recovery artifacts are exported outside execute. PostgreSQL owns rollback.
  v_before:=jsonb_build_object('schemaVersion','restore-source-generation-v1',
    'restoreEpoch',v_source_epoch,'businessGeneration',v_source_generation,
    'proofId',p_proof_id,'targetFingerprint',p_snapshot_fingerprint);
  v_before_fingerprint:=encode(extensions.digest(convert_to(v_before::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.erp_cloud_restore_snapshots(actor_id,source_environment,snapshot_fingerprint,manifest,snapshot)
  VALUES(v_actor,'restore-source-generation',v_before_fingerprint,
    jsonb_build_object('evidenceKind','SOURCE_GENERATION','atomicRollback','POSTGRESQL_TRANSACTION'),v_before)
  RETURNING id INTO v_rollback_id;
  v_phase_timings:=v_phase_timings||jsonb_build_object('beforeSnapshot',0,'sourceGeneration',
    (extract(epoch FROM clock_timestamp()-v_phase_started_at)*1000)::bigint);

  PERFORM set_config('erp.cloud_restore_active','on',true);
  v_phase:='delete';v_phase_started_at:=clock_timestamp();
  DELETE FROM public.outbound_shipment_items WHERE id IS NOT NULL;
  DELETE FROM public.outbound_shipments WHERE id IS NOT NULL;
  DELETE FROM public.japan_package_items WHERE id IS NOT NULL;
  DELETE FROM public.japan_packages WHERE id IS NOT NULL;
  DELETE FROM public.private_order_items WHERE id IS NOT NULL;
  DELETE FROM public.purchase_batch_items WHERE id IS NOT NULL;
  DELETE FROM public.sales_order_items WHERE id IS NOT NULL;
  DELETE FROM public.bundle_components WHERE id IS NOT NULL;
  DELETE FROM public.private_orders WHERE id IS NOT NULL;
  DELETE FROM public.purchase_batches WHERE id IS NOT NULL;
  DELETE FROM public.dashboard_category_images WHERE id IS NOT NULL;
  DELETE FROM public.waca_order_items WHERE id IS NOT NULL;
  DELETE FROM public.waca_mappings WHERE id IS NOT NULL;
  DELETE FROM public.waca_master_links WHERE id IS NOT NULL;
  DELETE FROM public.waca_cutover_audit WHERE id IS NOT NULL;
  DELETE FROM public.waca_import_batches WHERE id IS NOT NULL;
  DELETE FROM public.waca_state WHERE id IS NOT NULL;
  DELETE FROM public.waca_orders WHERE id IS NOT NULL;
  DELETE FROM public.import_batches WHERE id IS NOT NULL;
  DELETE FROM public.product_variants WHERE id IS NOT NULL;
  DELETE FROM public.product_categories WHERE id IS NOT NULL;
  DELETE FROM public.sales_orders WHERE id IS NOT NULL;
  DELETE FROM public.product_groups WHERE id IS NOT NULL;
  DELETE FROM public.inventory_items WHERE id IS NOT NULL;
  v_phase_ms:=(extract(epoch FROM clock_timestamp()-v_phase_started_at)*1000)::bigint;
  v_phase_timings:=v_phase_timings||jsonb_build_object('delete',v_phase_ms);

  v_phase:='insert';v_phase_started_at:=clock_timestamp();
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.inventory_items',p_proof_id,'inventory_items');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.product_groups',p_proof_id,'product_groups');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.product_categories',p_proof_id,'product_categories');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.product_variants',p_proof_id,'product_variants');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.bundle_components',p_proof_id,'bundle_components');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.purchase_batches',p_proof_id,'purchase_batches');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.purchase_batch_items',p_proof_id,'purchase_batch_items');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.private_orders',p_proof_id,'private_orders');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.private_order_items',p_proof_id,'private_order_items');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.sales_orders',p_proof_id,'sales_orders');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.sales_order_items',p_proof_id,'sales_order_items');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.japan_packages',p_proof_id,'japan_packages');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.japan_package_items',p_proof_id,'japan_package_items');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.outbound_shipments',p_proof_id,'outbound_shipments');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.outbound_shipment_items',p_proof_id,'outbound_shipment_items');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.dashboard_category_images',p_proof_id,'dashboard_category_images');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.import_batches',p_proof_id,'import_batches');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.waca_orders',p_proof_id,'waca_orders');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.waca_order_items',p_proof_id,'waca_order_items');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.waca_mappings',p_proof_id,'waca_mappings');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.waca_master_links',p_proof_id,'waca_master_links');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.waca_import_batches',p_proof_id,'waca_import_batches');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.waca_cutover_audit',p_proof_id,'waca_cutover_audit');
  PERFORM public.erp_cloud_restore_insert_staged_rows('public.waca_state',p_proof_id,'waca_state');
  PERFORM public.erp_cloud_restore_recompute_waca_quantities();
  PERFORM public.erp_cloud_restore_validate_live_waca();
  v_phase_ms:=(extract(epoch FROM clock_timestamp()-v_phase_started_at)*1000)::bigint;
  v_phase_timings:=v_phase_timings||jsonb_build_object('insert',v_phase_ms);

  v_phase:='integrity';v_phase_started_at:=clock_timestamp();
  FOREACH v_table IN ARRAY ARRAY[
    'inventory_items','product_groups','product_categories','product_variants','bundle_components',
    'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
    'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
    'waca_orders','waca_order_items','waca_mappings','waca_master_links','waca_import_batches','waca_cutover_audit','waca_state'
  ] LOOP
    v_actual_profile:=public.erp_cloud_restore_table_profile(format('public.%I',v_table)::regclass,NULL::jsonb);
    v_expected_profile:=v_proof.expected_profiles->v_table;
    IF (v_actual_profile->>'count')::bigint IS DISTINCT FROM (v_expected_profile->>'count')::bigint THEN
      RAISE EXCEPTION USING errcode='23000',message='CLOUD_RESTORE_POST_INTEGRITY_COUNT_MISMATCH:'||v_table;
    END IF;
    IF v_actual_profile->>'identityHash' IS DISTINCT FROM v_expected_profile->>'identityHash' THEN
      RAISE EXCEPTION USING errcode='23000',message='CLOUD_RESTORE_POST_INTEGRITY_IDENTITY_HASH_MISMATCH:'||v_table;
    END IF;
  END LOOP;
  IF EXISTS (
    SELECT 1 FROM public.product_variants v LEFT JOIN public.product_groups g ON g.id=v.product_group_id WHERE g.id IS NULL
    UNION ALL SELECT 1 FROM public.purchase_batch_items i LEFT JOIN public.purchase_batches b ON b.id=i.purchase_batch_id WHERE b.id IS NULL
    UNION ALL SELECT 1 FROM public.private_order_items i LEFT JOIN public.private_orders o ON o.id=i.private_order_id WHERE o.id IS NULL
    UNION ALL SELECT 1 FROM public.sales_order_items i LEFT JOIN public.sales_orders o ON o.id=i.order_id WHERE o.id IS NULL
    UNION ALL SELECT 1 FROM public.japan_package_items i LEFT JOIN public.japan_packages p ON p.id=i.japan_package_id WHERE p.id IS NULL
    UNION ALL SELECT 1 FROM public.outbound_shipment_items i LEFT JOIN public.outbound_shipments s ON s.id=i.outbound_shipment_id WHERE s.id IS NULL
  ) THEN RAISE EXCEPTION USING errcode='23503',message='CLOUD_RESTORE_POST_INTEGRITY_ORPHAN'; END IF;
  v_actual_relationship_hash:=public.erp_cloud_restore_live_relationship_hash();
  IF v_actual_relationship_hash<>v_proof.expected_relationship_hash THEN
    RAISE EXCEPTION USING errcode='23000',message='CLOUD_RESTORE_POST_INTEGRITY_RELATIONSHIP_HASH_MISMATCH';
  END IF;
  v_phase_ms:=(extract(epoch FROM clock_timestamp()-v_phase_started_at)*1000)::bigint;
  v_phase_timings:=v_phase_timings||jsonb_build_object('integrity',v_phase_ms);

  v_phase:='commit';v_phase_started_at:=clock_timestamp();
  UPDATE public.erp_cloud_restore_epoch SET epoch=epoch+1,restored_at=now(),restored_by=v_actor,
    snapshot_fingerprint=v_proof.prepared_payload_hash WHERE singleton=true RETURNING epoch INTO v_epoch;
  v_phase_timings:=v_phase_timings||jsonb_build_object('commit',
    (extract(epoch FROM clock_timestamp()-v_phase_started_at)*1000)::bigint,
    'total',(extract(epoch FROM clock_timestamp()-v_started_at)*1000)::bigint);
  v_result:=jsonb_build_object(
    'ok',true,'replayed',false,'idempotencyKey',p_idempotency_key,
    'snapshotFingerprint',p_snapshot_fingerprint,'serverSnapshotFingerprint',v_proof.prepared_payload_hash,
    'rollbackSnapshotId',v_rollback_id,'restoreEpoch',v_epoch,'manifest',p_manifest,
    'serverRelationshipHash',v_actual_relationship_hash,'timingsMs',v_phase_timings,
    'executeModel','typed-staged-generation-v2','recoveryEvidenceKind','SOURCE_GENERATION'
  );
  UPDATE public.erp_cloud_restore_requests SET status='completed',rollback_snapshot_id=v_rollback_id,
    canonical_result=v_result,completed_at=now() WHERE actor_id=v_actor AND idempotency_key=p_idempotency_key;
  RETURN v_result;
EXCEPTION WHEN query_canceled THEN
  RAISE LOG 'CLOUD_RESTORE_STAGED_TIMING phase=failure failed_phase=% classification=statement_timeout total_ms=%',
    v_phase,(extract(epoch FROM clock_timestamp()-v_started_at)*1000)::bigint;
  RAISE;
WHEN OTHERS THEN
  RAISE LOG 'CLOUD_RESTORE_STAGED_TIMING phase=failure failed_phase=% sqlstate=% total_ms=%',
    v_phase,SQLSTATE,(extract(epoch FROM clock_timestamp()-v_started_at)*1000)::bigint;
  RAISE;
END;
$function$

public.erp_prove_cloud_restore_candidate.definition:
CREATE OR REPLACE FUNCTION public.erp_prove_cloud_restore_candidate_v2(p_source_snapshot jsonb, p_manifest jsonb, p_restore_mode text, p_source_environment text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();
  v_actor_key text;
  v_effective jsonb;
  v_audit jsonb;
  v_integrity jsonb;
  v_result jsonb;
  v_stage jsonb;
  v_proof_id uuid:=gen_random_uuid();
  v_expires_at timestamptz:=clock_timestamp()+interval '30 minutes';
  v_policy text;
  v_source_fingerprint text;
  v_effective_fingerprint text;
  v_restore_relationship_hash text;
  v_transformed bigint:=0;
  v_started_at timestamptz:=clock_timestamp();
  v_headers jsonb;
  v_source_generation bigint; v_source_epoch bigint;
  v_phase_started timestamptz:=clock_timestamp(); v_prepare_timings jsonb:='{}';
BEGIN
  RAISE LOG 'CLOUD_RESTORE_TRANSPORT request=% rpc=PROOF event=db-entry',p_request_id;
  IF v_actor IS NULL THEN RAISE EXCEPTION USING errcode='42501',message='AUTHENTICATION_REQUIRED'; END IF;
  IF NOT public.is_owner(v_actor) THEN RAISE EXCEPTION USING errcode='42501',message='CLOUD_RESTORE_OWNER_REQUIRED'; END IF;
  IF p_request_id IS NULL OR coalesce(length(p_source_environment),0) NOT BETWEEN 1 AND 2048
     OR jsonb_typeof(p_source_snapshot) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_manifest) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_INPUT_INVALID';
  END IF;
  v_headers:=nullif(current_setting('request.headers',true),'')::jsonb;
  IF lower(split_part(coalesce(v_headers->>'host',''),':',1)) NOT LIKE 'rhfdjsklfrgpoqsaqpkn.%'
     OR (v_headers->>'x-restore-request-id' IS NOT NULL AND v_headers->>'x-restore-request-id'<>p_request_id::text) THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_TARGET_MISMATCH';
  END IF;

  IF p_restore_mode='cross-environment' THEN
    IF jsonb_typeof(p_manifest->'portability') IS DISTINCT FROM 'object'
       OR p_manifest->'portability'->>'policyVersion'<>'cross-environment-audit-null-v1'
       OR p_manifest->'portability'->>'targetProjectRef'<>'rhfdjsklfrgpoqsaqpkn' THEN
      RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_POLICY_INVALID';
    END IF;
    v_policy:='cross-environment-audit-null-v1';
    v_source_fingerprint:=p_manifest->'portability'->>'sourceSnapshotFingerprint';
    v_transformed:=(p_manifest->'portability'->>'totalTransformedRows')::bigint;
  ELSIF p_restore_mode='strict' AND NOT (p_manifest ? 'portability') THEN
    v_policy:='strict';
    v_source_fingerprint:=p_manifest->>'snapshotFingerprint';
  ELSE
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_POLICY_INVALID';
  END IF;
  v_effective_fingerprint:=p_manifest->>'snapshotFingerprint';
  IF coalesce(v_source_fingerprint,'') !~ '^[0-9a-f]{64}$' OR coalesce(v_effective_fingerprint,'') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_FINGERPRINT_INVALID';
  END IF;
  SELECT generation INTO STRICT v_source_generation FROM public.erp_restore_business_generation WHERE singleton;
  SELECT epoch INTO STRICT v_source_epoch FROM public.erp_cloud_restore_epoch WHERE singleton;
  v_prepare_timings:=jsonb_build_object('auth',(extract(epoch FROM clock_timestamp()-v_started_at)*1000)::bigint);
  v_phase_started:=clock_timestamp();
  v_effective:=public.erp_cloud_restore_build_effective_snapshot(p_source_snapshot,p_manifest,p_restore_mode);
  IF p_restore_mode='cross-environment' THEN
    PERFORM public.erp_cloud_restore_validate_portability(v_effective,p_manifest,'rhfdjsklfrgpoqsaqpkn');
  END IF;
  PERFORM public.erp_cloud_restore_validate_waca_dataset(v_effective);
  v_audit:=public.erp_cloud_restore_audit_dataset(v_effective);
  v_integrity:=v_audit->'integrity';
  v_restore_relationship_hash:=public.erp_cloud_restore_relationship_hash(v_effective);
  IF (SELECT count(*) FROM jsonb_object_keys(v_audit->'table_counts'))<>24
     OR p_manifest->>'resourceCount'<>'24'
     OR p_manifest->'counts' IS DISTINCT FROM v_audit->'table_counts'
     OR (p_manifest->>'totalRows')::bigint IS DISTINCT FROM (v_audit->>'total_rows')::bigint
     OR p_manifest->>'relationshipHash' IS DISTINCT FROM v_audit->>'relationship_hash'
     OR (p_manifest->>'orphanCount')::bigint IS DISTINCT FROM (v_integrity->>'orphan_count')::bigint
     OR (p_manifest->>'duplicateVariantIdCount')::bigint IS DISTINCT FROM (v_integrity->>'duplicate_variant_id_count')::bigint
     OR (p_manifest->>'duplicateVariantLocalIdCount')::bigint IS DISTINCT FROM (v_integrity->>'duplicate_variant_local_id_count')::bigint
     OR (p_manifest->>'duplicateCanonicalIdCount')::bigint IS DISTINCT FROM (v_integrity->>'duplicate_canonical_id_count')::bigint
     OR (p_manifest->>'canonicalIdentityAnomalyCount')::bigint IS DISTINCT FROM (v_integrity->>'canonical_identity_anomaly_count')::bigint
     OR (p_manifest->>'unknownProductCount')::bigint IS DISTINCT FROM (v_integrity->>'unknown_product_count')::bigint
     OR (p_manifest->>'optionalMetadataMissingReferenceCount')::bigint IS DISTINCT FROM (v_integrity->>'optional_metadata_missing_reference_count')::bigint
     OR (v_integrity->>'duplicate_inventory_key_count')::bigint<>0
     OR (v_integrity->>'missing_inventory_key_count')::bigint<>0 THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_CANDIDATE_INVALID';
  END IF;
  v_prepare_timings:=v_prepare_timings||jsonb_build_object('semanticProof',(extract(epoch FROM clock_timestamp()-v_phase_started)*1000)::bigint);
  v_phase_started:=clock_timestamp();
  v_actor_key:=encode(extensions.digest(v_actor::text,'sha256'),'hex');
  -- Expired OPS are handled exclusively by bounded maintenance.
  v_result:=jsonb_build_object(
    'ok',true,'candidate_valid',true,'schema_version','cloud-restore-candidate-proof-v1','policy',v_policy,
    'resource_count',24,'coverage_count',24,'total_rows',(v_audit->>'total_rows')::bigint,
    'table_counts',v_audit->'table_counts','transformed_updated_by_count',v_transformed,
    'source_fingerprint',v_source_fingerprint,'effective_fingerprint',v_effective_fingerprint,
    'relationship_hash',v_audit->>'relationship_hash','integrity',v_integrity
  );
  INSERT INTO public.erp_cloud_restore_candidate_proofs(
    proof_id,actor_key,source_fingerprint,effective_fingerprint,restore_policy,target_environment,
    restore_mode,source_environment,effective_snapshot,manifest,proof_result,expires_at,
    expected_relationship_hash
  ) VALUES(
    v_proof_id,v_actor_key,v_source_fingerprint,v_effective_fingerprint,v_policy,'rhfdjsklfrgpoqsaqpkn',
    p_restore_mode,p_source_environment,'{}'::jsonb,p_manifest,v_result,v_expires_at,v_restore_relationship_hash
  );
  v_stage:=public.erp_cloud_restore_stage_candidate(v_proof_id,v_actor_key,v_effective,v_expires_at);
  IF (v_stage->>'rowCount')::bigint IS DISTINCT FROM (v_audit->>'total_rows')::bigint THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_STAGE_ROW_COUNT_MISMATCH';
  END IF;
  UPDATE public.erp_cloud_restore_candidate_proofs SET
    expected_profiles=v_stage->'profiles',prepared_row_count=(v_stage->>'rowCount')::bigint,
    prepared_byte_count=(v_stage->>'byteCount')::bigint,prepared_payload_hash=v_stage->>'payloadHash'
  WHERE proof_id=v_proof_id;
  IF v_source_generation IS DISTINCT FROM (SELECT generation FROM public.erp_restore_business_generation WHERE singleton)
     OR v_source_epoch IS DISTINCT FROM (SELECT epoch FROM public.erp_cloud_restore_epoch WHERE singleton) THEN
    RAISE EXCEPTION USING errcode='55000',message='STALE_RESTORE_PREPARE';
  END IF;
  UPDATE public.erp_cloud_restore_candidate_proofs SET source_generation=v_source_generation,source_restore_epoch=v_source_epoch
    WHERE proof_id=v_proof_id;
  v_prepare_timings:=v_prepare_timings||jsonb_build_object('decodeAndStage',(extract(epoch FROM clock_timestamp()-v_phase_started)*1000)::bigint);
  v_result:=v_result||jsonb_build_object('prepareTimingsMs',v_prepare_timings,
    'proof_id',v_proof_id,'proof_expires_at',v_expires_at,'request_id',p_request_id,
    'elapsed_ms',(extract(epoch FROM clock_timestamp()-v_started_at)*1000)::bigint,
    'prepared_row_count',(v_stage->>'rowCount')::bigint,
    'prepared_byte_count',(v_stage->>'byteCount')::bigint,
    'prepared_payload_hash',v_stage->>'payloadHash'
  );
  UPDATE public.erp_cloud_restore_candidate_proofs SET proof_result=v_result WHERE proof_id=v_proof_id;
  RAISE LOG 'CLOUD_RESTORE_TRANSPORT request=% rpc=PROOF proof=% event=db-complete',p_request_id,v_proof_id;
  RETURN v_result;
END;
$function$

public.erp_restore_proven_cloud_snapshot.definition:
CREATE OR REPLACE FUNCTION public.erp_restore_proven_cloud_snapshot_attempt(p_attempt_id uuid, p_trace_id uuid, p_execution_id uuid, p_proof_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();v_actor_key text;
  v_attempt public.erp_cloud_restore_attempts%rowtype;
  v_proof public.erp_cloud_restore_candidate_proofs%rowtype;
  v_result jsonb;v_epoch bigint;v_phase text:='PREPARING';v_state text;v_message text;v_category text;
  v_headers jsonb;
BEGIN
  RAISE LOG 'CLOUD_RESTORE_TRANSPORT request=% attempt=% trace=% execution=% rpc=EXECUTE event=db-entry',
    p_request_id,p_attempt_id,p_trace_id,p_execution_id;
  IF v_actor IS NULL THEN RAISE EXCEPTION USING errcode='42501',message='AUTHENTICATION_REQUIRED'; END IF;
  IF NOT public.is_owner(v_actor) THEN RAISE EXCEPTION USING errcode='42501',message='CLOUD_RESTORE_OWNER_REQUIRED'; END IF;
  IF p_execution_id IS NULL OR p_proof_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_EXECUTION_ID_REQUIRED';
  END IF;
  v_headers:=nullif(current_setting('request.headers',true),'')::jsonb;
  IF v_headers->>'x-restore-request-id' IS NOT NULL AND v_headers->>'x-restore-request-id'<>p_request_id::text THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_REQUEST_CORRELATION_MISMATCH';
  END IF;
  v_actor_key:=encode(extensions.digest(v_actor::text,'sha256'),'hex');
  IF NOT pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-attempt:'||p_attempt_id::text,0)) THEN
    RAISE EXCEPTION USING errcode='55006',message='CLOUD_RESTORE_ATTEMPT_EXECUTION_CONFLICT';
  END IF;
  SELECT * INTO v_attempt FROM public.erp_cloud_restore_attempts
   WHERE attempt_id=p_attempt_id AND trace_id=p_trace_id AND actor_key=v_actor_key FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_ATTEMPT_NOT_FOUND'; END IF;
  IF v_attempt.status='completed' THEN RETURN v_attempt.canonical_result||jsonb_build_object('replayed',true); END IF;
  IF v_attempt.status='not_committed' THEN
    v_result:=public.erp_cloud_restore_failure_result(p_attempt_id);IF v_result IS NOT NULL THEN RETURN v_result;END IF;
  END IF;
  SELECT * INTO v_proof FROM public.erp_cloud_restore_candidate_proofs
   WHERE proof_id=p_proof_id AND actor_key=v_actor_key FOR UPDATE;
  IF NOT FOUND OR v_proof.expires_at<=clock_timestamp() THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_PROOF_NOT_FOUND';
  END IF;
  IF v_attempt.source_fingerprint IS DISTINCT FROM v_proof.source_fingerprint
     OR v_attempt.effective_fingerprint IS DISTINCT FROM v_proof.effective_fingerprint
     OR v_attempt.restore_policy IS DISTINCT FROM v_proof.restore_policy
     OR v_attempt.target_environment IS DISTINCT FROM v_proof.target_environment
     OR v_proof.effective_fingerprint IS DISTINCT FROM v_proof.manifest->>'snapshotFingerprint' THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_ATTEMPT_PAYLOAD_MISMATCH';
  END IF;
  IF v_attempt.status='prepared' THEN
    UPDATE public.erp_cloud_restore_attempts SET status='executing',execution_id=p_execution_id,
      execution_started_at=clock_timestamp() WHERE attempt_id=p_attempt_id;
  ELSIF v_attempt.status<>'executing' OR v_attempt.execution_id IS DISTINCT FROM p_execution_id THEN
    RAISE EXCEPTION USING errcode='55006',message='CLOUD_RESTORE_ATTEMPT_NOT_EXECUTABLE';
  END IF;
  IF NOT pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) THEN
    RAISE EXCEPTION USING errcode='55006',message='CLOUD_RESTORE_LOCK_CONFLICT';
  END IF;
  BEGIN
    SELECT epoch INTO STRICT v_epoch FROM public.erp_cloud_restore_epoch WHERE singleton=true;
    IF v_epoch IS DISTINCT FROM v_attempt.expected_epoch THEN
      RAISE EXCEPTION USING errcode='55000',message='CLOUD_RESTORE_ATTEMPT_EPOCH_MISMATCH';
    END IF;
    v_phase:='ATOMIC_RESTORE';
    v_result:=public.erp_restore_staged_cloud_snapshot(
      p_attempt_id,p_proof_id,v_proof.effective_fingerprint,v_proof.manifest,v_proof.source_environment
    );
    v_phase:='FINAL_VALIDATION';
    IF v_result->>'ok' IS DISTINCT FROM 'true'
       OR (v_result->>'restoreEpoch')::bigint IS DISTINCT FROM v_attempt.expected_epoch+1 THEN
      RAISE EXCEPTION USING errcode='XX000',message='CLOUD_RESTORE_CANONICAL_RESULT_INVALID';
    END IF;
    UPDATE public.erp_cloud_restore_attempts SET status='completed',completed_at=clock_timestamp(),
      result_epoch=(v_result->>'restoreEpoch')::bigint,canonical_result=v_result WHERE attempt_id=p_attempt_id;
    DELETE FROM public.erp_cloud_restore_candidate_proofs WHERE proof_id=p_proof_id;
    RETURN v_result;
  EXCEPTION WHEN query_canceled OR OTHERS THEN
    GET STACKED DIAGNOSTICS v_state=RETURNED_SQLSTATE,v_message=MESSAGE_TEXT;
    v_category:=public.erp_cloud_restore_failure_category(v_state,v_message);
  END;
  DELETE FROM public.erp_cloud_restore_candidate_proofs WHERE proof_id=p_proof_id;
  INSERT INTO public.erp_cloud_restore_failures(
    attempt_id,trace_id,execution_id,phase,category,code,sqlstate,timeout_classification,evidence
  ) VALUES(
    p_attempt_id,p_trace_id,p_execution_id,
    CASE WHEN v_phase='FINAL_VALIDATION' THEN 'canonical-result' ELSE 'atomic-restore' END,
    v_category,'CLOUD_RESTORE_FAILURE_'||v_category,v_state,
    CASE WHEN v_state='57014' THEN 'query-canceled' ELSE 'not-timeout' END,'caught-subtransaction'
  );
  UPDATE public.erp_cloud_restore_attempts SET status='not_committed',reconciled_at=clock_timestamp()
   WHERE attempt_id=p_attempt_id;
  RETURN public.erp_cloud_restore_failure_result(p_attempt_id);
END;
$function$

public.erp_restore_cloud_snapshot_effect.definition:
CREATE OR REPLACE FUNCTION public.erp_restore_cloud_snapshot_effective(p_idempotency_key uuid, p_snapshot_fingerprint text, p_source_snapshot jsonb, p_manifest jsonb, p_source_environment text, p_restore_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
declare
  v_effective_snapshot jsonb;
  v_started_at timestamptz := clock_timestamp();
  v_policy text := coalesce(p_manifest->'portability'->>'policyVersion', 'strict');
  v_target text := coalesce(p_manifest->'portability'->>'targetProjectRef', 'same-environment');
  v_source_fingerprint text := coalesce(p_manifest->'portability'->>'sourceSnapshotFingerprint', p_snapshot_fingerprint);
begin
  if p_snapshot_fingerprint !~ '^[0-9a-f]{64}$'
     or p_snapshot_fingerprint is distinct from p_manifest->>'snapshotFingerprint' then
    raise exception using errcode = '22023', message = 'CLOUD_RESTORE_EFFECTIVE_FINGERPRINT_MISMATCH';
  end if;

  v_effective_snapshot := public.erp_cloud_restore_build_effective_snapshot(
    p_source_snapshot,
    p_manifest,
    p_restore_mode
  );

  return public.erp_restore_cloud_snapshot(
    p_idempotency_key,
    p_snapshot_fingerprint,
    v_effective_snapshot,
    p_manifest,
    p_source_environment
  );
exception
  when query_canceled then
    raise log 'CLOUD_RESTORE_EFFECTIVE_FAILURE attempt=% classification=statement_timeout timeout_source=postgresql_statement_timeout sqlstate=% elapsed_ms=% policy=% target=% source_fingerprint=% effective_fingerprint=%',
      p_idempotency_key, sqlstate,
      (extract(epoch from clock_timestamp() - v_started_at) * 1000)::bigint,
      v_policy, v_target, v_source_fingerprint, p_snapshot_fingerprint;
    raise;
  when others then
    raise log 'CLOUD_RESTORE_EFFECTIVE_FAILURE attempt=% classification=server_error timeout_source=none sqlstate=% elapsed_ms=% policy=% target=% source_fingerprint=% effective_fingerprint=%',
      p_idempotency_key, sqlstate,
      (extract(epoch from clock_timestamp() - v_started_at) * 1000)::bigint,
      v_policy, v_target, v_source_fingerprint, p_snapshot_fingerprint;
    raise;
end;
$function$

public.erp_cloud_restore_stage_candidate.definition:
CREATE OR REPLACE FUNCTION public.erp_cloud_restore_stage_candidate(p_proof_id uuid, p_actor_key text, p_effective_snapshot jsonb, p_expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE v_resource text;v_resource_rows jsonb;v_profile jsonb;v_profiles jsonb:='{}';
 v_total_rows bigint:=0;v_total_bytes bigint:=0;v_payload_hash text;
 v_columns text;v_select_columns text;v_columns_by_resource jsonb:='{}';
BEGIN
 IF p_actor_key !~ '^[0-9a-f]{64}$' OR p_expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_STAGE_IDENTITY_INVALID'; END IF;
 DELETE FROM public.erp_cloud_restore_prepared_chunks WHERE proof_id=p_proof_id;
 FOREACH v_resource IN ARRAY ARRAY[
  'inventory_items','product_groups','product_categories','product_variants','bundle_components',
  'purchase_batches','purchase_batch_items','private_orders','private_order_items','sales_orders','sales_order_items',
  'japan_packages','japan_package_items','outbound_shipments','outbound_shipment_items','dashboard_category_images','import_batches',
  'waca_orders','waca_order_items','waca_mappings','waca_master_links','waca_import_batches','waca_cutover_audit','waca_state'
 ] LOOP
  v_resource_rows:=p_effective_snapshot->v_resource;
  IF jsonb_typeof(v_resource_rows) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_RESOURCE_REQUIRED:'||v_resource; END IF;
  INSERT INTO public.erp_cloud_restore_prepared_chunks(
   proof_id,actor_key,resource,chunk_ordinal,row_count,rows,payload_hash,expires_at
  )
  WITH grouped AS (
   SELECT ((ordinality-1)/256)::integer chunk_ordinal,count(*)::integer row_count,
    json_agg(row_value ORDER BY ordinality)::jsonb rows
   FROM jsonb_array_elements(v_resource_rows) WITH ORDINALITY source(row_value,ordinality)
   WHERE CASE WHEN jsonb_typeof(row_value)='object' THEN true
    ELSE public.erp_cloud_restore_reject_invalid_portable_row(v_resource) END
   GROUP BY ((ordinality-1)/256)::integer
  )
  SELECT p_proof_id,p_actor_key,v_resource,chunk_ordinal,row_count,rows,
   encode(extensions.digest(convert_to(rows::text,'UTF8'),'sha256'),'hex'),p_expires_at FROM grouped;

  -- One exact union of supplied keys across ALL rows, including fields first
  -- supplied in a later row. Never infer columns from only the first row.
  WITH supplied_columns AS MATERIALIZED (
   SELECT DISTINCT supplied.key FROM jsonb_array_elements(v_resource_rows) row_value
    CROSS JOIN LATERAL jsonb_object_keys(row_value) supplied(key)
  )
  SELECT string_agg(quote_ident(a.attname),',' ORDER BY a.attnum),
   string_agg('r.'||quote_ident(a.attname),',' ORDER BY a.attnum)
  INTO v_columns,v_select_columns FROM pg_attribute a
   JOIN supplied_columns supplied ON supplied.key=a.attname
  WHERE a.attrelid=format('public.%I',v_resource)::regclass AND a.attnum>0
   AND NOT a.attisdropped AND a.attgenerated='';
  IF v_columns IS NOT NULL THEN
   EXECUTE format('insert into public.%I (restore_proof_id,%s) select $1,%s from jsonb_populate_recordset(null::public.%I,$2) r',
    'erp_restore_stage_'||v_resource,v_columns,v_select_columns,v_resource)
    USING p_proof_id,v_resource_rows;
  END IF;
  v_columns_by_resource:=v_columns_by_resource||jsonb_build_object(v_resource,v_columns);
  v_profile:=public.erp_cloud_restore_prepared_profile(p_proof_id,v_resource);
  IF (v_profile->>'missingIdentityCount')::bigint>0 THEN
   RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_IDENTITY_REQUIRED:'||v_resource; END IF;
  IF (v_profile->>'duplicateIdentityCount')::bigint>0 THEN
   RAISE EXCEPTION USING errcode='23505',message='DUPLICATE_CANONICAL_ID:'||v_resource; END IF;
  IF v_resource='product_variants' AND (v_profile->>'duplicateAuxiliaryIdentityCount')::bigint>0 THEN
   RAISE EXCEPTION USING errcode='23505',message='DUPLICATE_VARIANT_LOCAL_ID'; END IF;
  v_profiles:=v_profiles||jsonb_build_object(v_resource,v_profile);
  v_total_rows:=v_total_rows+(v_profile->>'count')::bigint;
 END LOOP;
 SELECT coalesce(sum(pg_column_size(rows)),0),
  encode(extensions.digest(convert_to(coalesce(string_agg(resource||':'||chunk_ordinal::text||':'||payload_hash,E'\n'
   ORDER BY resource COLLATE "C",chunk_ordinal),''),'UTF8'),'sha256'),'hex')
 INTO v_total_bytes,v_payload_hash FROM public.erp_cloud_restore_prepared_chunks WHERE proof_id=p_proof_id;
 UPDATE public.erp_cloud_restore_candidate_proofs SET prepared_columns=v_columns_by_resource WHERE proof_id=p_proof_id;
 RETURN jsonb_build_object('profiles',v_profiles,'rowCount',v_total_rows,'byteCount',v_total_bytes,'payloadHash',v_payload_hash);
END;
$function$

public.erp_prepare_cloud_restore_attempt.definition:
CREATE OR REPLACE FUNCTION public.erp_prepare_cloud_restore_attempt(p_attempt_id uuid, p_trace_id uuid, p_source_fingerprint text, p_effective_fingerprint text, p_restore_policy text, p_target_environment text, p_timeout_budget_ms integer, p_timeout_contract_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '10s'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();v_actor_key text;v_epoch bigint;
  v_existing public.erp_cloud_restore_attempts%rowtype;v_headers jsonb;v_host text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION USING errcode='42501',message='AUTHENTICATION_REQUIRED'; END IF;
  IF NOT public.is_owner(v_actor) THEN RAISE EXCEPTION USING errcode='42501',message='CLOUD_RESTORE_OWNER_REQUIRED'; END IF;
  IF p_attempt_id IS NULL OR p_trace_id IS NULL
     OR p_source_fingerprint !~ '^[0-9a-f]{64}$' OR p_effective_fingerprint !~ '^[0-9a-f]{64}$'
     OR p_restore_policy NOT IN ('strict','cross-environment-audit-null-v1')
     OR p_target_environment IS DISTINCT FROM 'rhfdjsklfrgpoqsaqpkn'
     OR p_timeout_budget_ms IS DISTINCT FROM 120000
     OR p_timeout_contract_version IS DISTINCT FROM 'postgresql-statement-timeout-v1' THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_ATTEMPT_INVALID';
  END IF;
  v_headers:=nullif(current_setting('request.headers',true),'')::jsonb;
  v_host:=lower(split_part(coalesce(v_headers->>'host',''),':',1));
  IF split_part(v_host,'.',1) IS DISTINCT FROM p_target_environment THEN
    RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_ATTEMPT_TARGET_MISMATCH';
  END IF;
  v_actor_key:=encode(extensions.digest(v_actor::text,'sha256'),'hex');
  SELECT epoch INTO STRICT v_epoch FROM public.erp_cloud_restore_epoch WHERE singleton=true;
  SELECT * INTO v_existing FROM public.erp_cloud_restore_attempts
   WHERE attempt_id=p_attempt_id AND actor_key=v_actor_key;
  IF FOUND THEN
    IF v_existing.trace_id IS DISTINCT FROM p_trace_id
       OR v_existing.source_fingerprint IS DISTINCT FROM p_source_fingerprint
       OR v_existing.effective_fingerprint IS DISTINCT FROM p_effective_fingerprint
       OR v_existing.restore_policy IS DISTINCT FROM p_restore_policy
       OR v_existing.target_environment IS DISTINCT FROM p_target_environment
       OR v_existing.timeout_budget_ms IS DISTINCT FROM p_timeout_budget_ms
       OR v_existing.timeout_contract_version IS DISTINCT FROM p_timeout_contract_version THEN
      RAISE EXCEPTION USING errcode='22023',message='CLOUD_RESTORE_ATTEMPT_PAYLOAD_MISMATCH';
    END IF;
    RETURN jsonb_build_object(
      'status',v_existing.status,'attemptId',v_existing.attempt_id,'traceId',v_existing.trace_id,
      'expectedEpoch',v_existing.expected_epoch,'effectiveFingerprint',v_existing.effective_fingerprint,
      'reconcileAfter',v_existing.submitted_at+(v_existing.timeout_budget_ms+v_existing.grace_ms)*interval '1 millisecond',
      'resultEpoch',v_existing.result_epoch,'restoreResult',v_existing.canonical_result
    );
  END IF;
  BEGIN
    INSERT INTO public.erp_cloud_restore_attempts(
      attempt_id,trace_id,actor_key,source_fingerprint,effective_fingerprint,restore_policy,
      target_environment,expected_epoch,timeout_budget_ms,timeout_contract_version,status
    ) VALUES(
      p_attempt_id,p_trace_id,v_actor_key,p_source_fingerprint,p_effective_fingerprint,p_restore_policy,
      p_target_environment,v_epoch,p_timeout_budget_ms,p_timeout_contract_version,'prepared'
    ) RETURNING * INTO v_existing;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION USING errcode='55006',message='CLOUD_RESTORE_ATTEMPT_PENDING';
  END;
  RETURN jsonb_build_object(
    'status','prepared','attemptId',v_existing.attempt_id,'traceId',v_existing.trace_id,
    'expectedEpoch',v_existing.expected_epoch,'effectiveFingerprint',v_existing.effective_fingerprint,
    'reconcileAfter',v_existing.submitted_at+(v_existing.timeout_budget_ms+v_existing.grace_ms)*interval '1 millisecond'
  );
END;
$function$

public.erp_restore_cloud_snapshot_attemp.definition:
CREATE OR REPLACE FUNCTION public.erp_restore_cloud_snapshot_attempt(p_attempt_id uuid, p_trace_id uuid, p_execution_id uuid, p_snapshot_fingerprint text, p_source_snapshot jsonb, p_manifest jsonb, p_source_environment text, p_restore_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET statement_timeout TO '120s'
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_attempt public.erp_cloud_restore_attempts%rowtype;
  v_effective jsonb;
  v_result jsonb;
  v_epoch bigint;
  v_phase text:='PREPARING';
  v_phase_started timestamptz:=clock_timestamp();
  v_state text;
  v_message text;
  v_category text;
begin
  raise log 'CLOUD_RESTORE_ATTEMPT_PHASE attempt=% trace=% execution=% phase=% event=start',
    p_attempt_id,p_trace_id,p_execution_id,v_phase;
  if v_actor is null then raise exception using errcode='42501',message='AUTHENTICATION_REQUIRED'; end if;
  if not public.is_owner(v_actor) then raise exception using errcode='42501',message='CLOUD_RESTORE_OWNER_REQUIRED'; end if;
  if p_execution_id is null then
    raise exception using errcode='22023',message='CLOUD_RESTORE_EXECUTION_ID_REQUIRED';
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-attempt:'||p_attempt_id::text,0)) then
    raise exception using errcode='55006',message='CLOUD_RESTORE_ATTEMPT_EXECUTION_CONFLICT';
  end if;
  select * into v_attempt from public.erp_cloud_restore_attempts
    where attempt_id=p_attempt_id and trace_id=p_trace_id
      and actor_key=encode(digest(v_actor::text,'sha256'),'hex') for update;
  if not found then raise exception using errcode='22023',message='CLOUD_RESTORE_ATTEMPT_NOT_FOUND'; end if;
  if v_attempt.status='completed' then return v_attempt.canonical_result||jsonb_build_object('replayed',true); end if;
  if v_attempt.status='not_committed' then
    v_result:=public.erp_cloud_restore_failure_result(p_attempt_id);
    if v_result is not null then return v_result; end if;
  end if;

  -- New clients arrive with a prepared envelope and a client-generated
  -- execution id. This state transition intentionally shares the destructive
  -- transaction: whole-request cancellation rolls it back to prepared.
  if v_attempt.status='prepared' then
    if clock_timestamp()>=v_attempt.submitted_at
       +(v_attempt.timeout_budget_ms+v_attempt.grace_ms)*interval '1 millisecond' then
      raise exception using errcode='55006',message='CLOUD_RESTORE_ATTEMPT_PENDING';
    end if;
    update public.erp_cloud_restore_attempts
       set status='executing',execution_id=p_execution_id,execution_started_at=clock_timestamp()
     where attempt_id=p_attempt_id;
    v_attempt.status:='executing';
    v_attempt.execution_id:=p_execution_id;
    v_attempt.execution_started_at:=clock_timestamp();
  elsif v_attempt.status='executing' then
    -- Backward compatibility for the 038/041 client that called BEGIN first.
    if v_attempt.execution_id is distinct from p_execution_id then
      raise exception using errcode='55006',message='CLOUD_RESTORE_ATTEMPT_NOT_EXECUTABLE';
    end if;
    if clock_timestamp()>=v_attempt.execution_started_at
       +(v_attempt.timeout_budget_ms+v_attempt.grace_ms)*interval '1 millisecond' then
      raise exception using errcode='55006',message='CLOUD_RESTORE_ATTEMPT_PENDING';
    end if;
  else
    raise exception using errcode='55006',message='CLOUD_RESTORE_ATTEMPT_NOT_EXECUTABLE';
  end if;

  if not pg_try_advisory_xact_lock(hashtextextended('erp-cloud-restore-maintenance-lock',0)) then
    raise exception using errcode='55006',message='CLOUD_RESTORE_LOCK_CONFLICT';
  end if;
  raise log 'CLOUD_RESTORE_ATTEMPT_PHASE attempt=% trace=% execution=% phase=PREPARING event=complete duration_ms=%',
    p_attempt_id,p_trace_id,p_execution_id,
    (extract(epoch from clock_timestamp()-v_phase_started)*1000)::bigint;

  -- This exception block is the atomic business subtransaction. All business
  -- writes roll back before the outer failure envelope is written.
  begin
    if v_attempt.effective_fingerprint is distinct from p_snapshot_fingerprint
       or v_attempt.source_fingerprint is distinct from coalesce(p_manifest->'portability'->>'sourceSnapshotFingerprint',p_snapshot_fingerprint)
       or v_attempt.restore_policy is distinct from coalesce(p_manifest->'portability'->>'policyVersion','strict')
       or v_attempt.target_environment is distinct from coalesce(p_manifest->'portability'->>'targetProjectRef','rhfdjsklfrgpoqsaqpkn')
       or p_snapshot_fingerprint is distinct from p_manifest->>'snapshotFingerprint' then
      raise exception using errcode='22023',message='CLOUD_RESTORE_ATTEMPT_PAYLOAD_MISMATCH';
    end if;
    select epoch into strict v_epoch from public.erp_cloud_restore_epoch where singleton=true;
    if v_epoch is distinct from v_attempt.expected_epoch then
      raise exception using errcode='55000',message='CLOUD_RESTORE_ATTEMPT_EPOCH_MISMATCH';
    end if;

    v_phase:='BUILDING_EFFECTIVE_SNAPSHOT'; v_phase_started:=clock_timestamp();
    raise log 'CLOUD_RESTORE_ATTEMPT_PHASE attempt=% trace=% execution=% phase=% event=start',
      p_attempt_id,p_trace_id,p_execution_id,v_phase;
    v_effective:=public.erp_cloud_restore_build_effective_snapshot(p_source_snapshot,p_manifest,p_restore_mode);
    raise log 'CLOUD_RESTORE_ATTEMPT_PHASE attempt=% trace=% execution=% phase=% event=complete duration_ms=%',
      p_attempt_id,p_trace_id,p_execution_id,v_phase,
      (extract(epoch from clock_timestamp()-v_phase_started)*1000)::bigint;

    -- erp_restore_cloud_snapshot already emits bounded phase timings for input
    -- validation, rollback snapshot, delete, insert, final integrity and epoch.
    -- The global maintenance lock makes these records unambiguous; this outer
    -- record adds attempt/trace/execution correlation without storing payload.
    v_phase:='ATOMIC_RESTORE'; v_phase_started:=clock_timestamp();
    raise log 'CLOUD_RESTORE_ATTEMPT_PHASE attempt=% trace=% execution=% phase=% event=start',
      p_attempt_id,p_trace_id,p_execution_id,v_phase;
    v_result:=public.erp_restore_cloud_snapshot(p_attempt_id,p_snapshot_fingerprint,v_effective,p_manifest,p_source_environment);
    raise log 'CLOUD_RESTORE_ATTEMPT_PHASE attempt=% trace=% execution=% phase=% event=complete duration_ms=%',
      p_attempt_id,p_trace_id,p_execution_id,v_phase,
      (extract(epoch from clock_timestamp()-v_phase_started)*1000)::bigint;

    v_phase:='FINAL_VALIDATION'; v_phase_started:=clock_timestamp();
    if v_result->>'ok' is distinct from 'true'
       or (v_result->>'restoreEpoch')::bigint is distinct from v_attempt.expected_epoch+1 then
      raise exception using errcode='XX000',message='CLOUD_RESTORE_CANONICAL_RESULT_INVALID';
    end if;
    raise log 'CLOUD_RESTORE_ATTEMPT_PHASE attempt=% trace=% execution=% phase=% event=complete duration_ms=%',
      p_attempt_id,p_trace_id,p_execution_id,v_phase,
      (extract(epoch from clock_timestamp()-v_phase_started)*1000)::bigint;

    v_phase:='COMMITTING'; v_phase_started:=clock_timestamp();
    update public.erp_cloud_restore_attempts set status='completed',completed_at=clock_timestamp(),
      result_epoch=(v_result->>'restoreEpoch')::bigint,canonical_result=v_result where attempt_id=p_attempt_id;
    raise log 'CLOUD_RESTORE_ATTEMPT_PHASE attempt=% trace=% execution=% phase=COMPLETED event=complete duration_ms=%',
      p_attempt_id,p_trace_id,p_execution_id,
      (extract(epoch from clock_timestamp()-v_phase_started)*1000)::bigint;
    return v_result;
  exception when query_canceled or others then
    get stacked diagnostics v_state=returned_sqlstate,v_message=message_text;
    v_category:=public.erp_cloud_restore_failure_category(v_state,v_message);
  end;

  raise log 'CLOUD_RESTORE_ATTEMPT_PHASE attempt=% trace=% execution=% phase=% event=failure sqlstate=% category=%',
    p_attempt_id,p_trace_id,p_execution_id,v_phase,v_state,v_category;
  insert into public.erp_cloud_restore_failures(
    attempt_id,trace_id,execution_id,phase,category,code,sqlstate,timeout_classification,evidence
  ) values(
    p_attempt_id,p_trace_id,p_execution_id,
    case
      when v_phase='BUILDING_EFFECTIVE_SNAPSHOT' then 'builder'
      when v_phase='FINAL_VALIDATION' or v_phase='COMMITTING' then 'canonical-result'
      else 'atomic-restore'
    end,
    v_category,'CLOUD_RESTORE_FAILURE_'||v_category,v_state,
    case when v_state='57014' then 'query-canceled' else 'not-timeout' end,
    'caught-subtransaction'
  );
  update public.erp_cloud_restore_attempts
     set status='not_committed',reconciled_at=clock_timestamp()
   where attempt_id=p_attempt_id;
  return public.erp_cloud_restore_failure_result(p_attempt_id);
end;
$function$

public.erp_record_schema_migration_event.definition:
CREATE OR REPLACE FUNCTION public.erp_record_schema_migration_event(p_event_type text, p_event_key text, p_source_checksum text, p_source_head text, p_checkpoint text, p_schema_fingerprint_before text, p_schema_fingerprint_after text, p_environment_role text, p_supabase_project_ref text, p_result text, p_metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_actor uuid:=auth.uid(); v_row public.erp_schema_migration_ledger%rowtype;
begin
  if v_actor is null then raise exception using errcode='42501',message='AUTHENTICATION_REQUIRED'; end if;
  if not public.is_owner(v_actor) then raise exception using errcode='42501',message='SCHEMA_LEDGER_OWNER_REQUIRED'; end if;
  if p_event_type not in ('BASELINE_ADOPTED','MIGRATION_APPLIED')
     or p_result not in ('PASS','FAIL') or jsonb_typeof(p_metadata) is distinct from 'object' then
    raise exception using errcode='22023',message='SCHEMA_LEDGER_EVENT_INVALID';
  end if;
  if p_event_type='BASELINE_ADOPTED' and coalesce((p_metadata->>'historicalMigrationExecutionClaimed')::boolean,true) then
    raise exception using errcode='22023',message='BASELINE_ADOPTION_CANNOT_CLAIM_MIGRATION_EXECUTION';
  end if;
  insert into public.erp_schema_migration_ledger(
    event_type,event_key,source_checksum,source_head,checkpoint,schema_fingerprint_before,
    schema_fingerprint_after,environment_role,supabase_project_ref,recorded_by,result,metadata
  ) values(
    p_event_type,p_event_key,p_source_checksum,p_source_head,p_checkpoint,p_schema_fingerprint_before,
    p_schema_fingerprint_after,p_environment_role,p_supabase_project_ref,v_actor,p_result,p_metadata
  ) returning * into v_row;
  return jsonb_build_object('id',v_row.id,'eventType',v_row.event_type,'eventKey',v_row.event_key,
    'recordedAt',v_row.recorded_at,'result',v_row.result);
end;
$function$
